window.SEARCH_INDEX = [{"file":"index.html","page":"Implementing cards in Jigoku","id":"start-order","name":"","signature":"From card text to code","summary":"A card's abilities are written with a builder: a method that names the ability, followed by one call for each part of the card text. Read the card from left to right and write the calls in the same order. Hover a line to see which part of the text it implements.","section":true},{"file":"index.html","page":"Implementing cards in Jigoku","id":"start-anatomy","name":"","signature":"Anatomy of a card file","summary":"Every card is a class in its own file under server/game/cards/, in the folder of its pack (and clan, for newer packs). The file is named after the card in PascalCase: server/game/cards/01-Core/Assassination.ts. The card loader picks up every file in these folders; there is nothing to register.","section":true},{"file":"index.html","page":"Implementing cards in Jigoku","id":"start-map","name":"","signature":"Which method for which card text","summary":"Each kind of ability starts with its own method on the card. They are documented on the ability builder page.","section":true},{"file":"index.html","page":"Implementing cards in Jigoku","id":"start-context","name":"","signature":"The context","summary":"Every callback gets context: the ability being resolved. The fields you will use most:","section":true},{"file":"index.html","page":"Implementing cards in Jigoku","id":"start-timing","name":"","signature":"Timing: costs, targets, effects","summary":"An ability resolves in a fixed order: the player pays its costs, then chooses its targets, then the effects resolve. The builder follows the Rules Reference Guide here, and so should a card's code.","section":true},{"file":"index.html","page":"Implementing cards in Jigoku","id":"start-then","name":"","signature":"Then, if you do, afterwards","summary":"","section":true},{"file":"index.html","page":"Implementing cards in Jigoku","id":"start-if","name":"","signature":"If, if able, otherwise","summary":"","section":true},{"file":"index.html","page":"Implementing cards in Jigoku","id":"start-cancel","name":"","signature":"Cancelling and limits","summary":"","section":true},{"file":"index.html","page":"Implementing cards in Jigoku","id":"start-chat","name":"","signature":"Chat text","summary":"When an ability resolves, the chat says what happened: player1 plays Assassination, losing 3 honor to discard Doji Whisperer. The part after \"to\" comes from the ability (a card ability reads \"uses\", an event \"plays\"; the costs come before \"to\"):","section":true},{"file":"index.html","page":"Implementing cards in Jigoku","id":"start-examples","name":"","signature":"Examples of more complex cards","summary":"","section":true},{"file":"index.html","page":"Implementing cards in Jigoku","id":"start-example-then","name":"","signature":"\"If you do\": Ujiaki's Offer","summary":"","section":true},{"file":"index.html","page":"Implementing cards in Jigoku","id":"start-example-duel","name":"","signature":"A duel: Doji Reiha","summary":"","section":true},{"file":"index.html","page":"Implementing cards in Jigoku","id":"start-example-if-able","name":"","signature":"If able, otherwise: Calling in Favors","summary":"","section":true},{"file":"index.html","page":"Implementing cards in Jigoku","id":"start-example-select","name":"","signature":"A choice before the dash: Hero of Three Trees","summary":"","section":true},{"file":"index.html","page":"Implementing cards in Jigoku","id":"start-example-gained","name":"","signature":"A granted ability: Kagi-nawa","summary":"","section":true},{"file":"index.html","page":"Implementing cards in Jigoku","id":"start-testing","name":"","signature":"Testing a card","summary":"Every card gets a spec in test/server/cards/, mirroring the card's folder: test/server/cards/01-Core/Assassination.spec.js. A spec sets up a game in the state the card needs, plays it, and checks the result.","section":true},{"file":"index.html","page":"Implementing cards in Jigoku","id":"start-setup","name":"","signature":"setupTest options","summary":"","section":true},{"file":"index.html","page":"Implementing cards in Jigoku","id":"start-helpers","name":"","signature":"Driving the game","summary":"","section":true},{"file":"index.html","page":"Implementing cards in Jigoku","id":"start-checks","name":"","signature":"Checks you don't write","summary":"Many card texts start with a condition the engine already enforces. A condition() or cardCondition that repeats it only adds noise, and on province actions it can be wrong.","section":true},{"file":"index.html","page":"Implementing cards in Jigoku","id":"start-mistakes","name":"","signature":"Common mistakes","summary":"","section":true},{"file":"builder.html","page":"The ability builder","id":"cm-action","name":"action","signature":"action(title)","summary":"Starts an action (\"Action:\"). Returns an AbilityBuilder whose context is an ActionContext of this card class, so context.source has the card's own type."},{"file":"builder.html","page":"The ability builder","id":"cm-conflictAction","name":"conflictAction","signature":"conflictAction(title, options?)","summary":"Starts a \"Conflict Action:\" (or \"[military] Conflict Action:\"): an action that can only be used during a conflict, of conflictType if given. A character must be participating; an attachment in play needs its character to be participating. Events and holdings only need the conflict. Defined on DrawCard. Only for a card whose Emerald Legacy text prints \"Conflict Action:\". A card that exists only in its older print (A Fate Worse Than Death, Fate Has No Secrets) or whose text says \"Action: During a conflict, …\" or \"While this character is participating …\" is an action() with that condition written out."},{"file":"builder.html","page":"The ability builder","id":"cm-forcedInterrupt","name":"forcedInterrupt","signature":"forcedInterrupt(title)","summary":"Starts a \"Forced Interrupt:\": it resolves before the triggering event, and the player can't decline it. Returns a TriggerBuilder."},{"file":"builder.html","page":"The ability builder","id":"cm-forcedReaction","name":"forcedReaction","signature":"forcedReaction(title)","summary":"Starts a \"Forced Reaction:\": it resolves after the triggering event, and the player can't decline it. Returns a TriggerBuilder."},{"file":"builder.html","page":"The ability builder","id":"cm-interrupt","name":"interrupt","signature":"interrupt(title)","summary":"Starts an \"Interrupt: When …\": the player may use it before the triggering event resolves. Returns a TriggerBuilder."},{"file":"builder.html","page":"The ability builder","id":"cm-reaction","name":"reaction","signature":"reaction(title)","summary":"Starts a \"Reaction: After …\": the player may use it after the triggering event resolved. Returns a TriggerBuilder."},{"file":"builder.html","page":"The ability builder","id":"cm-wouldInterrupt","name":"wouldInterrupt","signature":"wouldInterrupt(title)","summary":"Starts an \"Interrupt: When … would …\": it opens the first window of the event, before forced interrupts and interrupts, so it can cancel or replace the event before anything reacts to it. Returns a TriggerBuilder."},{"file":"builder.html","page":"The ability builder","id":"cm-duelChallenge","name":"duelChallenge duelFocus duelStrike","signature":"duelChallenge(title, duelCondition?)","summary":"Start a \"Duel Challenge:\", \"Duel Focus:\" or \"Duel Strike:\" ability, triggered on onDuelChallenge, onDuelFocus or onDuelStrike."},{"file":"builder.html","page":"The ability builder","id":"cm-attachmentConditions","name":"attachmentConditions","signature":"attachmentConditions(properties)","summary":"Declares an attachment's \"Attach to …\" and \"No more than …\" restrictions. They become a persistent effect on the attachment that works in every location."},{"file":"builder.html","page":"The ability builder","id":"cm-composure","name":"composure","signature":"composure(properties)","summary":"\"Composure – …\": a persistentEffect that is active while the card's controller has composure (their honor bid is lower than an opponent's)."},{"file":"builder.html","page":"The ability builder","id":"cm-dire","name":"dire","signature":"dire(properties)","summary":"\"Dire – …\": a persistentEffect that is active while the card is dire (has no fate on it)."},{"file":"builder.html","page":"The ability builder","id":"cm-legendary","name":"legendary","signature":"legendary(fate)","summary":"\"Legendary X\": declares the keyword's restrictions as one persistent effect that works in every location."},{"file":"builder.html","page":"The ability builder","id":"cm-tutored","name":"tutored","signature":"tutored(attachmentName)","summary":"\"Tutored – X\": after this character enters play, find the attachment named X and put it into play attached to the character. A keyword ability, like Rally or Sincerity: it resolves by itself and has no limit."},{"file":"builder.html","page":"The ability builder","id":"cm-persistentEffect","name":"persistentEffect","signature":"persistentEffect(properties)","summary":"A constant ability: its effect applies to the matching cards (or players, rings) while the card is in location and the condition holds."},{"file":"builder.html","page":"The ability builder","id":"cm-playOnlyIf","name":"playOnlyIf","signature":"playOnlyIf(condition)","summary":"\"Play only if …\" on a character or an attachment: the card can only be played while condition holds, on top of the usual play restrictions. Defined on DrawCard."},{"file":"builder.html","page":"The ability builder","id":"cm-whileAttached","name":"whileAttached","signature":"whileAttached(properties)","summary":"\"Attached character gets …\": a persistent effect on the card this attachment is attached to, whoever controls it. Defined on DrawCard."},{"file":"builder.html","page":"The ability builder","id":"cm-declareAbilities","name":"declareAbilities","signature":"declareAbilities(declare)","summary":"Runs declare as if it were setupCardAbilities(): builders started in it are registered when it returns. Used to add an ability after setup, for example in a test."},{"file":"builder.html","page":"The ability builder","id":"b-aggregateWhen","name":"aggregateWhen","signature":"aggregateWhen(condition)","summary":"Triggers on a window's events together, for text that counts over several events (\"After fate is removed from characters … If 4 or more fate was removed\")."},{"file":"builder.html","page":"The ability builder","id":"b-when","name":"when","signature":"when(events)","summary":"The triggering condition (\"After …\", \"When …\"): a map from event name to a check of that event."},{"file":"builder.html","page":"The ability builder","id":"b-anyPlayer","name":"anyPlayer","signature":"anyPlayer()","summary":"\"Any player may trigger this ability\": either player may use it, not only the card's controller. The player who uses it is context.player."},{"file":"builder.html","page":"The ability builder","id":"b-canTriggerOutsideConflict","name":"canTriggerOutsideConflict","signature":"canTriggerOutsideConflict()","summary":"Province actions only: the action can be used when no conflict is at this province (or no conflict at all). Without it, a province's action needs a conflict at a province that passes conflictProvinceCondition()."},{"file":"builder.html","page":"The ability builder","id":"b-collectiveTrigger","name":"collectiveTrigger","signature":"collectiveTrigger()","summary":"Triggered abilities only: when the ability could trigger on several events of one window (\"After 1 or more characters move …\"), it triggers once for all of them instead of once per event, and the player isn't asked which event it answers."},{"file":"builder.html","page":"The ability builder","id":"b-condition","name":"condition","signature":"condition(condition)","summary":"A triggering condition: the ability can only be used while condition holds (\"During a conflict, …\", \"If you control a Shugenja, …\")."},{"file":"builder.html","page":"The ability builder","id":"b-conflictProvinceCondition","name":"conflictProvinceCondition","signature":"conflictProvinceCondition(condition)","summary":"Province actions only: which conflict provinces allow the action. By default only a conflict at this province (\"During a conflict at this province\")."},{"file":"builder.html","page":"The ability builder","id":"b-evenDuringDynasty","name":"evenDuringDynasty","signature":"evenDuringDynasty()","summary":"Actions only: \"Even during the dynasty phase\". The action can be used in the Dynasty phase whatever the card's type (see phase())."},{"file":"builder.html","page":"The ability builder","id":"b-location","name":"location","signature":"location(location)","summary":"Where the card must be to use the ability (\"… from your hand\", \"… from your conflict discard pile\")."},{"file":"builder.html","page":"The ability builder","id":"b-phase","name":"phase","signature":"phase(phase)","summary":"Actions only: \"During the [phase] phase\". The action can only be used in that phase."},{"file":"builder.html","page":"The ability builder","id":"b-playOnlyIf","name":"playOnlyIf","signature":"playOnlyIf(condition)","summary":"Events only: the event's \"Play only if …\". It becomes a play restriction of the card (this.playOnlyIf()), not a triggering condition, so effects that ignore triggering conditions still respect it."},{"file":"builder.html","page":"The ability builder","id":"b-cost","name":"cost","signature":"cost(cost)","summary":"A cost the player pays to use the ability (the part before the dash: \"Bow this character – …\"). The costs are listed on the Costs and limits page."},{"file":"builder.html","page":"The ability builder","id":"b-abilityTarget","name":"abilityTarget","signature":"abilityTarget(properties, ...gameActions)","summary":"\"Choose a triggered ability printed on …\": the player chooses a card, then one of its actions or triggered abilities. The ability is context.targetAbility."},{"file":"builder.html","page":"The ability builder","id":"b-elementTarget","name":"elementTarget","signature":"elementTarget(properties, ...gameActions)","summary":"\"Choose an element symbol on a card\": the player chooses a card with an element symbol, then one of its symbols. The symbol is context.element (an ElementSymbol), the card context.elementCard."},{"file":"builder.html","page":"The ability builder","id":"b-ringTarget","name":"ringTarget","signature":"ringTarget(properties, ...gameActions)","summary":"\"Choose a ring\": the chosen ring is context.rings[name], and context.ring for the target named target."},{"file":"builder.html","page":"The ability builder","id":"b-select","name":"select","signature":"select(choices)","summary":"\"Select one – … or …\" before the effect: the player picks one labelled choice when the ability is used. The label is context.selects[name].choice, and context.select for the select named target. Without other properties, pass the choices alone."},{"file":"builder.html","page":"The ability builder","id":"b-selectFrom","name":"selectFrom","signature":"selectFrom(properties, choices)","summary":"A select() whose choices depend on the context, such as labels naming a player or an earlier target."},{"file":"builder.html","page":"The ability builder","id":"b-target","name":"target","signature":"target(properties, ...gameActions)","summary":"\"Choose a character / an attachment / a card …\": one card. It is context.targets[name]; the target named target is also context.target and the {0} of a chatText() string."},{"file":"builder.html","page":"The ability builder","id":"b-targetCards","name":"targetCards","signature":"targetCards(properties, ...gameActions)","summary":"\"Choose up to 3 cards …\", \"Choose X characters …\": several cards in one choice, by mode. context.targets[name] is the array of chosen cards, and the game actions get the whole array as their target."},{"file":"builder.html","page":"The ability builder","id":"b-tokenTarget","name":"tokenTarget","signature":"tokenTarget(properties, ...gameActions)","summary":"\"Choose a status token on …\": the player chooses a card with status tokens; when it has more than one valid token, a menu asks which. context.tokens[name] (and context.token for target) is an array of StatusToken."},{"file":"builder.html","page":"The ability builder","id":"b-gameAction","name":"gameAction","signature":"gameAction(...actions)","summary":"Adds game actions to the ability or step: the effect after the dash. Use it for an action without a shortcut, a composite (sequential, multiple, conditional …) or several actions in one call."},{"file":"builder.html","page":"The ability builder","id":"b-handler","name":"handler","signature":"handler(fn)","summary":"Custom code instead of game actions: fn runs once the costs are paid and the targets chosen, and replaces the step's resolution. Prefer game actions; keep handlers for one-offs."},{"file":"builder.html","page":"The ability builder","id":"b-initiateDuel","name":"initiateDuel","signature":"initiateDuel(fn)","summary":"\"Initiate a [type] duel – …\": the duel is the ability's effect. On a character, the character is the challenger and its player chooses an opposing character as the duel target. On other cards the player chooses a challenger they control (target challenger), then the duel target (target duelTarget)."},{"file":"builder.html","page":"The ability builder","id":"b-onAffinity","name":"onAffinity","signature":"onAffinity(trait, options?)","summary":"\"With [trait] affinity, …\": the ability's or step's own game actions resolve only if the player has that affinity (controls a character with the trait, or an effect gives it)."},{"file":"builder.html","page":"The ability builder","id":"b-onResolve","name":"onResolve","signature":"onResolve(fn)","summary":"Runs fn when the ability or step starts resolving its effects, before its handler or game actions. For bookkeeping: counting uses, remembering a target, an extra chat line."},{"file":"builder.html","page":"The ability builder","id":"b-afterwards","name":"afterwards","signature":"afterwards()","summary":"Starts the next step, read after this one: a plain \"Then, …\", or a sentence that follows the effect (\"Shuffle.\"). It follows whether or not this step resolved in full, also when it raised no events. Returns a builder for the step."},{"file":"builder.html","page":"The ability builder","id":"b-afterwardsIf","name":"afterwardsIf","signature":"afterwardsIf(condition)","summary":"\"Then, if …\" or \"If …\" read after this step: the next step follows when condition holds, whether or not this step resolved in full."},{"file":"builder.html","page":"The ability builder","id":"b-if","name":"if","signature":"if(condition)","summary":"\"If …, X. Otherwise, Y\": the game actions after if() resolve when condition holds, the ones after otherwise() (if any) when it doesn't. Game actions before if() always resolve. Indent the branch lines one level deeper."},{"file":"builder.html","page":"The ability builder","id":"b-ifAble","name":"ifAble","signature":"ifAble()","summary":"\"…, if able. Otherwise, …\": the game actions after ifAble() resolve when they can (have a legal target), the ones after otherwise() when they can't."},{"file":"builder.html","page":"The ability builder","id":"b-mayResolveAgain","name":"mayResolveAgain","signature":"mayResolveAgain(options?)","summary":"\"You may [pay] to resolve this ability again\" / \"… twice\": once the ability resolved, its player may pay cost to resolve it once more. Without a cost, the player is asked \"Resolve this ability again?\" (Yes/No)."},{"file":"builder.html","page":"The ability builder","id":"b-opponentMayResolveAgain","name":"opponentMayResolveAgain","signature":"opponentMayResolveAgain(activePromptTitle)","summary":"\"Then, your opponent may resolve this ability\": the opponent is asked Yes/No and, on Yes, resolves the ability as its player, so they may hand it back in turn."},{"file":"builder.html","page":"The ability builder","id":"b-otherwise","name":"otherwise","signature":"otherwise()","summary":"\"Otherwise, …\": the game actions after it resolve when the if() condition doesn't hold, or the ifAble() actions can't resolve."},{"file":"builder.html","page":"The ability builder","id":"b-then","name":"then","signature":"then()","summary":"\"If you do, …\": starts the next step, which follows only when every event of this step resolved in full. Returns a builder for the step."},{"file":"builder.html","page":"The ability builder","id":"b-thenIf","name":"thenIf","signature":"thenIf(condition)","summary":"\"If you do, and if …\": the next step follows when this step resolved in full and condition holds."},{"file":"builder.html","page":"The ability builder","id":"b-chatMessage","name":"chatMessage","signature":"chatMessage(message)","summary":"A chat line as one of the step's game actions, printed when the actions resolve. The same as gameAction(chatMessage(…)); see chatMessage."},{"file":"builder.html","page":"The ability builder","id":"b-chatText","name":"chatText","signature":"chatText(message, args?)","summary":"What the chat says the ability does, after \"… uses {card} to \"."},{"file":"builder.html","page":"The ability builder","id":"b-message","name":"message","signature":"message(fn)","summary":"Steps only: the step's whole chat line, printed when the step resolves."},{"file":"builder.html","page":"The ability builder","id":"b-cannotBeMirrored","name":"cannotBeMirrored","signature":"cannotBeMirrored()","summary":"The Mirror's Gaze can't copy this event's ability. Only The Mirror's Gaze reads the flag."},{"file":"builder.html","page":"The ability builder","id":"b-cannotTargetFirst","name":"cannotTargetFirst","signature":"cannotTargetFirst()","summary":"The targets are chosen only after the costs are paid. By default the player chooses targets first (with a \"Pay costs first\" button); use this when the legal targets depend on what was paid."},{"file":"builder.html","page":"The ability builder","id":"b-limit","name":"limit","signature":"limit(limit)","summary":"\"(Limit X per [period].)\": how often each player may use this copy of the ability."},{"file":"builder.html","page":"The ability builder","id":"b-max","name":"max","signature":"max(max)","summary":"\"(Max X per [period].)\": how often each player may use this ability across all copies of the card, whoever owns the copy."},{"file":"builder.html","page":"The ability builder","id":"b-notPrinted","name":"notPrinted","signature":"notPrinted()","summary":"The ability isn't printed on the card (Togashi Kazue's text as an attachment): effects that copy or count printed abilities skip it."},{"file":"builder.html","page":"The ability builder","id":"b-chosenDiscard","name":"chosenDiscard","signature":"chosenDiscard(properties?)","summary":"The target player (default: the opponent) chooses cards in their hand and discards them. The same as gameAction(chosenDiscard(…)), with the same properties as the game action; full entry: chosenDiscard."},{"file":"builder.html","page":"The ability builder","id":"b-claimImperialFavor","name":"claimImperialFavor","signature":"claimImperialFavor(properties?)","summary":"The target player (default: the ability's player) claims the Imperial Favor. The same as gameAction(claimImperialFavor(…)), with the same properties as the game action; full entry: claimImperialFavor."},{"file":"builder.html","page":"The ability builder","id":"b-discardAtRandom","name":"discardAtRandom","signature":"discardAtRandom(properties?)","summary":"Discards random cards from the target player's hand (default: the opponent). The same as gameAction(discardAtRandom(…)), with the same properties as the game action; full entry: discardAtRandom."},{"file":"builder.html","page":"The ability builder","id":"b-draw","name":"draw","signature":"draw(amount?)","summary":"The target player (default: the ability's player) draws cards. The same as gameAction(draw(…)), with the same properties as the game action; full entry: draw."},{"file":"builder.html","page":"The ability builder","id":"b-gainFate","name":"gainFate","signature":"gainFate(amount?)","summary":"The target player (default: the ability's player) gains fate. The same as gameAction(gainFate(…)), with the same properties as the game action; full entry: gainFate."},{"file":"builder.html","page":"The ability builder","id":"b-gainHonor","name":"gainHonor","signature":"gainHonor(amount?)","summary":"The target player (default: the ability's player) gains honor. The same as gameAction(gainHonor(…)), with the same properties as the game action; full entry: gainHonor."},{"file":"builder.html","page":"The ability builder","id":"b-loseFate","name":"loseFate","signature":"loseFate(amount?)","summary":"The target player (default: the ability's player) loses fate. The same as gameAction(loseFate(…)), with the same properties as the game action; full entry: loseFate."},{"file":"builder.html","page":"The ability builder","id":"b-loseHonor","name":"loseHonor","signature":"loseHonor(amount?)","summary":"The target player (default: the ability's player) loses honor. The same as gameAction(loseHonor(…)), with the same properties as the game action; full entry: loseHonor."},{"file":"builder.html","page":"The ability builder","id":"b-modifyBid","name":"modifyBid","signature":"modifyBid(properties?)","summary":"Changes the target player's honor bid (default: the ability's player). The same as gameAction(modifyBid(…)), with the same properties as the game action; full entry: modifyBid."},{"file":"builder.html","page":"The ability builder","id":"b-shuffleDeck","name":"shuffleDeck","signature":"shuffleDeck(properties)","summary":"Shuffles a deck of the target player (default: the ability's player). The same as gameAction(shuffleDeck(…)), with the same properties as the game action; full entry: shuffleDeck."},{"file":"builder.html","page":"The ability builder","id":"b-takeFate","name":"takeFate","signature":"takeFate(properties?)","summary":"Takes fate from the target player (default: the opponent) and gives it to the ability's player. The same as gameAction(takeFate(…)), with the same properties as the game action; full entry: takeFate."},{"file":"builder.html","page":"The ability builder","id":"b-takeHonor","name":"takeHonor","signature":"takeHonor(properties?)","summary":"Takes honor from the target player (default: the opponent) and gives it to the ability's player. The same as gameAction(takeHonor(…)), with the same properties as the game action; full entry: takeHonor."},{"file":"builder.html","page":"The ability builder","id":"b-addToken","name":"addToken","signature":"addToken(properties?)","summary":"Adds a token (default type: honor) to the target card (default: the source). The same as gameAction(addToken(…)), with the same properties as the game action; full entry: addToken."},{"file":"builder.html","page":"The ability builder","id":"b-bow","name":"bow","signature":"bow(properties?)","summary":"Bows the target card (default: the source). The same as gameAction(bow(…)), with the same properties as the game action; full entry: bow."},{"file":"builder.html","page":"The ability builder","id":"b-discardStatusToken","name":"discardStatusToken","signature":"discardStatusToken(properties?)","summary":"Discards the target status tokens (default: every status token on the source). The same as gameAction(discardStatusToken(…)), with the same properties as the game action; full entry: discardStatusToken."},{"file":"builder.html","page":"The ability builder","id":"b-dishonor","name":"dishonor","signature":"dishonor(properties?)","summary":"Dishonors the target character (default: the source). The same as gameAction(dishonor(…)), with the same properties as the game action; full entry: dishonor."},{"file":"builder.html","page":"The ability builder","id":"b-honor","name":"honor","signature":"honor(properties?)","summary":"Honors the target character (default: the source). The same as gameAction(honor(…)), with the same properties as the game action; full entry: honor."},{"file":"builder.html","page":"The ability builder","id":"b-injure","name":"injure","signature":"injure(properties?)","summary":"Injures the target character (default: the source): removes 1 fate from it, or discards it if it has none. The same as gameAction(injure(…)), with the same properties as the game action; full entry: injure."},{"file":"builder.html","page":"The ability builder","id":"b-placeFate","name":"placeFate","signature":"placeFate(properties?)","summary":"Places fate on the target character (default: the source), from the general supply or an origin. The same as gameAction(placeFate(…)), with the same properties as the game action; full entry: placeFate."},{"file":"builder.html","page":"The ability builder","id":"b-ready","name":"ready","signature":"ready(properties?)","summary":"Readies the target card (default: the source). The same as gameAction(ready(…)), with the same properties as the game action; full entry: ready."},{"file":"builder.html","page":"The ability builder","id":"b-removeFate","name":"removeFate","signature":"removeFate(properties?)","summary":"Removes fate from the target character (default: the source), to the supply or a recipient. The same as gameAction(removeFate(…)), with the same properties as the game action; full entry: removeFate."},{"file":"builder.html","page":"The ability builder","id":"b-taint","name":"taint","signature":"taint(properties?)","summary":"Taints the target card (default: the source). The same as gameAction(taint(…)), with the same properties as the game action; full entry: taint."},{"file":"builder.html","page":"The ability builder","id":"b-attach","name":"attach","signature":"attach(properties)","summary":"Attaches attachment to the target character (default: the source). The same as gameAction(attach(…)), with the same properties as the game action; full entry: attach."},{"file":"builder.html","page":"The ability builder","id":"b-discardCard","name":"discardCard","signature":"discardCard(properties?)","summary":"Discards the target cards (default: the source) from a hand, deck or province. The same as gameAction(discardCard(…)), with the same properties as the game action; full entry: discardCard."},{"file":"builder.html","page":"The ability builder","id":"b-discardFromPlay","name":"discardFromPlay","signature":"discardFromPlay(properties?)","summary":"Discards the target card (default: the source) from play. The same as gameAction(discardFromPlay(…)), with the same properties as the game action; full entry: discardFromPlay."},{"file":"builder.html","page":"The ability builder","id":"b-lookAt","name":"lookAt","signature":"lookAt(properties?)","summary":"The ability's player looks at the target cards (default: the source). The same as gameAction(lookAt(…)), with the same properties as the game action; full entry: lookAt."},{"file":"builder.html","page":"The ability builder","id":"b-moveCard","name":"moveCard","signature":"moveCard(properties)","summary":"Moves the target cards (default: the source) to destination. The same as gameAction(moveCard(…)), with the same properties as the game action; full entry: moveCard."},{"file":"builder.html","page":"The ability builder","id":"b-moveToConflict","name":"moveToConflict","signature":"moveToConflict(properties?)","summary":"Moves the target character (default: the source) to the conflict. The same as gameAction(moveToConflict(…)), with the same properties as the game action; full entry: moveToConflict."},{"file":"builder.html","page":"The ability builder","id":"b-placeCardUnderneath","name":"placeCardUnderneath","signature":"placeCardUnderneath(properties)","summary":"Places the target card (default: the source) underneath destination. The same as gameAction(placeCardUnderneath(…)), with the same properties as the game action; full entry: placeCardUnderneath."},{"file":"builder.html","page":"The ability builder","id":"b-playCard","name":"playCard","signature":"playCard(properties?)","summary":"Plays the target card (default: the source) as if from hand, with the given play options. The same as gameAction(playCard(…)), with the same properties as the game action; full entry: playCard."},{"file":"builder.html","page":"The ability builder","id":"b-putIntoConflict","name":"putIntoConflict","signature":"putIntoConflict(properties?)","summary":"Puts the target character (default: the source) into play in the conflict. The same as gameAction(putIntoConflict(…)), with the same properties as the game action; full entry: putIntoConflict."},{"file":"builder.html","page":"The ability builder","id":"b-putIntoPlay","name":"putIntoPlay","signature":"putIntoPlay(properties?)","summary":"Puts the target character (default: the source) into play at home. The same as gameAction(putIntoPlay(…)), with the same properties as the game action; full entry: putIntoPlay."},{"file":"builder.html","page":"The ability builder","id":"b-refillFaceup","name":"refillFaceup","signature":"refillFaceup(properties)","summary":"Refills the province at location faceup. The same as gameAction(refillFaceup(…)), with the same properties as the game action; full entry: refillFaceup."},{"file":"builder.html","page":"The ability builder","id":"b-removeFromGame","name":"removeFromGame","signature":"removeFromGame(properties?)","summary":"Removes the target cards (default: the source) from the game. The same as gameAction(removeFromGame(…)), with the same properties as the game action; full entry: removeFromGame."},{"file":"builder.html","page":"The ability builder","id":"b-returnToDeck","name":"returnToDeck","signature":"returnToDeck(properties?)","summary":"Returns the target card (default: the source) to its owner's deck. The same as gameAction(returnToDeck(…)), with the same properties as the game action; full entry: returnToDeck."},{"file":"builder.html","page":"The ability builder","id":"b-returnToHand","name":"returnToHand","signature":"returnToHand(properties?)","summary":"Returns the target card (default: the source) to its owner's hand. The same as gameAction(returnToHand(…)), with the same properties as the game action; full entry: returnToHand."},{"file":"builder.html","page":"The ability builder","id":"b-reveal","name":"reveal","signature":"reveal(properties?)","summary":"Reveals the target cards (default: the source). The same as gameAction(reveal(…)), with the same properties as the game action; full entry: reveal."},{"file":"builder.html","page":"The ability builder","id":"b-sacrifice","name":"sacrifice","signature":"sacrifice(properties?)","summary":"Sacrifices the target card (default: the source). The same as gameAction(sacrifice(…)), with the same properties as the game action; full entry: sacrifice."},{"file":"builder.html","page":"The ability builder","id":"b-sendHome","name":"sendHome","signature":"sendHome(properties?)","summary":"Moves the target character (default: the source) home from the conflict. The same as gameAction(sendHome(…)), with the same properties as the game action; full entry: sendHome."},{"file":"builder.html","page":"The ability builder","id":"b-cancel","name":"cancel","signature":"cancel(properties?)","summary":"Cancels the triggering event; with replacementGameAction, that action resolves instead, and thenGameAction after it. Triggered abilities only (a compile error on an action); after aggregateWhen() there is no single event, and nothing is cancelled. The same as gameAction(cancel(…)), with the same properties as the game action; full entry: cancel."},{"file":"builder.html","page":"The ability builder","id":"b-initiateConflict","name":"initiateConflict","signature":"initiateConflict(properties?)","summary":"The target player (default: the ability's player) declares a conflict. The same as gameAction(initiateConflict(…)), with the same properties as the game action; full entry: initiateConflict."},{"file":"builder.html","page":"The ability builder","id":"b-placeFateOnRing","name":"placeFateOnRing","signature":"placeFateOnRing(properties?)","summary":"Places fate on the target rings (default: the contested ring). The same as gameAction(placeFateOnRing(…)), with the same properties as the game action; full entry: placeFateOnRing."},{"file":"builder.html","page":"The ability builder","id":"b-resolveConflictRing","name":"resolveConflictRing","signature":"resolveConflictRing(properties?)","summary":"Resolves the contested ring's effect (default: the contested ring). The same as gameAction(resolveConflictRing(…)), with the same properties as the game action; full entry: resolveConflictRing."},{"file":"builder.html","page":"The ability builder","id":"b-resolveRingEffect","name":"resolveRingEffect","signature":"resolveRingEffect(properties?)","summary":"Resolves the target ring's effect (default: the contested ring). The same as gameAction(resolveRingEffect(…)), with the same properties as the game action; full entry: resolveRingEffect."},{"file":"builder.html","page":"The ability builder","id":"b-switchConflictType","name":"switchConflictType","signature":"switchConflictType(properties?)","summary":"Switches the type of the current conflict. The same as gameAction(switchConflictType(…)), with the same properties as the game action; full entry: switchConflictType."},{"file":"builder.html","page":"The ability builder","id":"b-atEndOfConflict","name":"atEndOfConflict","signature":"atEndOfConflict(properties)","summary":"A delayed effect: at the end of the conflict, gameAction resolves on the target card (default: the source). The same as gameAction(atEndOfConflict(…)), with the same properties as the game action; full entry: atEndOfConflict."},{"file":"builder.html","page":"The ability builder","id":"b-cardLastingEffect","name":"cardLastingEffect","signature":"cardLastingEffect(properties)","summary":"Applies effect to the target cards (default: the source) for duration. The same as gameAction(cardLastingEffect(…)), with the same properties as the game action; full entry: cardLastingEffect."},{"file":"builder.html","page":"The ability builder","id":"b-conflictLastingEffect","name":"conflictLastingEffect","signature":"conflictLastingEffect(properties)","summary":"Applies effect to the current conflict. The same as gameAction(conflictLastingEffect(…)), with the same properties as the game action; full entry: conflictLastingEffect."},{"file":"builder.html","page":"The ability builder","id":"b-duelLastingEffect","name":"duelLastingEffect","signature":"duelLastingEffect(properties)","summary":"Applies effect to the current duel. The same as gameAction(duelLastingEffect(…)), with the same properties as the game action; full entry: duelLastingEffect."},{"file":"builder.html","page":"The ability builder","id":"b-playerLastingEffect","name":"playerLastingEffect","signature":"playerLastingEffect(properties)","summary":"Applies effect to the target player (default: the ability's player). The same as gameAction(playerLastingEffect(…)), with the same properties as the game action; full entry: playerLastingEffect."},{"file":"builder.html","page":"The ability builder","id":"b-ringLastingEffect","name":"ringLastingEffect","signature":"ringLastingEffect(properties)","summary":"Applies effect to the target rings (default: the contested ring). The same as gameAction(ringLastingEffect(…)), with the same properties as the game action; full entry: ringLastingEffect."},{"file":"builder.html","page":"The ability builder","id":"b-cardMenu","name":"cardMenu","signature":"cardMenu(properties)","summary":"One of cards is chosen from card buttons, and gameAction resolves on it. The same as gameAction(cardMenu(…)), with the same properties as the game action; full entry: cardMenu."},{"file":"builder.html","page":"The ability builder","id":"b-chooseAction","name":"chooseAction","signature":"chooseAction(properties)","summary":"A labelled choice between game actions (\"select one\" after the dash); a choice is an action or { action, message }. The same as gameAction(chooseAction(…)), with the same properties as the game action; full entry: chooseAction."},{"file":"builder.html","page":"The ability builder","id":"b-chooseAmount","name":"chooseAmount","signature":"chooseAmount(properties)","summary":"A number is chosen, and gameAction(amount) resolves. The same as gameAction(chooseAmount(…)), with the same properties as the game action; full entry: chooseAmount."},{"file":"builder.html","page":"The ability builder","id":"b-deckSearch","name":"deckSearch","signature":"deckSearch(properties)","summary":"Searches a deck: look at its top cards, choose some, and resolve gameAction on them. The same as gameAction(deckSearch(…)), with the same properties as the game action; full entry: deckSearch."},{"file":"builder.html","page":"The ability builder","id":"b-optional","name":"optional","signature":"optional(properties)","summary":"A player (default: the ability's player) is asked Yes/No whether to resolve gameAction. The same as gameAction(optional(…)), with the same properties as the game action; full entry: optional."},{"file":"builder.html","page":"The ability builder","id":"b-selectAttackedProvince","name":"selectAttackedProvince","signature":"selectAttackedProvince(properties)","summary":"An attacked province is chosen, and gameAction resolves on it. The same as gameAction(selectAttackedProvince(…)), with the same properties as the game action; full entry: selectAttackedProvince."},{"file":"builder.html","page":"The ability builder","id":"b-selectCard","name":"selectCard","signature":"selectCard(properties)","summary":"A player (default: the ability's player) chooses a card, and gameAction resolves on it. The same as gameAction(selectCard(…)), with the same properties as the game action; full entry: selectCard."},{"file":"builder.html","page":"The ability builder","id":"b-selectCards","name":"selectCards","signature":"selectCards(properties)","summary":"A player chooses several cards by mode (required), and gameAction resolves on them. The same as gameAction(selectCards(…)), with the same properties as the game action; full entry: selectCards."},{"file":"builder.html","page":"The ability builder","id":"b-selectRing","name":"selectRing","signature":"selectRing(properties)","summary":"A ring is chosen, and gameAction resolves on it. The same as gameAction(selectRing(…)), with the same properties as the game action; full entry: selectRing."},{"file":"builder.html","page":"The ability builder","id":"b-selectToken","name":"selectToken","signature":"selectToken(properties)","summary":"A status token on card is chosen, and gameAction resolves on it. The same as gameAction(selectToken(…)), with the same properties as the game action; full entry: selectToken."},{"file":"builder.html","page":"The ability builder","id":"b-tokenFromTopCard","name":"tokenFromTopCard","signature":"tokenFromTopCard(properties)","summary":"The top card of a deck becomes a token card, then gameAction(token) resolves. The same as gameAction(tokenFromTopCard(…)), with the same properties as the game action; full entry: tokenFromTopCard."},{"file":"builder.html","page":"The ability builder","id":"cm-conflictProvinceWithText","name":"conflictProvinceWithText","signature":"conflictProvinceWithText()","summary":"On a province: the conflict province that carries this province's text, which is this province or a copy of it, or undefined. A province whose text is blank (broken, dishonored or blanked) doesn't count."},{"file":"builder.html","page":"The ability builder","id":"cm-isAttacking","name":"isAttacking isDefending","signature":"isAttacking(conflictType?)","summary":"Whether this character is attacking (or defending) in the current conflict. Defined on DrawCard."},{"file":"builder.html","page":"The ability builder","id":"cm-isInConflictProvince","name":"isInConflictProvince","signature":"isInConflictProvince()","summary":"Whether this card is in a province where a conflict is (\"During a conflict at this province\" on a holding)."},{"file":"builder.html","page":"The ability builder","id":"cm-getBaseMilitarySkill","name":"getBaseMilitarySkill getBasePoliticalSkill","signature":"getBaseMilitarySkill()","summary":"This character's base skill: the printed skill after effects that change the base (set, copy, double, switch, dash), without other modifiers. Defined on DrawCard; the getters baseMilitarySkill and basePoliticalSkill return the same."},{"file":"builder.html","page":"The ability builder","id":"cm-getCurrentElementSymbol","name":"getCurrentElementSymbol","signature":"getCurrentElementSymbol(key)","summary":"The element of one of this card's element symbols, after effects that replace it. A card declares its symbols in getPrintedElementSymbols(), each with a key."},{"file":"builder.html","page":"The ability builder","id":"cm-getTokenCount","name":"getTokenCount","signature":"getTokenCount(type)","summary":"How many tokens of type (such as TokenType.Honor) are on this card; 0 when there are none. Status tokens (honored, dishonored, tainted) are not counted here."},{"file":"builder.html","page":"The ability builder","id":"cm-hasTrait","name":"hasTrait","signature":"hasTrait(trait)","summary":"Whether this card has the trait now: its printed traits (or those of the card it copies), plus gained traits, minus lost ones."},{"file":"builder.html","page":"The ability builder","id":"cm-isBlank","name":"isBlank","signature":"isBlank()","summary":"Whether this card's printed text box is blank: a blank effect, or an effect that makes it a copy of another card. A province is also blank while it is broken or dishonored (unless the conflict ignores status tokens)."},{"file":"builder.html","page":"The ability builder","id":"cm-isFaceup","name":"isFaceup","signature":"isFaceup()","summary":"Whether this card is faceup."},{"file":"builder.html","page":"The ability builder","id":"cm-declaring-abilities","name":"","signature":"Declaring abilities","summary":"A card class declares its abilities in setupCardAbilities(). An action or a triggered ability starts with a card method that takes the ability's title and returns a builder; each chained call adds one part of the card text (see The ability builder). The builder is registered when setupCardAbilities() returns, so there is no closing build() call. Constant abilities (persistent effects, composure, dire, attachment restrictions, Legendary) take a properties object or a number and return nothing.","section":true},{"file":"builder.html","page":"The ability builder","id":"b-the-ability-builder","name":"","signature":"The ability builder","summary":"action(), conflictAction(), the duel triggers and when()/aggregateWhen() return an AbilityBuilder (server/game/AbilityBuilder.ts). Each call records one part of the ability and returns the builder, typed with what was declared so far: a target, a cost or a select adds its name to context for every later callback, so card code needs no casts. The types are backed by runtime checks: a callback that is called with a context that doesn't hold its declared targets throws \"<title>: context does not match its declared targets\".","section":true},{"file":"builder.html","page":"The ability builder","id":"cm-card-queries","name":"","signature":"Card queries used in abilities","summary":"Card methods that ability callbacks (condition, cardCondition, match, if() …) call to read the game state. They change nothing. More helpers are on the Card helpers and queries page.","section":true},{"file":"game-actions.html","page":"Game actions","id":"ga-addToken","name":"addToken","signature":"addToken(properties?)","summary":"Places a token on a card, such as an honor token on a province or holding."},{"file":"game-actions.html","page":"Game actions","id":"ga-bow","name":"bow","signature":"bow(properties?)","summary":"Bows the target cards."},{"file":"game-actions.html","page":"Game actions","id":"ga-discardStatusToken","name":"discardStatusToken","signature":"discardStatusToken(properties?)","summary":"Discards status tokens (honored, dishonored, tainted) from the cards they are on."},{"file":"game-actions.html","page":"Game actions","id":"ga-dishonor","name":"dishonor","signature":"dishonor(properties?)","summary":"Dishonors a character: an honored character loses its honored token and becomes ordinary; an ordinary character gets a dishonored token."},{"file":"game-actions.html","page":"Game actions","id":"ga-dishonorProvince","name":"dishonorProvince","signature":"dishonorProvince(properties?)","summary":"Places a dishonored status token on a province, which blanks its printed text."},{"file":"game-actions.html","page":"Game actions","id":"ga-gainStatusToken","name":"gainStatusToken","signature":"gainStatusToken(properties?)","summary":"Gives a card a status token of a given kind. Unlike honor and dishonor, it is about the token, not the change of status."},{"file":"game-actions.html","page":"Game actions","id":"ga-honor","name":"honor","signature":"honor(properties?)","summary":"Honors a character: a dishonored character loses its dishonored token and becomes ordinary; an ordinary character gets an honored token."},{"file":"game-actions.html","page":"Game actions","id":"ga-gainFate","name":"gainFate","signature":"gainFate(properties?)","summary":"The target players gain fate."},{"file":"game-actions.html","page":"Game actions","id":"ga-gainHonor","name":"gainHonor","signature":"gainHonor(properties?)","summary":"The target players gain honor from the general supply."},{"file":"game-actions.html","page":"Game actions","id":"ga-loseFate","name":"loseFate","signature":"loseFate(properties?)","summary":"The target players lose fate from their fate pool."},{"file":"game-actions.html","page":"Game actions","id":"ga-loseHonor","name":"loseHonor","signature":"loseHonor(properties?)","summary":"The target players lose honor to the general supply."},{"file":"game-actions.html","page":"Game actions","id":"ga-discardCard","name":"discardCard","signature":"discardCard(properties?)","summary":"Puts cards into their discard pile from wherever they are: hand, province, deck."},{"file":"game-actions.html","page":"Game actions","id":"ga-discardFromPlay","name":"discardFromPlay","signature":"discardFromPlay(properties?)","summary":"Discards cards from play: they leave play and go to their discard pile."},{"file":"game-actions.html","page":"Game actions","id":"ga-injure","name":"injure","signature":"injure(properties?)","summary":"Injures characters: removes 1 fate from a character with fate, and discards a character without fate."},{"file":"game-actions.html","page":"Game actions","id":"ga-chosenDiscard","name":"chosenDiscard","signature":"chosenDiscard(properties?)","summary":"The target player chooses cards in their hand and discards them."},{"file":"game-actions.html","page":"Game actions","id":"ga-chosenReturnToDeck","name":"chosenReturnToDeck","signature":"chosenReturnToDeck(properties?)","summary":"The target player chooses cards in their hand and puts them on their conflict deck."},{"file":"game-actions.html","page":"Game actions","id":"ga-deckSearch","name":"deckSearch","signature":"deckSearch(properties)","summary":"Searches a deck, or looks at its top cards: the chooser takes cards, gameAction resolves on them, and the rest are shuffled back or otherwise dealt with."},{"file":"game-actions.html","page":"Game actions","id":"ga-discardAtRandom","name":"discardAtRandom","signature":"discardAtRandom(properties?)","summary":"The target player discards cards at random from their hand."},{"file":"game-actions.html","page":"Game actions","id":"ga-discardMatching","name":"discardMatching","signature":"discardMatching(properties?)","summary":"The target player discards the cards from a given list that match a condition, such as each revealed copy of a named card."},{"file":"game-actions.html","page":"Game actions","id":"ga-draw","name":"draw","signature":"draw(properties?)","summary":"The target players draw cards from their conflict deck."},{"file":"game-actions.html","page":"Game actions","id":"ga-lookAt","name":"lookAt","signature":"lookAt(properties?)","summary":"Looks at cards, such as cards in a hand or a facedown card. The cards are shown in the chat."},{"file":"game-actions.html","page":"Game actions","id":"ga-attach","name":"attach","signature":"attach(properties?)","summary":"Attaches a card to the target character or province, from wherever the card is (hand, discard pile, another character)."},{"file":"game-actions.html","page":"Game actions","id":"ga-attachToRing","name":"attachToRing","signature":"attachToRing(properties?)","summary":"Attaches a card to a ring, under the control of the ability's player."},{"file":"game-actions.html","page":"Game actions","id":"ga-detach","name":"detach","signature":"detach(properties?)","summary":"Takes an attachment off its parent and leaves it in play on its own. Combine it with an effect that turns the card into a character."},{"file":"game-actions.html","page":"Game actions","id":"ga-breakProvince","name":"breakProvince","signature":"breakProvince(properties?)","summary":"Breaks a province."},{"file":"game-actions.html","page":"Game actions","id":"ga-createToken","name":"createToken","signature":"createToken(properties)","summary":"Turns facedown cards in provinces into token characters: each card is removed from the game, a token enters play in its place, and the token is discarded at the end of the conflict."},{"file":"game-actions.html","page":"Game actions","id":"ga-fillProvince","name":"fillProvince","signature":"fillProvince(properties)","summary":"Fills a province of the target player from the top of their dynasty deck."},{"file":"game-actions.html","page":"Game actions","id":"ga-flipDynasty","name":"flipDynasty","signature":"flipDynasty(properties?)","summary":"Turns a facedown dynasty card in a province faceup."},{"file":"game-actions.html","page":"Game actions","id":"ga-claimRing","name":"claimRing","signature":"claimRing(properties?)","summary":"The ability's player claims a ring."},{"file":"game-actions.html","page":"Game actions","id":"ga-initiateConflict","name":"initiateConflict","signature":"initiateConflict(properties?)","summary":"The target player declares a conflict now."},{"file":"game-actions.html","page":"Game actions","id":"ga-placeFateOnRing","name":"placeFateOnRing","signature":"placeFateOnRing(properties?)","summary":"Places fate on a ring, from the general pool or from origin. Builder shortcut: .placeFateOnRing(…)."},{"file":"game-actions.html","page":"Game actions","id":"ga-removeRingFromPlay","name":"removeRingFromPlay","signature":"removeRingFromPlay(properties?)","summary":"Removes a ring from play. The fate on it stays. No builder shortcut."},{"file":"game-actions.html","page":"Game actions","id":"ga-resolveConflictRing","name":"resolveConflictRing","signature":"resolveConflictRing(properties?)","summary":"The ability's player resolves the ring as the conflict ring, as if they were the attacking player. Builder shortcut: .resolveConflictRing(…)."},{"file":"game-actions.html","page":"Game actions","id":"ga-resolveRingEffect","name":"resolveRingEffect","signature":"resolveRingEffect(properties?)","summary":"Resolves the effect of one or more rings' elements. Builder shortcut: .resolveRingEffect(…)."},{"file":"game-actions.html","page":"Game actions","id":"ga-returnRing","name":"returnRing","signature":"returnRing(properties?)","summary":"Returns a claimed or contested ring to the unclaimed pool. No builder shortcut."},{"file":"game-actions.html","page":"Game actions","id":"ga-returnRingToPlay","name":"returnRingToPlay","signature":"returnRingToPlay(properties?)","summary":"Returns a ring that was removed from play. No builder shortcut."},{"file":"game-actions.html","page":"Game actions","id":"ga-switchConflictElement","name":"switchConflictElement","signature":"switchConflictElement(properties?)","summary":"Switches the contested ring with the target ring; the conflict keeps its type. No builder shortcut."},{"file":"game-actions.html","page":"Game actions","id":"ga-switchConflictType","name":"switchConflictType","signature":"switchConflictType(properties?)","summary":"Switches the conflict between military and political; the conflict keeps its element. Builder shortcut: .switchConflictType(…)."},{"file":"game-actions.html","page":"Game actions","id":"ga-takeFateFromRing","name":"takeFateFromRing","signature":"takeFateFromRing(properties?)","summary":"The ability's player takes fate from a ring, or removes it to the general pool. No builder shortcut."},{"file":"game-actions.html","page":"Game actions","id":"ga-takeRing","name":"takeRing","signature":"takeRing(properties?)","summary":"The ability's player claims the ring, taking the fate on it. No builder shortcut."},{"file":"game-actions.html","page":"Game actions","id":"ga-claimImperialFavor","name":"claimImperialFavor","signature":"claimImperialFavor(properties)","summary":"The target player claims the Imperial Favor; the opponent loses it."},{"file":"game-actions.html","page":"Game actions","id":"ga-flipImperialFavor","name":"flipImperialFavor","signature":"flipImperialFavor(properties)","summary":"Flips the target player's Imperial Favor from military to political or back."},{"file":"game-actions.html","page":"Game actions","id":"ga-loseImperialFavor","name":"loseImperialFavor","signature":"loseImperialFavor(properties?)","summary":"The target player loses the Imperial Favor."},{"file":"game-actions.html","page":"Game actions","id":"ga-duel","name":"duel","signature":"duel(properties)","summary":"The challenger challenges the target characters to a duel; the duel resolves and gameAction resolves if it has a winner."},{"file":"game-actions.html","page":"Game actions","id":"ga-duelAddParticipant","name":"duelAddParticipant","signature":"duelAddParticipant(properties)","summary":"Adds a character to a duel as another target."},{"file":"game-actions.html","page":"Game actions","id":"ga-fateBid","name":"fateBid","signature":"fateBid(properties?)","summary":"Each player secretly chooses an amount of fate from their pool and loses it; then postBidAction resolves."},{"file":"game-actions.html","page":"Game actions","id":"ga-honorBid","name":"honorBid","signature":"honorBid(properties?)","summary":"The players secretly choose a number on their honor dials and reveal them; then postBidAction resolves."},{"file":"game-actions.html","page":"Game actions","id":"ga-atEndOfConflict","name":"atEndOfConflict","signature":"atEndOfConflict(properties)","summary":"\"At the end of the conflict, …\": resolves gameAction on the target cards when this conflict ends."},{"file":"game-actions.html","page":"Game actions","id":"ga-cardLastingEffect","name":"cardLastingEffect","signature":"cardLastingEffect(properties)","summary":"Applies an effect to cards for a duration: \"until the end of the conflict, that character gets +2 military\"."},{"file":"game-actions.html","page":"Game actions","id":"ga-conflictLastingEffect","name":"conflictLastingEffect","signature":"conflictLastingEffect(properties)","summary":"Applies an effect to the conflict as a whole, not to a card or player: \"characters cannot trigger abilities this conflict\"."},{"file":"game-actions.html","page":"Game actions","id":"ga-duelLastingEffect","name":"duelLastingEffect","signature":"duelLastingEffect(properties)","summary":"Applies an effect to the current duel: \"characters do not contribute their printed statistic to the resolution of this duel\"."},{"file":"game-actions.html","page":"Game actions","id":"ga-cancel","name":"cancel","signature":"cancel(properties?)","summary":"\"Cancel\" and \"… instead\": cancels the event an interrupt triggered on, and optionally resolves a replacement in its place."},{"file":"game-actions.html","page":"Game actions","id":"ga-chatMessage","name":"chatMessage","signature":"chatMessage(message)","summary":"Adds a chat line as a step of its own, when it resolves."},{"file":"game-actions.html","page":"Game actions","id":"ga-conditional","name":"conditional","signature":"conditional(properties)","summary":"\"If …, X. Otherwise, Y\": resolves one of two actions, picked by a condition when it resolves."},{"file":"game-actions.html","page":"Game actions","id":"ga-handler","name":"handler","signature":"handler(properties?)","summary":"Runs a function as a game action, in order with the others. For game state no other action covers."},{"file":"game-actions.html","page":"Game actions","id":"ga-ifAble","name":"ifAble","signature":"ifAble(properties)","summary":"\"X, if able. Otherwise, Y\": resolves the first action when it has a legal target, the second when it doesn't."},{"file":"game-actions.html","page":"Game actions","id":"ga-joint","name":"joint","signature":"joint(gameActions)","summary":"Resolves several actions together, but only when every one of them has a legal target (\"do X and Y\": if one can't happen, neither does)."},{"file":"game-actions.html","page":"Game actions","id":"ga-multiple","name":"multiple","signature":"multiple(gameActions)","summary":"Resolves several actions at the same time: their events go into one window. No builder shortcut; use it on a target or with .gameAction(…)."},{"file":"game-actions.html","page":"Game actions","id":"ga-onAffinity","name":"onAffinity","signature":"onAffinity(properties)","summary":"\"With [trait] affinity, …\": resolves gameAction only if the ability's player has affinity to the trait (controls a character with it), otherwise noAffinityGameAction if there is one. Affinity works with any trait, not only elements."},{"file":"game-actions.html","page":"Game actions","id":"ga-optional","name":"optional","signature":"optional(properties)","summary":"\"You may …\": a player answers Yes or No, and gameAction resolves on Yes. Builder shortcut: .optional(…)."},{"file":"game-actions.html","page":"Game actions","id":"ga-sequential","name":"sequential","signature":"sequential(gameActions)","summary":"Resolves several actions one after the other: each action's events resolve in their own window before the next action is checked. No builder shortcut; use it on a target or with .gameAction(…) (or use .then() steps)."},{"file":"game-actions.html","page":"Game actions","id":"ga-assignRoles","name":"assignRoles","signature":"assignRoles(properties)","summary":"\"Honor one of those characters and dishonor the other\": the chooser gives each of two cards one of two roles, and each role's action resolves on its card."},{"file":"game-actions.html","page":"Game actions","id":"ga-cardMenu","name":"cardMenu","signature":"cardMenu(properties)","summary":"Shows a list of cards as buttons; the chosen card gets gameAction. For choices among cards that aren't on the table, such as cards from a deck or a revealed hand."},{"file":"game-actions.html","page":"Game actions","id":"ga-chooseAction","name":"chooseAction","signature":"chooseAction(properties)","summary":"\"Choose one: …\" while the ability resolves: the chooser picks one of several labelled actions, and it resolves."},{"file":"game-actions.html","page":"Game actions","id":"ga-chooseAmount","name":"chooseAmount","signature":"chooseAmount(properties)","summary":"\"Choose a number\": the chooser picks a number from min to max, then gameAction(amount) resolves."},{"file":"game-actions.html","page":"Game actions","id":"ga-nameCard","name":"nameCard","signature":"nameCard(properties)","summary":"\"Name a card\": a player names a card, then gameAction(cardName) resolves. No builder shortcut."},{"file":"game-actions.html","page":"Game actions","id":"ga-selectAttackedProvince","name":"selectAttackedProvince","signature":"selectAttackedProvince(properties)","summary":"\"Choose an attacked province\": a selectCard limited to the provinces in the current conflict, with no prompt when there is only one. Builder shortcut: .selectAttackedProvince(…)."},{"file":"game-actions.html","page":"Game actions","id":"ga-selectCard","name":"selectCard","signature":"selectCard(properties)","summary":"A player chooses one card while the ability resolves, and gameAction resolves on it. Builder shortcut: .selectCard(…)."},{"file":"game-actions.html","page":"Game actions","id":"ga-selectCards","name":"selectCards","signature":"selectCards(properties)","summary":"A player chooses several cards while the ability resolves, and gameAction resolves on them. Builder shortcut: .selectCards(…)."},{"file":"game-actions.html","page":"Game actions","id":"ga-selectRing","name":"selectRing","signature":"selectRing(properties)","summary":"A player chooses a ring while the ability resolves, and gameAction resolves on it. Builder shortcut: .selectRing(…)."},{"file":"game-actions.html","page":"Game actions","id":"ga-selectToken","name":"selectToken","signature":"selectToken(properties)","summary":"A player chooses one of a card's status tokens, and gameAction resolves on it. Builder shortcut: .selectToken(…)."},{"file":"game-actions.html","page":"Game actions","id":"ga-moveStatusToken","name":"moveStatusToken","signature":"moveStatusToken(properties)","summary":"Moves a status token (honored, dishonored or tainted) from the card that has it to recipient. No builder shortcut: use it on a target, in selectToken, or with .gameAction(…)."},{"file":"game-actions.html","page":"Game actions","id":"ga-ready","name":"ready","signature":"ready(properties?)","summary":"Readies the target. Builder shortcut: .ready(…)."},{"file":"game-actions.html","page":"Game actions","id":"ga-restoreProvince","name":"restoreProvince","signature":"restoreProvince(properties?)","summary":"Restores a broken province. No builder shortcut."},{"file":"game-actions.html","page":"Game actions","id":"ga-reveal","name":"reveal","signature":"reveal(properties?)","summary":"Reveals the target: turns it faceup. Builder shortcut: .reveal(…)."},{"file":"game-actions.html","page":"Game actions","id":"ga-taint","name":"taint","signature":"taint(properties?)","summary":"Gives the target a tainted status token. Builder shortcut: .taint(…)."},{"file":"game-actions.html","page":"Game actions","id":"ga-turnFacedown","name":"turnFacedown","signature":"turnFacedown(properties?)","summary":"Turns a faceup card in a province facedown. No builder shortcut."},{"file":"game-actions.html","page":"Game actions","id":"ga-moveConflict","name":"moveConflict","signature":"moveConflict(properties?)","summary":"Moves the conflict to the target province. No builder shortcut."},{"file":"game-actions.html","page":"Game actions","id":"ga-moveToConflict","name":"moveToConflict","signature":"moveToConflict(properties?)","summary":"Moves a character at home into the conflict. Builder shortcut: .moveToConflict(…)."},{"file":"game-actions.html","page":"Game actions","id":"ga-sendHome","name":"sendHome","signature":"sendHome(properties?)","summary":"Sends a participating character home. Builder shortcut: .sendHome(…)."},{"file":"game-actions.html","page":"Game actions","id":"ga-opponentPutIntoPlay","name":"opponentPutIntoPlay","signature":"opponentPutIntoPlay(properties?)","summary":"Like putIntoPlay (at home), but the ability's player's opponent puts the character into play and controls it. No builder shortcut."},{"file":"game-actions.html","page":"Game actions","id":"ga-playCard","name":"playCard","signature":"playCard(properties?)","summary":"The ability's player plays the target card as if it were in their hand: its play ability resolves in full (targets, costs, \"card played\" events). Builder shortcut: .playCard(…)."},{"file":"game-actions.html","page":"Game actions","id":"ga-putIntoPlay","name":"putIntoPlay putIntoConflict","signature":"putIntoPlay(properties?)","summary":"Puts a character into play for the ability's player: putIntoPlay at home, putIntoConflict participating in the current conflict. Builder shortcuts: .putIntoPlay(…), .putIntoConflict(…)."},{"file":"game-actions.html","page":"Game actions","id":"ga-modifyBid","name":"modifyBid","signature":"modifyBid(properties?)","summary":"Increases or decreases a player's honor bid. Builder shortcut: .modifyBid(…)."},{"file":"game-actions.html","page":"Game actions","id":"ga-performGloryCount","name":"performGloryCount","signature":"performGloryCount(properties)","summary":"Performs a glory count, then resolves gameAction for its result. No builder shortcut."},{"file":"game-actions.html","page":"Game actions","id":"ga-placeFate","name":"placeFate","signature":"placeFate(properties?)","summary":"Places fate on a character, from the general pool or from origin. Builder shortcut: .placeFate(…)."},{"file":"game-actions.html","page":"Game actions","id":"ga-removeFate","name":"removeFate","signature":"removeFate(properties?)","summary":"Removes fate from a character, to the general pool or to recipient. Builder shortcut: .removeFate(…)."},{"file":"game-actions.html","page":"Game actions","id":"ga-setHonorDial","name":"setHonorDial","signature":"setHonorDial(properties)","summary":"Sets a player's honor dial to a new value. No builder shortcut."},{"file":"game-actions.html","page":"Game actions","id":"ga-takeFate","name":"takeFate","signature":"takeFate(properties?)","summary":"The target player gives fate to their opponent (\"take 1 fate from your opponent\"). Builder shortcut: .takeFate(…)."},{"file":"game-actions.html","page":"Game actions","id":"ga-takeHonor","name":"takeHonor","signature":"takeHonor(properties?)","summary":"The target player gives honor to their opponent (\"take 1 honor from your opponent\"). Builder shortcut: .takeHonor(…)."},{"file":"game-actions.html","page":"Game actions","id":"ga-moveCard","name":"moveCard","signature":"moveCard(properties)","summary":"Moves a card that is not in play to destination: from a deck, discard pile, hand or province. Builder shortcut: .moveCard(…)."},{"file":"game-actions.html","page":"Game actions","id":"ga-placeCardUnderneath","name":"placeCardUnderneath","signature":"placeCardUnderneath(properties)","summary":"Places the target card underneath destination. Builder shortcut: .placeCardUnderneath(…)."},{"file":"game-actions.html","page":"Game actions","id":"ga-placeInProvince","name":"placeInProvince","signature":"placeInProvince(properties?)","summary":"Puts a dynasty card that is not in play into one of its owner's provinces, faceup by default, optionally discarding the cards there. No builder shortcut."},{"file":"game-actions.html","page":"Game actions","id":"ga-putIntoProvince","name":"putIntoProvince","signature":"putIntoProvince(properties)","summary":"Takes a card in play and puts it into a province (it is out of play there). No builder shortcut."},{"file":"game-actions.html","page":"Game actions","id":"ga-refillFaceup","name":"refillFaceup","signature":"refillFaceup(properties)","summary":"Refills a player's empty provinces from their dynasty deck and turns the new cards faceup. Builder shortcut: .refillFaceup(…)."},{"file":"game-actions.html","page":"Game actions","id":"ga-removeFromGame","name":"removeFromGame","signature":"removeFromGame(properties?)","summary":"Removes the target from the game. Builder shortcut: .removeFromGame(…)."},{"file":"game-actions.html","page":"Game actions","id":"ga-returnToDeck","name":"returnToDeck","signature":"returnToDeck(properties?)","summary":"Returns the target to its owner's deck: the dynasty deck for dynasty cards, the conflict deck for conflict cards. Builder shortcut: .returnToDeck(…)."},{"file":"game-actions.html","page":"Game actions","id":"ga-returnToHand","name":"returnToHand","signature":"returnToHand(properties?)","summary":"Returns a card in play to its owner's hand. Builder shortcut: .returnToHand(…)."},{"file":"game-actions.html","page":"Game actions","id":"ga-sacrifice","name":"sacrifice","signature":"sacrifice(properties?)","summary":"The target's controller sacrifices it: it is discarded from play. Builder shortcut: .sacrifice(…). It is discardFromPlay marked as a sacrifice."},{"file":"game-actions.html","page":"Game actions","id":"ga-setAside","name":"setAside","signature":"setAside(properties?)","summary":"Sets cards aside, out of play (in the removed-from-game zone), optionally hidden, playable by a player, or returned at the end of the conflict. No builder shortcut."},{"file":"game-actions.html","page":"Game actions","id":"ga-rearrangeDeck","name":"rearrangeDeck","signature":"rearrangeDeck(properties)","summary":"The ability's player puts the top cards of a deck back in the order they choose. No builder shortcut."},{"file":"game-actions.html","page":"Game actions","id":"ga-shuffleDeck","name":"shuffleDeck","signature":"shuffleDeck(properties)","summary":"Shuffles a player's deck. Builder shortcut: .shuffleDeck(…)."},{"file":"game-actions.html","page":"Game actions","id":"ga-tokenFromTopCard","name":"tokenFromTopCard","signature":"tokenFromTopCard(properties)","summary":"The top card of a player's deck becomes a token card, then gameAction(token) resolves. Builder shortcut: .tokenFromTopCard(…)."},{"file":"game-actions.html","page":"Game actions","id":"ga-playerLastingEffect","name":"playerLastingEffect","signature":"playerLastingEffect(properties)","summary":"Applies an effect to players for a while (\"for this conflict, you …\"). Builder shortcut: .playerLastingEffect(…)."},{"file":"game-actions.html","page":"Game actions","id":"ga-ringLastingEffect","name":"ringLastingEffect","signature":"ringLastingEffect(properties)","summary":"Applies an effect to rings for a while. Builder shortcut: .ringLastingEffect(…)."},{"file":"game-actions.html","page":"Game actions","id":"ga-takeControl","name":"takeControl","signature":"takeControl(properties?)","summary":"The ability's player takes control of the target. It is a cardLastingEffect whose effect defaults to the takeControl effect for the ability's player. No builder shortcut."},{"file":"game-actions.html","page":"Game actions","id":"ga-resolveAbility","name":"resolveAbility","signature":"resolveAbility(properties)","summary":"Resolves an ability's effects \"as if\" it were used, skipping its triggering. No builder shortcut."},{"file":"game-actions.html","page":"Game actions","id":"ga-triggerAbility","name":"triggerAbility","signature":"triggerAbility(properties)","summary":"Triggers an ability as if the player used it: it resolves in full, with targeting, costs and cancelling. No builder shortcut."},{"file":"game-actions.html","page":"Game actions","id":"ga-basics","name":"","signature":"How game actions work","summary":"A game action is one thing the game does: bow a character, gain honor, move a card. Every change a card makes goes through one, so that reactions, interrupts, restrictions and the chat see it. Each action is made by a factory exported from server/game/GameActions/GameActions.ts.","section":true},{"file":"game-actions.html","page":"Game actions","id":"ga-properties","name":"","signature":"Properties: none, an object, or a function","summary":"","section":true},{"file":"game-actions.html","page":"Game actions","id":"ga-where","name":"","signature":"Where an action goes","summary":"","section":true},{"file":"game-actions.html","page":"Game actions","id":"ga-defaults","name":"","signature":"What an action affects by default","summary":"","section":true},{"file":"game-actions.html","page":"Game actions","id":"ga-legality","name":"","signature":"Legality","summary":"","section":true},{"file":"game-actions.html","page":"Game actions","id":"ga-reference","name":"","signature":"Reference","summary":"","section":true},{"file":"effects.html","page":"Effects","id":"ef-addFaction","name":"addFaction","signature":"addFaction(faction)","summary":"The card gains a clan symbol: \"Attached character gains the [clan-crane] clan symbol.\""},{"file":"effects.html","page":"Effects","id":"ef-addKeyword","name":"addKeyword","signature":"addKeyword(keyword)","summary":"The card gains a keyword: \"Attached character gains pride.\""},{"file":"effects.html","page":"Effects","id":"ef-addTrait","name":"addTrait","signature":"addTrait(trait)","summary":"The card gains a trait: \"Attached character gains Tattooed.\""},{"file":"effects.html","page":"Effects","id":"ef-blank","name":"blank","signature":"blank(blankTraits?)","summary":"The card treats its printed text box as blank: \"Attached character loses all printed abilities.\""},{"file":"effects.html","page":"Effects","id":"ef-changeType","name":"changeType","signature":"changeType(type)","summary":"The card's type becomes type: \"turn it into a character\", \"attach this card … as an attachment\"."},{"file":"effects.html","page":"Effects","id":"ef-copyCard","name":"copyCard copyProvince","signature":"copyCard(character)","summary":"The card \"becomes a copy of\" another character or province: it takes the other card's name, printed traits, printed faction and abilities."},{"file":"effects.html","page":"Effects","id":"ef-attachmentMilitarySkillModifier","name":"attachmentMilitarySkillModifier attachmentPoliticalSkillModifier","signature":"attachmentMilitarySkillModifier(value)","summary":"An attachment's skill bonus: \"+X [conflict-military]\" printed on an attachment, where X is computed."},{"file":"effects.html","page":"Effects","id":"ef-calculatePrintedMilitarySkill","name":"calculatePrintedMilitarySkill","signature":"calculatePrintedMilitarySkill(func)","summary":"Computes a printed [conflict-military] skill of X: \"X is equal to the number of cards in your opponent's hand.\""},{"file":"effects.html","page":"Effects","id":"ef-canContributeGloryWhileBowed","name":"canContributeGloryWhileBowed","signature":"canContributeGloryWhileBowed()","summary":"\"This character contributes its glory to glory counts even while bowed.\""},{"file":"effects.html","page":"Effects","id":"ef-canContributeWhileBowed","name":"canContributeWhileBowed","signature":"canContributeWhileBowed()","summary":"\"Bowed participating characters contribute their skill toward the resolution of the conflict.\""},{"file":"effects.html","page":"Effects","id":"ef-cannotContribute","name":"cannotContribute","signature":"cannotContribute(func)","summary":"Some characters \"do not count their skill toward the resolution of this conflict\"."},{"file":"effects.html","page":"Effects","id":"ef-changeConflictSkillFunction","name":"changeConflictSkillFunction","signature":"changeConflictSkillFunction(func)","summary":"\"While resolving this conflict, characters count their glory instead of their skill\": replaces what each counted character adds to its side."},{"file":"effects.html","page":"Effects","id":"ef-changeConflictSkillFunctionPlayer","name":"changeConflictSkillFunctionPlayer","signature":"changeConflictSkillFunctionPlayer(func)","summary":"Like changeConflictSkillFunction, but only for characters the affected player controls: \"attacking characters cannot have their skills increased by attachment cards\"."},{"file":"effects.html","page":"Effects","id":"ef-changeContributionFunction","name":"changeContributionFunction","signature":"changeContributionFunction(func)","summary":"Changes what one character contributes to the conflict: \"that character contributes its printed [conflict-military] skill\"."},{"file":"effects.html","page":"Effects","id":"ef-changePlayerGloryModifier","name":"changePlayerGloryModifier","signature":"changePlayerGloryModifier(value)","summary":"\"This holding adds +3 to your side during each glory count.\""},{"file":"effects.html","page":"Effects","id":"ef-changePlayerSkillModifier","name":"changePlayerSkillModifier","signature":"changePlayerSkillModifier(value)","summary":"\"Add +3 to your skill during conflict resolution\": changes the player's total, not a character's skill."},{"file":"effects.html","page":"Effects","id":"ef-contributeToConflict","name":"contributeToConflict","signature":"contributeToConflict(player)","summary":"A character that isn't participating \"contributes its skill to your side\"."},{"file":"effects.html","page":"Effects","id":"ef-attachmentCardCondition","name":"attachmentCardCondition","signature":"attachmentCardCondition(func)","summary":"The attachment can only be on a character that passes func: \"Character with printed [conflict-military] skill 3 or higher only.\""},{"file":"effects.html","page":"Effects","id":"ef-attachmentFactionRestriction","name":"attachmentFactionRestriction attachmentTraitRestriction","signature":"attachmentFactionRestriction(factions)","summary":"\"Attach to a [clan-lion] character\", \"Cavalry character only\": the parent must have one of the listed factions or traits."},{"file":"effects.html","page":"Effects","id":"ef-attachmentLimit","name":"attachmentLimit","signature":"attachmentLimit(amount)","summary":"\"Limit 1 per character\": a character may hold at most amount copies of this attachment."},{"file":"effects.html","page":"Effects","id":"ef-attachmentMyControlOnly","name":"attachmentMyControlOnly attachmentOpponentControlOnly attachmentUniqueRestriction","signature":"attachmentMyControlOnly()","summary":"\"Attach to a character you control\", \"Attach to a character you do not control\", \"Attach to a unique character\"."},{"file":"effects.html","page":"Effects","id":"ef-attachmentRestrictTraitAmount","name":"attachmentRestrictTraitAmount","signature":"attachmentRestrictTraitAmount(object)","summary":"\"Limit 1 Title per character\": a character may hold at most n attachments with the trait."},{"file":"effects.html","page":"Effects","id":"ef-cannotHaveOtherRestrictedAttachments","name":"cannotHaveOtherRestrictedAttachments","signature":"cannotHaveOtherRestrictedAttachments(card)","summary":"\"Attached character may not have other restricted attachments.\" An effect on the character, not on the attachment."},{"file":"effects.html","page":"Effects","id":"ef-cannotApplyLastingEffects","name":"cannotApplyLastingEffects","signature":"cannotApplyLastingEffects(condition)","summary":"Lasting effects of a kind can't be put on the card: \"cannot have its skills reduced (… lasting effects …)\"."},{"file":"effects.html","page":"Effects","id":"ef-cannotBeDeclaredAsAttacker","name":"cannotBeDeclaredAsAttacker cannotBeDeclaredAsDefender","signature":"cannotBeDeclaredAsAttacker()","summary":"\"This character cannot be declared as an attacker / a defender.\""},{"file":"effects.html","page":"Effects","id":"ef-cannotParticipateAsAttacker","name":"cannotParticipateAsAttacker cannotParticipateAsDefender","signature":"cannotParticipateAsAttacker(type?)","summary":"\"This character cannot participate in conflicts as an attacker\", \"Attached character cannot participate in [conflict-military] conflicts.\""},{"file":"effects.html","page":"Effects","id":"ef-cannotReceiveDishonorToken","name":"cannotReceiveDishonorToken cannotReceiveHonorToken cannotReceiveTaintedToken","signature":"cannotReceiveDishonorToken()","summary":"\"Characters cannot receive dishonored status tokens\", and the same for honored and tainted tokens."},{"file":"effects.html","page":"Effects","id":"ef-cannotTriggerAbilities","name":"cannotTriggerAbilities","signature":"cannotTriggerAbilities()","summary":"\"Characters in your opponent's home cannot trigger abilities\": the card's actions and triggered abilities can't be used."},{"file":"effects.html","page":"Effects","id":"ef-cardCannot","name":"cardCannot","signature":"cardCannot(properties)","summary":"The card \"cannot be bowed\", \"cannot be chosen as the target of an opponent's event\", and so on."},{"file":"effects.html","page":"Effects","id":"ef-charactersCannot","name":"charactersCannot","signature":"charactersCannot(properties)","summary":"\"Abilities on characters cannot be triggered this conflict\": a restriction on the current conflict, scoped to attempts whose source is a character."},{"file":"effects.html","page":"Effects","id":"ef-doesNotBow","name":"doesNotBow","signature":"doesNotBow()","summary":"\"This character does not bow as a result of conflict resolution.\""},{"file":"effects.html","page":"Effects","id":"ef-doesNotReady","name":"doesNotReady","signature":"doesNotReady()","summary":"\"Attached character does not ready during the regroup phase.\""},{"file":"effects.html","page":"Effects","id":"ef-addElement","name":"addElement","signature":"addElement(element)","summary":"\"The contested ring gains each of the attacked province's elements.\""},{"file":"effects.html","page":"Effects","id":"ef-addElementAsAttacker","name":"addElementAsAttacker","signature":"addElementAsAttacker(element)","summary":"\"While this character is attacking, the contested ring gains the [element-air] element.\""},{"file":"effects.html","page":"Effects","id":"ef-cannotDeclareRing","name":"cannotDeclareRing","signature":"cannotDeclareRing(match)","summary":"\"That player cannot declare conflicts of that ring's element this phase.\""},{"file":"effects.html","page":"Effects","id":"ef-cannotResolveRings","name":"cannotResolveRings","signature":"cannotResolveRings()","summary":"\"Cancel all ring effects until the end of the conflict\" for the affected players."},{"file":"effects.html","page":"Effects","id":"ef-canOnlyBeDeclaredAsAttackerWithElement","name":"canOnlyBeDeclaredAsAttackerWithElement","signature":"canOnlyBeDeclaredAsAttackerWithElement(element)","summary":"\"This character cannot be declared as an attacker except during [element-fire] conflicts.\""},{"file":"effects.html","page":"Effects","id":"ef-considerRingAsClaimed","name":"considerRingAsClaimed","signature":"considerRingAsClaimed(match)","summary":"\"You are considered to have that ring in your claimed ring pool.\""},{"file":"effects.html","page":"Effects","id":"ef-additionalAttackedProvince","name":"additionalAttackedProvince","signature":"additionalAttackedProvince(province)","summary":"\"The conflict is also at that province.\""},{"file":"effects.html","page":"Effects","id":"ef-additionalCardPlayed","name":"additionalCardPlayed","signature":"additionalCardPlayed(amount?)","summary":"\"You are considered to have played an additional card in each conflict.\""},{"file":"effects.html","page":"Effects","id":"ef-additionalCharactersInConflict","name":"additionalCharactersInConflict","signature":"additionalCharactersInConflict(amount)","summary":"\"You are considered to control an additional character in this conflict.\""},{"file":"effects.html","page":"Effects","id":"ef-additionalConflict","name":"additionalConflict","signature":"additionalConflict(type?)","summary":"\"You may declare an additional [conflict-military] conflict this phase.\""},{"file":"effects.html","page":"Effects","id":"ef-cannotBeAttacked","name":"cannotBeAttacked","signature":"cannotBeAttacked()","summary":"\"That province cannot be attacked this round.\" Put it on a province."},{"file":"effects.html","page":"Effects","id":"ef-cannotDeclareConflictsOfType","name":"cannotDeclareConflictsOfType","signature":"cannotDeclareConflictsOfType(type)","summary":"\"… cannot declare [conflict-military] conflicts this phase.\""},{"file":"effects.html","page":"Effects","id":"ef-cannotHaveConflictsDeclaredOfType","name":"cannotHaveConflictsDeclaredOfType","signature":"cannotHaveConflictsDeclaredOfType(type)","summary":"\"[conflict-political] conflicts cannot be declared against this holding's province.\" Put it on a province."},{"file":"effects.html","page":"Effects","id":"ef-canOnlyBeDeclaredAsAttackerWithCondition","name":"canOnlyBeDeclaredAsAttackerWithCondition","signature":"canOnlyBeDeclaredAsAttackerWithCondition(condition)","summary":"\"This character cannot be declared as an attacker … unless a unique character is attacking.\""},{"file":"effects.html","page":"Effects","id":"ef-conflictIgnoreStatusTokens","name":"conflictIgnoreStatusTokens","signature":"conflictIgnoreStatusTokens()","summary":"Status tokens are ignored for this conflict's participants and its province."},{"file":"effects.html","page":"Effects","id":"ef-defendersChosenFirstDuringConflict","name":"defendersChosenFirstDuringConflict","signature":"defendersChosenFirstDuringConflict(amountOfAttackers)","summary":"\"Your opponent declares defenders for this conflict. Then declare the conflict … You must declare a number of attackers equal to the number you chose.\" Put it on the attacking player."},{"file":"effects.html","page":"Effects","id":"ef-forceConflictDeclarationType","name":"forceConflictDeclarationType","signature":"forceConflictDeclarationType(type)","summary":"\"You must declare your conflicts as [conflict-political] conflicts.\""},{"file":"effects.html","page":"Effects","id":"ef-forceConflictUnopposed","name":"forceConflictUnopposed","signature":"forceConflictUnopposed()","summary":"\"Each conflict this character wins while attacking is considered to be unopposed.\""},{"file":"effects.html","page":"Effects","id":"ef-additionalPlayCost","name":"additionalPlayCost","signature":"additionalPlayCost(func)","summary":"\"As an additional cost for your opponent to play an event during this conflict, that opponent must give you 1 honor.\""},{"file":"effects.html","page":"Effects","id":"ef-additionalTriggerCost","name":"additionalTriggerCost additionalTriggerCostForCard","signature":"additionalTriggerCost(func)","summary":"\"As an additional cost for your opponent to trigger a character ability …\" (player) and \"As an additional cost to trigger an ability on attached character …\" (card)."},{"file":"effects.html","page":"Effects","id":"ef-alternateFatePool","name":"alternateFatePool","signature":"alternateFatePool(match)","summary":"\"You may spend fate from this character to pay for Spell cards\": another fate pool for the player's costs."},{"file":"effects.html","page":"Effects","id":"ef-cardCostToAttackMilitary","name":"cardCostToAttackMilitary","signature":"cardCostToAttackMilitary(amount?)","summary":"\"As an additional cost for a player to declare a character as an attacker during a [conflict-military] conflict, that player must discard 1 card from their hand.\" Put it on the characters."},{"file":"effects.html","page":"Effects","id":"ef-costToDeclareAnyParticipants","name":"costToDeclareAnyParticipants","signature":"costToDeclareAnyParticipants(properties)","summary":"\"As an additional cost to declare 1 or more defenders during a conflict at attached province, you must lose 1 honor.\" Put it on the declaring player."},{"file":"effects.html","page":"Effects","id":"ef-fateCostToAttack","name":"fateCostToAttack","signature":"fateCostToAttack(amount?)","summary":"\"This character cannot be declared as an attacker unless you spend 1 fate.\""},{"file":"effects.html","page":"Effects","id":"ef-fateCostToRingToDeclareConflictAgainst","name":"fateCostToRingToDeclareConflictAgainst","signature":"fateCostToRingToDeclareConflictAgainst(amount?)","summary":"\"As an additional cost to attack another province you control, your opponent must spend 1 fate to an unclaimed ring.\" Put it on the province."},{"file":"effects.html","page":"Effects","id":"ef-fateCostToTarget","name":"fateCostToTarget","signature":"fateCostToTarget(properties)","summary":"\"As an additional cost to choose a Tattooed character you control as a target of an event, the opponent playing that event must pay 1 additional fate.\" Put it on the card that is protected."},{"file":"effects.html","page":"Effects","id":"ef-gainExtraFateWhenPlayed","name":"gainExtraFateWhenPlayed","signature":"gainExtraFateWhenPlayed(amount?)","summary":"\"Characters played from this province enter play with 1 additional fate on them.\""},{"file":"effects.html","page":"Effects","id":"ef-increaseCost","name":"increaseCost","signature":"increaseCost(properties)","summary":"\"Increase the cost for each player to play each event by 1.\" It is reduceCost with the amount negated."},{"file":"effects.html","page":"Effects","id":"ef-legendaryFate","name":"legendaryFate","signature":"legendaryFate(amount?)","summary":"The character enters play with this much extra fate when played: the fate part of the Legendary X keyword."},{"file":"effects.html","page":"Effects","id":"ef-playerFateCostToTargetCard","name":"playerFateCostToTargetCard","signature":"playerFateCostToTargetCard(properties)","summary":"\"whenever an opponent chooses that character … as a target of a card ability, they must pay 1 additional fate as an additional cost.\" Put it on the player who would pay."},{"file":"effects.html","page":"Effects","id":"ef-reduceCost","name":"reduceCost","signature":"reduceCost(properties)","summary":"Reduces the cost to play matching cards: \"costs 1 less to play\"."},{"file":"effects.html","page":"Effects","id":"ef-reduceNextPlayedCardCost","name":"reduceNextPlayedCardCost","signature":"reduceNextPlayedCardCost(amount, match?)","summary":"\"the next non-event card you play … has its cost to play reduced by 1\""},{"file":"effects.html","page":"Effects","id":"ef-setApparentFate","name":"setApparentFate","signature":"setApparentFate(value)","summary":"\"each character in play is considered to have no fate on it\""},{"file":"effects.html","page":"Effects","id":"ef-canBeSeenWhenFacedown","name":"canBeSeenWhenFacedown","signature":"canBeSeenWhenFacedown()","summary":"\"You may look at facedown cards in each province you control.\""},{"file":"effects.html","page":"Effects","id":"ef-canBeTriggeredByOpponent","name":"canBeTriggeredByOpponent","signature":"canBeTriggeredByOpponent()","summary":"\"You may trigger the attacked province's ability as if you controlled that province.\""},{"file":"effects.html","page":"Effects","id":"ef-canPlayFromOutOfPlay","name":"canPlayFromOutOfPlay","signature":"canPlayFromOutOfPlay(player, playType?)","summary":"\"You may play each event in your opponent's discard pile as if it were in your hand.\" Put it on each card that becomes playable."},{"file":"effects.html","page":"Effects","id":"ef-canPlayFromOwn","name":"canPlayFromOwn canPlayFromOpponents","signature":"canPlayFromOwn(location, cards, sourceOfEffect, playType?)","summary":"\"This card can be played from your discard pile\", \"make them playable by both players\": the player may play cards from one of their own (or their opponent's) locations."},{"file":"effects.html","page":"Effects","id":"ef-entersPlayForOpponent","name":"entersPlayForOpponent","signature":"entersPlayForOpponent()","summary":"\"When you play this character, it enters play under the control of an opponent of your choice. (You may still put fate on it.)\""},{"file":"effects.html","page":"Effects","id":"ef-entersPlayWithStatus","name":"entersPlayWithStatus","signature":"entersPlayWithStatus(status)","summary":"\"Each character played from this province enters play honored.\""},{"file":"effects.html","page":"Effects","id":"ef-eventsCannotBeCancelled","name":"eventsCannotBeCancelled","signature":"eventsCannotBeCancelled()","summary":"\"Each event you play during this conflict cannot be canceled.\""},{"file":"effects.html","page":"Effects","id":"ef-additionalAction","name":"additionalAction","signature":"additionalAction(amount?)","summary":"\"You may take another action after this one.\""},{"file":"effects.html","page":"Effects","id":"ef-additionalActionAfterWindowCompleted","name":"additionalActionAfterWindowCompleted","signature":"additionalActionAfterWindowCompleted(amount?)","summary":"\"Before this conflict resolves, take an action.\""},{"file":"effects.html","page":"Effects","id":"ef-consideredLessHonorable","name":"consideredLessHonorable","signature":"consideredLessHonorable()","summary":"\"You are considered to be less honorable than each opponent.\""},{"file":"effects.html","page":"Effects","id":"ef-gainActionPhasePriority","name":"gainActionPhasePriority","signature":"gainActionPhasePriority()","summary":"\"The attacker has the first action opportunity this conflict.\""},{"file":"effects.html","page":"Effects","id":"ef-applyStatusTokensToDuel","name":"applyStatusTokensToDuel","signature":"applyStatusTokensToDuel()","summary":"\"Apply the skill modifiers from status tokens to each character's duel statistic.\""},{"file":"effects.html","page":"Effects","id":"ef-cannotBidInDuels","name":"cannotBidInDuels","signature":"cannotBidInDuels(num)","summary":"\"Your opponent cannot bid 1 or 5.\" A player effect, not a duel effect."},{"file":"effects.html","page":"Effects","id":"ef-duelIgnorePrintedSkill","name":"duelIgnorePrintedSkill","signature":"duelIgnorePrintedSkill()","summary":"\"Characters do not contribute their printed statistic to the resolution of this duel.\""},{"file":"effects.html","page":"Effects","id":"ef-ignoreDuelSkill","name":"ignoreDuelSkill","signature":"ignoreDuelSkill()","summary":"No participant's skill counts in the duel; only modifiers and bids do."},{"file":"effects.html","page":"Effects","id":"ef-modifyDuelistSkill","name":"modifyDuelistSkill","signature":"modifyDuelistSkill(value, duel)","summary":"Changes one character's contribution to one duel, without changing its skill elsewhere."},{"file":"effects.html","page":"Effects","id":"ef-modifyDuelTotal","name":"modifyDuelTotal","signature":"modifyDuelTotal(properties)","summary":"\"add 2 to your duel total\": changes one side's total, not a character's skill."},{"file":"effects.html","page":"Effects","id":"ef-winDuel","name":"winDuel","signature":"winDuel(duel)","summary":"The challenger wins this duel outright."},{"file":"effects.html","page":"Effects","id":"ef-winDuelTies","name":"winDuelTies","signature":"winDuelTies()","summary":"The character's side wins the duel on a tie."},{"file":"effects.html","page":"Effects","id":"ef-gainAbility","name":"gainAbility","signature":"gainAbility","summary":"The target card gains an action, a triggered ability or a constant ability. Write the ability with the same builder as the card's own abilities (see the builder); inside it, context.source is the card that gains it, while this is still the card that grants it."},{"file":"effects.html","page":"Effects","id":"ef-addFlag","name":"addFlag addPlayerFlag","signature":"addFlag(flag)","summary":"Marks a card or player with a name, for the card's own code to check later: \"if this card was not attached this round\", \"the first time this round you have triggered …\"."},{"file":"effects.html","page":"Effects","id":"ef-customDetachedCard","name":"customDetachedCard customDetachedPlayer","signature":"customDetachedCard(properties)","summary":"Runs card code when the effect starts on a target and when it ends, for something no other effect does."},{"file":"effects.html","page":"Effects","id":"ef-customFatePhaseFateRemoval","name":"customFatePhaseFateRemoval","signature":"customFatePhaseFateRemoval(func)","summary":"\"When fate would be removed from characters during the fate phase, instead distribute that fate among unclaimed rings as evenly as possible.\""},{"file":"effects.html","page":"Effects","id":"ef-customRefillProvince","name":"customRefillProvince","signature":"customRefillProvince(refillFunc)","summary":"\"Each time you would refill attached province with a card, instead …\" Put it on the province card."},{"file":"effects.html","page":"Effects","id":"ef-delayedEffect","name":"delayedEffect","signature":"delayedEffect(properties)","summary":"Does something later, when an event happens or a condition becomes true: \"If it wins the conflict, honor it\", \"If an opponent is more honorable than you, discard this character\"."},{"file":"effects.html","page":"Effects","id":"ef-modifyBaseMilitarySkillMultiplier","name":"modifyBaseMilitarySkillMultiplier modifyBasePoliticalSkillMultiplier","signature":"modifyBaseMilitarySkillMultiplier(value)","summary":"Multiplies the character's base military (or political) skill, as in \"double that character's base [conflict-military] skill\" (Way of the Lion)."},{"file":"effects.html","page":"Effects","id":"ef-modifyBothSkills","name":"modifyBothSkills","signature":"modifyBothSkills(value)","summary":"Gives +X military and +X political skill. Status tokens use this effect too."},{"file":"effects.html","page":"Effects","id":"ef-modifyMilitarySkill","name":"modifyMilitarySkill modifyPoliticalSkill","signature":"modifyMilitarySkill(value)","summary":"Gives +X (or -X) military or political skill."},{"file":"effects.html","page":"Effects","id":"ef-modifyMilitarySkillMultiplier","name":"modifyMilitarySkillMultiplier modifyPoliticalSkillMultiplier","signature":"modifyMilitarySkillMultiplier(value)","summary":"Multiplies the character's current military (or political) skill: \"double this character's [conflict-military] skill\"."},{"file":"effects.html","page":"Effects","id":"ef-setBaseDash","name":"setBaseDash","signature":"setBaseDash(type)","summary":"Sets the character's base military or political skill to a dash."},{"file":"effects.html","page":"Effects","id":"ef-setBaseMilitarySkill","name":"setBaseMilitarySkill setBasePoliticalSkill","signature":"setBaseMilitarySkill(value)","summary":"Sets the character's base military (or political) skill. Modifiers still apply on top."},{"file":"effects.html","page":"Effects","id":"ef-setDash","name":"setDash","signature":"setDash(type)","summary":"Sets the character's current military or political skill to a dash, which counts as 0."},{"file":"effects.html","page":"Effects","id":"ef-setMilitarySkill","name":"setMilitarySkill setPoliticalSkill","signature":"setMilitarySkill(value)","summary":"Sets the character's current military (or political) skill to a value, ignoring every modifier: \"set that character's skill values to its printed values\"."},{"file":"effects.html","page":"Effects","id":"ef-switchAttachmentSkillModifiers","name":"switchAttachmentSkillModifiers","signature":"switchAttachmentSkillModifiers()","summary":"Switches an attachment's printed military and political skill bonuses. The effect goes on the attachment, not on the character."},{"file":"effects.html","page":"Effects","id":"ef-switchBaseSkills","name":"switchBaseSkills","signature":"switchBaseSkills()","summary":"Switches the character's base military and political skills."},{"file":"effects.html","page":"Effects","id":"ef-modifyGlory","name":"modifyGlory","signature":"modifyGlory(value)","summary":"Gives +X (or -X) glory."},{"file":"effects.html","page":"Effects","id":"ef-setBaseGlory","name":"setBaseGlory","signature":"setBaseGlory(value)","summary":"Sets the character's base glory; modifyGlory effects still apply on top."},{"file":"effects.html","page":"Effects","id":"ef-setGlory","name":"setGlory","signature":"setGlory(value)","summary":"Sets the character's glory, ignoring every other glory effect: \"set that character’s glory to 0\"."},{"file":"effects.html","page":"Effects","id":"ef-honorStatusDoesNotAffectLeavePlay","name":"honorStatusDoesNotAffectLeavePlay","signature":"honorStatusDoesNotAffectLeavePlay()","summary":"When the character leaves play, its controller doesn't gain or lose honor for its honored or dishonored status."},{"file":"effects.html","page":"Effects","id":"ef-honorStatusDoesNotModifySkill","name":"honorStatusDoesNotModifySkill","signature":"honorStatusDoesNotModifySkill()","summary":"The character's status tokens don't change its skill."},{"file":"effects.html","page":"Effects","id":"ef-honorStatusReverseModifySkill","name":"honorStatusReverseModifySkill","signature":"honorStatusReverseModifySkill()","summary":"The dishonored token adds the character's glory to its skills instead of subtracting it."},{"file":"effects.html","page":"Effects","id":"ef-statusTokensDoNotDecreaseSkill","name":"statusTokensDoNotDecreaseSkill","signature":"statusTokensDoNotDecreaseSkill()","summary":"\"Does not have its skills decreased by status tokens\": a status-token modifier that would lower the character's skill is set to 0."},{"file":"effects.html","page":"Effects","id":"ef-taintedStatusDoesNotCostHonor","name":"taintedStatusDoesNotCostHonor","signature":"taintedStatusDoesNotCostHonor()","summary":"The tainted token on this character no longer costs 1 honor to declare it as an attacker or defender."},{"file":"effects.html","page":"Effects","id":"ef-treatStatusTokenAs","name":"treatStatusTokenAs","signature":"treatStatusTokenAs(token, status)","summary":"Treats a status token as if it were a different status token: \"treat one of the chosen status tokens as if it were the other\"."},{"file":"effects.html","page":"Effects","id":"ef-loseFaction","name":"loseFaction","signature":"loseFaction(faction)","summary":"The card loses a clan affiliation: \"remove that character's clan affiliation\"."},{"file":"effects.html","page":"Effects","id":"ef-loseKeyword","name":"loseKeyword","signature":"loseKeyword(keyword)","summary":"The card loses a keyword: \"loses covert\"."},{"file":"effects.html","page":"Effects","id":"ef-loseTrait","name":"loseTrait","signature":"loseTrait(trait)","summary":"The card loses a trait: \"loses Bushi\"."},{"file":"effects.html","page":"Effects","id":"ef-replacePrintedElement","name":"replacePrintedElement","signature":"replacePrintedElement(value)","summary":"Replaces one printed element symbol on a card with a different element."},{"file":"effects.html","page":"Effects","id":"ef-gainAllAbilities","name":"gainAllAbilities","signature":"gainAllAbilities(card, printedOnly?)","summary":"The target gains each ability of another card: \"gains each printed ability of the chosen character\"."},{"file":"effects.html","page":"Effects","id":"ef-gainAllAbilitiesDynamic","name":"gainAllAbilitiesDynamic","signature":"gainAllAbilitiesDynamic(match, printedAbilitiesOnly?)","summary":"The target gains each triggered ability (actions, reactions, interrupts) of a changing set of cards: \"gains each triggered ability on each other participating dishonored character\"."},{"file":"effects.html","page":"Effects","id":"ef-gainPlayAction","name":"gainPlayAction","signature":"gainPlayAction(playActionClass)","summary":"Gives the card another way to be played: \"You may play cards in adjacent provinces as if they were in your hand.\""},{"file":"effects.html","page":"Effects","id":"ef-increaseLimitOnAbilities","name":"increaseLimitOnAbilities","signature":"increaseLimitOnAbilities(abilities?)","summary":"\"You may trigger each of attached character's triggered abilities an additional time each round (or specified period).\""},{"file":"effects.html","page":"Effects","id":"ef-increaseLimitOnPrintedAbilities","name":"increaseLimitOnPrintedAbilities","signature":"increaseLimitOnPrintedAbilities(ability?)","summary":"\"You may trigger each ability printed on that character an additional time this round (or specified period).\""},{"file":"effects.html","page":"Effects","id":"ef-loseAllNonKeywordAbilities","name":"loseAllNonKeywordAbilities","signature":"loseAllNonKeywordAbilities()","summary":"The card loses each non-keyword ability, printed or gained."},{"file":"effects.html","page":"Effects","id":"ef-loseGainedAbilities","name":"loseGainedAbilities","signature":"loseGainedAbilities()","summary":"The card loses all gained abilities; printed ones are kept. \"With Air affinity, it also loses all gained abilities.\""},{"file":"effects.html","page":"Effects","id":"ef-registerToPlayFromOutOfPlay","name":"registerToPlayFromOutOfPlay","signature":"registerToPlayFromOutOfPlay()","summary":"Makes the card's reactions and interrupts listen for their triggers while it is out of play, so an event that is a reaction or interrupt can be played from there."},{"file":"effects.html","page":"Effects","id":"ef-suppressEffects","name":"suppressEffects","signature":"suppressEffects(condition)","summary":"Effects on the target that match condition are ignored: \"cannot have its skills reduced. (This includes by attachments, lasting effects, and status tokens.)\""},{"file":"effects.html","page":"Effects","id":"ef-immunity","name":"immunity","signature":"immunity(properties)","summary":"\"Immune to opponent's ring effects\", \"immune to events\": the card can't be chosen as a target of, or affected by, anything from the given sources."},{"file":"effects.html","page":"Effects","id":"ef-mustBeChosen","name":"mustBeChosen","signature":"mustBeChosen(properties)","summary":"\"This character must be chosen as the target of each event, if able.\""},{"file":"effects.html","page":"Effects","id":"ef-playerCannot","name":"playerCannot","signature":"playerCannot(properties)","summary":"The player can't do something: \"each player cannot spend fate\", \"that player cannot play copies of the named card this phase\"."},{"file":"effects.html","page":"Effects","id":"ef-unlessActionCost","name":"unlessActionCost","signature":"unlessActionCost(properties)","summary":"A game action can only affect the card if a cost is paid: \"cannot ready unless its controller discards the top 3 cards of his or her conflict deck\"."},{"file":"effects.html","page":"Effects","id":"ef-honorCostToDeclare","name":"honorCostToDeclare","signature":"honorCostToDeclare(properties?)","summary":"\"As an additional cost to declare this character as an attacker or defender, you lose 2 honor.\""},{"file":"effects.html","page":"Effects","id":"ef-limitLegalAttackers","name":"limitLegalAttackers","signature":"limitLegalAttackers(matchFunc)","summary":"Only characters that pass matchFunc can be declared as attackers by this player."},{"file":"effects.html","page":"Effects","id":"ef-mustBeDeclaredAsAttacker","name":"mustBeDeclaredAsAttacker","signature":"mustBeDeclaredAsAttacker(type?)","summary":"The character must be declared as an attacker when its controller declares a conflict, if able."},{"file":"effects.html","page":"Effects","id":"ef-mustBeDeclaredAsAttackerIfType","name":"mustBeDeclaredAsAttackerIfType","signature":"mustBeDeclaredAsAttackerIfType(type?)","summary":"\"Attached character must commit to each [conflict-military] conflict, if able\": forced to attack only once the player has chosen a conflict of that type."},{"file":"effects.html","page":"Effects","id":"ef-mustBeDeclaredAsDefender","name":"mustBeDeclaredAsDefender","signature":"mustBeDeclaredAsDefender(type?)","summary":"\"The chosen character must be declared as a defender in this conflict, if able.\""},{"file":"effects.html","page":"Effects","id":"ef-mustDeclareMaximumAttackers","name":"mustDeclareMaximumAttackers","signature":"mustDeclareMaximumAttackers(type?)","summary":"\"They must attack with as many of their characters as are able.\""},{"file":"effects.html","page":"Effects","id":"ef-provideConflictDeclarationType","name":"provideConflictDeclarationType","signature":"provideConflictDeclarationType(type)","summary":"The player may declare any of their conflicts as this type, in addition to the normal types."},{"file":"effects.html","page":"Effects","id":"ef-restrictNumberOfDefenders","name":"restrictNumberOfDefenders","signature":"restrictNumberOfDefenders(value)","summary":"\"Your opponent cannot declare more than one defender.\""},{"file":"effects.html","page":"Effects","id":"ef-setConflictDeclarationType","name":"setConflictDeclarationType","signature":"setConflictDeclarationType(type)","summary":"\"Each conflict declared this phase is [conflict-military] instead of its normal type.\""},{"file":"effects.html","page":"Effects","id":"ef-setMaxConflicts","name":"setMaxConflicts","signature":"setMaxConflicts(amount)","summary":"\"Cannot declare more than one conflict … this round.\""},{"file":"effects.html","page":"Effects","id":"ef-strongholdCanBeAttacked","name":"strongholdCanBeAttacked","signature":"strongholdCanBeAttacked()","summary":"\"You may attack that player's stronghold this phase\", even with fewer than 3 broken provinces."},{"file":"effects.html","page":"Effects","id":"ef-modifyConflictElementsToResolve","name":"modifyConflictElementsToResolve","signature":"modifyConflictElementsToResolve(value)","summary":"The winner resolves more ring elements: \"instead of choosing an element to resolve, resolve each of that ring's effects\"."},{"file":"effects.html","page":"Effects","id":"ef-modifyUnopposedHonorLoss","name":"modifyUnopposedHonorLoss","signature":"modifyUnopposedHonorLoss(amount?)","summary":"Changes the honor the defender loses for an unopposed conflict."},{"file":"effects.html","page":"Effects","id":"ef-noUnopposedHonorLoss","name":"noUnopposedHonorLoss","signature":"noUnopposedHonorLoss()","summary":"\"You do not lose honor from this conflict being unopposed.\""},{"file":"effects.html","page":"Effects","id":"ef-participatesFromHome","name":"participatesFromHome","signature":"participatesFromHome()","summary":"\"This character is considered to be participating in each conflict …\" while it stays at home."},{"file":"effects.html","page":"Effects","id":"ef-resolveConflictEarly","name":"resolveConflictEarly","signature":"resolveConflictEarly()","summary":"\"After your opponent's next action opportunity, resolve the conflict as if both players passed consecutively.\""},{"file":"effects.html","page":"Effects","id":"ef-setConflictTotalSkill","name":"setConflictTotalSkill","signature":"setConflictTotalSkill(value)","summary":"\"Both players count 0 total skill in the conflict.\""},{"file":"effects.html","page":"Effects","id":"ef-modifyBaseProvinceStrength","name":"modifyBaseProvinceStrength","signature":"modifyBaseProvinceStrength(value)","summary":"Adds to the province's base strength, e.g. for a strength of X."},{"file":"effects.html","page":"Effects","id":"ef-modifyProvinceStrength","name":"modifyProvinceStrength","signature":"modifyProvinceStrength(value)","summary":"\"the attacked province gets +4 strength this conflict\""},{"file":"effects.html","page":"Effects","id":"ef-modifyProvinceStrengthBonus","name":"modifyProvinceStrengthBonus","signature":"modifyProvinceStrengthBonus(value)","summary":"\"Each holding you control gets +2 bonus strength.\" Goes on the holding, not the province."},{"file":"effects.html","page":"Effects","id":"ef-modifyProvinceStrengthMultiplier","name":"modifyProvinceStrengthMultiplier","signature":"modifyProvinceStrengthMultiplier(value)","summary":"\"double that province's strength\""},{"file":"effects.html","page":"Effects","id":"ef-provinceCannotHaveSkillIncreased","name":"provinceCannotHaveSkillIncreased","signature":"provinceCannotHaveSkillIncreased()","summary":"The province gets no positive strength bonus from the holding or stronghold in it."},{"file":"effects.html","page":"Effects","id":"ef-refillProvinceTo","name":"refillProvinceTo","signature":"refillProvinceTo(refillAmount)","summary":"\"When you would refill this province, refill it to 3 cards instead of 1.\""},{"file":"effects.html","page":"Effects","id":"ef-setBaseProvinceStrength","name":"setBaseProvinceStrength","signature":"setBaseProvinceStrength(value)","summary":"\"Set the base strength of the attacked province to 1\"; modifiers still apply."},{"file":"effects.html","page":"Effects","id":"ef-setProvinceStrength","name":"setProvinceStrength","signature":"setProvinceStrength(value)","summary":"\"Set the strength of that province to 0\", ignoring every other strength effect."},{"file":"effects.html","page":"Effects","id":"ef-setProvinceStrengthBonus","name":"setProvinceStrengthBonus","signature":"setProvinceStrengthBonus(value)","summary":"Sets a holding's strength bonus, ignoring its printed bonus and every modifyProvinceStrengthBonus."},{"file":"effects.html","page":"Effects","id":"ef-limitHonorGainPerPhase","name":"limitHonorGainPerPhase","signature":"limitHonorGainPerPhase(amount)","summary":"\"Each opponent cannot gain more than 2 honor each phase.\""},{"file":"effects.html","page":"Effects","id":"ef-modifyCardsDrawnInDrawPhase","name":"modifyCardsDrawnInDrawPhase","signature":"modifyCardsDrawnInDrawPhase(amount)","summary":"\"Each player draws 2 fewer cards from honor bids during the draw phase (to a minimum of 1).\""},{"file":"effects.html","page":"Effects","id":"ef-playerDelayedEffect","name":"playerDelayedEffect","signature":"playerDelayedEffect(properties)","summary":"Resolves a game action on the player later, when an event happens. The card version is delayedEffect."},{"file":"effects.html","page":"Effects","id":"ef-restartDynastyPhase","name":"restartDynastyPhase","signature":"restartDynastyPhase(source)","summary":"\"End the dynasty phase. Then there is an additional dynasty phase, during which players do not collect fate.\""},{"file":"effects.html","page":"Effects","id":"ef-satisfyAffinity","name":"satisfyAffinity","signature":"satisfyAffinity(traits)","summary":"The player counts as having affinity to these traits even without a character that has them."},{"file":"effects.html","page":"Effects","id":"ef-showTopConflictCard","name":"showTopConflictCard","signature":"showTopConflictCard(players?)","summary":"The top card of the player's conflict deck is shown: \"you may look at … the top card of your conflict deck\"."},{"file":"effects.html","page":"Effects","id":"ef-showTopDynastyCard","name":"showTopDynastyCard","signature":"showTopDynastyCard()","summary":"The top card of the player's dynasty deck is shown."},{"file":"effects.html","page":"Effects","id":"ef-hideWhenFaceUp","name":"hideWhenFaceUp","signature":"hideWhenFaceUp()","summary":"The card is shown facedown to everyone but its controller, even though it is faceup."},{"file":"effects.html","page":"Effects","id":"ef-modifyRestrictedAttachmentAmount","name":"modifyRestrictedAttachmentAmount","signature":"modifyRestrictedAttachmentAmount(value)","summary":"\"Each [clan-dragon] character you control can have an additional restricted attachment.\""},{"file":"effects.html","page":"Effects","id":"ef-removeFromGameInsteadOfLeavingPlay","name":"removeFromGameInsteadOfLeavingPlay","signature":"removeFromGameInsteadOfLeavingPlay(value?)","summary":"\"When this character would leave play, remove it from the game instead.\""},{"file":"effects.html","page":"Effects","id":"ef-takeControl","name":"takeControl","signature":"takeControl(player)","summary":"\"Take control of that character until the end of the conflict.\""},{"file":"effects.html","page":"Effects","id":"ef-basics","name":"","signature":"How effects work","summary":"An effect changes how the game treats a card, a player, a ring, a conflict or a duel for as long as it applies: +2 military skill, \"cannot be bowed\", an extra conflict. Effects don't happen once like game actions; they hold while their condition and duration hold, and the game recalculates them after every change. The factories are exported from server/game/effects.ts.","section":true},{"file":"effects.html","page":"Effects","id":"ef-where","name":"","signature":"Where an effect goes","summary":"","section":true},{"file":"effects.html","page":"Effects","id":"ef-values","name":"","signature":"Fixed and computed values","summary":"Some effects take a value or a function of the game state: modifyMilitarySkill(2) or modifyMilitarySkill((card, context) => card.attachments.length). A function is recalculated whenever the game state changes. The entries say which effects take one.","section":true},{"file":"effects.html","page":"Effects","id":"ef-several","name":"","signature":"Several effects at once","summary":"","section":true},{"file":"effects.html","page":"Effects","id":"ef-reference","name":"","signature":"Reference","summary":"","section":true},{"file":"costs.html","page":"Costs and limits","id":"co-bowParent","name":"bowParent","signature":"bowParent()","summary":"\"Bow attached character\": bows the character the source is attached to."},{"file":"costs.html","page":"Costs and limits","id":"co-bowSelf","name":"bowSelf","signature":"bowSelf()","summary":"\"Bow this character / this card\": bows the source."},{"file":"costs.html","page":"Costs and limits","id":"co-breakSelf","name":"breakSelf","signature":"breakSelf()","summary":"\"Break this province\": breaks the source province."},{"file":"costs.html","page":"Costs and limits","id":"co-discardSelf","name":"discardSelf","signature":"discardSelf()","summary":"\"Discard this card from your hand\": discards the source. Use it on an ability that works from the hand (.location(Location.Hand))."},{"file":"costs.html","page":"Costs and limits","id":"co-discardStatusTokenFromSelf","name":"discardStatusTokenFromSelf","signature":"discardStatusTokenFromSelf(status)","summary":"\"Discard an honored status token from this character\": discards the source's status token of that status. Its other tokens stay."},{"file":"costs.html","page":"Costs and limits","id":"co-dishonorSelf","name":"dishonorSelf","signature":"dishonorSelf()","summary":"\"Dishonor this character\": dishonors the source (an honored character becomes ordinary, an ordinary one dishonored)."},{"file":"costs.html","page":"Costs and limits","id":"co-putSelfIntoPlay","name":"putSelfIntoPlay","signature":"putSelfIntoPlay()","summary":"\"Put this character into play\": puts the source into play for the ability's player, at home, ordinary, with no fate."},{"file":"costs.html","page":"Costs and limits","id":"co-removeFateFromParent","name":"removeFateFromParent","signature":"removeFateFromParent()","summary":"\"Remove 1 fate from attached character\": removes 1 fate from the source's parent to the general pool."},{"file":"costs.html","page":"Costs and limits","id":"co-removeFateFromSelf","name":"removeFateFromSelf","signature":"removeFateFromSelf()","summary":"\"Remove 1 fate from this character\": removes 1 fate from the source to the general pool."},{"file":"costs.html","page":"Costs and limits","id":"co-removeSelfFromGame","name":"removeSelfFromGame","signature":"removeSelfFromGame(properties?)","summary":"\"Remove this card from the game\": moves the source to the removed-from-game area."},{"file":"costs.html","page":"Costs and limits","id":"co-returnSelfToHand","name":"returnSelfToHand","signature":"returnSelfToHand()","summary":"\"Return this card to your hand\": returns the source from play to its owner's hand."},{"file":"costs.html","page":"Costs and limits","id":"co-sacrificeSelf","name":"sacrificeSelf","signature":"sacrificeSelf()","summary":"\"Sacrifice this card\": discards the source from play as a sacrifice."},{"file":"costs.html","page":"Costs and limits","id":"co-switchLocation","name":"switchLocation","signature":"switchLocation()","summary":"\"Move this character home or to the conflict\": sends the source home when it is participating, otherwise moves it into the conflict. The player is not asked; where the character is decides."},{"file":"costs.html","page":"Costs and limits","id":"co-bow","name":"bow","signature":"bow(properties)","summary":"\"Bow a … character you control\": the player chooses a card and bows it."},{"file":"costs.html","page":"Costs and limits","id":"co-breakProvince","name":"breakProvince","signature":"breakProvince(properties)","summary":"\"Break a (friendly) province\": the player chooses a province and breaks it."},{"file":"costs.html","page":"Costs and limits","id":"co-discardCard","name":"discardCard","signature":"discardCard(properties?)","summary":"\"Discard a card from your hand\": the player chooses cards and discards them."},{"file":"costs.html","page":"Costs and limits","id":"co-discardHonoredToken","name":"discardHonoredToken","signature":"discardHonoredToken(properties)","summary":"\"Discard an honored status token from a (friendly) character\": the player chooses a character and discards its honored status token."},{"file":"costs.html","page":"Costs and limits","id":"co-dishonor","name":"dishonor","signature":"dishonor(properties?)","summary":"\"Dishonor a (friendly) character\": the player chooses a character and dishonors it."},{"file":"costs.html","page":"Costs and limits","id":"co-dishonorAndSacrifice","name":"dishonorAndSacrifice","signature":"dishonorAndSacrifice(properties)","summary":"\"Dishonor and sacrifice a … character\": the player chooses a card, which is dishonored and sacrificed together."},{"file":"costs.html","page":"Costs and limits","id":"co-moveToConflict","name":"moveToConflict","signature":"moveToConflict(properties)","summary":"\"Move a … character you control to the conflict\": the player chooses a character and moves it into the conflict."},{"file":"costs.html","page":"Costs and limits","id":"co-removeFate","name":"removeFate","signature":"removeFate(properties)","summary":"\"Remove 1 fate from a (friendly) character\": the player chooses a character and removes 1 fate from it to the general pool."},{"file":"costs.html","page":"Costs and limits","id":"co-removeFromGame","name":"removeFromGame","signature":"removeFromGame(properties)","summary":"\"Remove … from the game\": the player chooses cards and removes them from the game, usually from a discard pile."},{"file":"costs.html","page":"Costs and limits","id":"co-returnToDeck","name":"returnToDeck","signature":"returnToDeck(properties)","summary":"\"Put a (friendly) … on the top/bottom of your deck\": the player chooses a card and returns it to its owner's deck (dynasty or conflict, by the card)."},{"file":"costs.html","page":"Costs and limits","id":"co-returnToHand","name":"returnToHand","signature":"returnToHand(properties)","summary":"\"Return a (friendly) … to your hand\": the player chooses a card in play and returns it to its owner's hand."},{"file":"costs.html","page":"Costs and limits","id":"co-reveal","name":"reveal","signature":"reveal(properties)","summary":"\"Reveal a (friendly) facedown province\": the player chooses a card and turns it faceup."},{"file":"costs.html","page":"Costs and limits","id":"co-sacrifice","name":"sacrifice","signature":"sacrifice(properties)","summary":"\"Sacrifice a … character\": the player chooses cards and sacrifices them."},{"file":"costs.html","page":"Costs and limits","id":"co-shuffleIntoDeck","name":"shuffleIntoDeck","signature":"shuffleIntoDeck(properties)","summary":"\"Shuffle a card in one of your provinces back into your dynasty deck\": the player chooses a card and shuffles it into the dynasty deck."},{"file":"costs.html","page":"Costs and limits","id":"co-taint","name":"taint","signature":"taint(properties)","summary":"\"Taint a (friendly) …\": the player chooses a character or province and taints it."},{"file":"costs.html","page":"Costs and limits","id":"co-discardCardsOf","name":"discardCardsOf","signature":"discardCardsOf(cardFunc)","summary":"Discards the card or cards cardFunc returns."},{"file":"costs.html","page":"Costs and limits","id":"co-discardHand","name":"discardHand","signature":"discardHand()","summary":"\"Discard your hand\": discards every card in the player's hand."},{"file":"costs.html","page":"Costs and limits","id":"co-discardTopCardsFromDeck","name":"discardTopCardsFromDeck","signature":"discardTopCardsFromDeck(properties)","summary":"\"Discard the top N cards of your … deck\": moves the top cards of one of the player's decks to its discard pile."},{"file":"costs.html","page":"Costs and limits","id":"co-revealCardsOf","name":"revealCardsOf","signature":"revealCardsOf(cardFunc)","summary":"\"Reveal the top N cards of your conflict deck\": reveals the cards cardFunc returns."},{"file":"costs.html","page":"Costs and limits","id":"co-chooseFate","name":"chooseFate","signature":"chooseFate(type)","summary":"The engine's \"how much extra fate\" question when a character is played. Cards don't use it."},{"file":"costs.html","page":"Costs and limits","id":"co-giveFateToOpponent","name":"giveFateToOpponent","signature":"giveFateToOpponent(amount?)","summary":"\"Give your opponent N fate\": moves fate from the player's pool to the opponent's."},{"file":"costs.html","page":"Costs and limits","id":"co-giveHonorToOpponent","name":"giveHonorToOpponent","signature":"giveHonorToOpponent(amount?)","summary":"\"Give your opponent N honor\": transfers honor from the player to the opponent."},{"file":"costs.html","page":"Costs and limits","id":"co-payFate","name":"payFate","signature":"payFate(amount?)","summary":"\"Spend N fate\": the player loses fate from their pool. Not reduced by cost reducers."},{"file":"costs.html","page":"Costs and limits","id":"co-payFateToRing","name":"payFateToRing","signature":"payFateToRing(amount?, ringCondition?)","summary":"\"Spend 1 fate to an unclaimed ring\": the player chooses a ring and moves fate from their pool onto it."},{"file":"costs.html","page":"Costs and limits","id":"co-payHonor","name":"payHonor","signature":"payHonor(amount?, dueToStatusToken?)","summary":"\"Lose N honor\": the player loses honor."},{"file":"costs.html","page":"Costs and limits","id":"co-payReduceableFateCost","name":"payReduceableFateCost","signature":"payReduceableFateCost(ignoreType?)","summary":"The printed fate cost of the source, minus the cost reducers that apply. Every event gets it automatically; characters and other played cards get it from the engine."},{"file":"costs.html","page":"Costs and limits","id":"co-payTargetDependentFateCost","name":"payTargetDependentFateCost","signature":"payTargetDependentFateCost(targetName, ignoreType?)","summary":"The printed fate cost of the source, with the reducers that apply when it goes onto the card chosen as the target targetName: playing an attachment."},{"file":"costs.html","page":"Costs and limits","id":"co-discardCardsUpToVariableX","name":"discardCardsUpToVariableX","signature":"discardCardsUpToVariableX(amount)","summary":"\"Discard up to X cards from your hand\": the player chooses up to amount cards in hand and discards them."},{"file":"costs.html","page":"Costs and limits","id":"co-optionalOpponentLoseHonor","name":"optionalOpponentLoseHonor","signature":"optionalOpponentLoseHonor(prompt?, canPayFunc?)","summary":"\"Each opponent may choose to lose 1 honor\": asks the opponent whether to lose 1 honor."},{"file":"costs.html","page":"Costs and limits","id":"co-optionalTakeHonorFromOpponent","name":"optionalTakeHonorFromOpponent","signature":"optionalTakeHonorFromOpponent(canPayFunc?)","summary":"\"Each opponent may give you 1 honor\": asks the opponent \"Give an honor to your opponent?\" and transfers 1 honor on Yes."},{"file":"costs.html","page":"Costs and limits","id":"co-payOptionalFate","name":"payOptionalFate","signature":"payOptionalFate(amount, forcePayment?)","summary":"\"You may spend N fate\": asks \"Spend N fate?\" and takes the fate on Yes."},{"file":"costs.html","page":"Costs and limits","id":"co-payVariableFate","name":"payVariableFate","signature":"payVariableFate(properties)","summary":"\"Spend X fate\": the player picks X from a list and pays it."},{"file":"costs.html","page":"Costs and limits","id":"co-payVariableHonor","name":"payVariableHonor","signature":"payVariableHonor(amountFunc)","summary":"\"Lose up to N honor\" / \"lose 1 or more honor\": the player picks how much honor to lose, from 1."},{"file":"costs.html","page":"Costs and limits","id":"co-returnRings","name":"returnRings","signature":"returnRings(amount?, ringCondition?)","summary":"\"Return a ring from your claimed ring pool to the unclaimed ring pool\": the player chooses claimed rings one at a time and returns them."},{"file":"costs.html","page":"Costs and limits","id":"co-discardImperialFavor","name":"discardImperialFavor","signature":"discardImperialFavor()","summary":"\"Discard the Imperial Favor\": the player loses the Imperial Favor."},{"file":"costs.html","page":"Costs and limits","id":"co-nameCard","name":"nameCard","signature":"nameCard()","summary":"\"Name a card\": the player types a card name. Nothing is paid; the name is recorded."},{"file":"costs.html","page":"Costs and limits","id":"co-chooseOne","name":"chooseOne","signature":"chooseOne(options)","summary":"\"Spend 1 honor or 1 fate\": the player picks one of the costs by its label and pays it."},{"file":"costs.html","page":"Costs and limits","id":"co-optional","name":"optional","signature":"optional(cost)","summary":"\"You may pay X\": asks \"Pay optional cost?\" and pays the wrapped cost on Yes."},{"file":"costs.html","page":"Costs and limits","id":"co-unless","name":"unless","signature":"unless(condition, cost)","summary":"\"Pay X unless …\": nothing to pay while condition holds, otherwise the wrapped cost."},{"file":"costs.html","page":"Costs and limits","id":"li-fixed","name":"fixed","signature":"fixed(max)","summary":"N uses that never reset on a period."},{"file":"costs.html","page":"Costs and limits","id":"li-perConflict","name":"perConflict","signature":"perConflict(max)","summary":"\"per conflict\": resets when a conflict finishes."},{"file":"costs.html","page":"Costs and limits","id":"li-perConflictOpportunity","name":"perConflictOpportunity","signature":"perConflictOpportunity(max)","summary":"\"per conflict opportunity\": resets when a conflict finishes or a player passes a conflict."},{"file":"costs.html","page":"Costs and limits","id":"li-perGame","name":"perGame","signature":"perGame(max)","summary":"\"per game\": never resets on a period."},{"file":"costs.html","page":"Costs and limits","id":"li-perPhase","name":"perPhase","signature":"perPhase(max)","summary":"\"per phase\": resets when a phase ends."},{"file":"costs.html","page":"Costs and limits","id":"li-perRound","name":"perRound","signature":"perRound(max)","summary":"\"per round\": resets when the round ends. perRound(1) is every card ability's default limit."},{"file":"costs.html","page":"Costs and limits","id":"li-repeatable","name":"repeatable","signature":"repeatable(max, eventName)","summary":"A limit that resets on any game event you name; the period helpers above are built on it."},{"file":"costs.html","page":"Costs and limits","id":"li-unlimited","name":"unlimited","signature":"unlimited()","summary":"\"(Unlimited.)\": the ability is never at its limit. Use it with .limit() to lift the once-per-round default."},{"file":"costs.html","page":"Costs and limits","id":"co-costs","name":"","signature":"Costs","summary":"A cost is what the player pays to use an ability: the imperative instructions before the dash (\"Bow this character\", \"Lose 1 honor\", \"Sacrifice a character\"). Costs come from the costs namespace (import * as costs from '../../costs/index.js'; the names clash with the game actions). Call .cost(...) once per cost; several calls add up and are all paid together. The functions live in boardCosts.ts, fateAndHonorCosts.ts and variableAndOptionalCosts.ts.","section":true},{"file":"costs.html","page":"Costs and limits","id":"co-how","name":"","signature":"How the engine pays","summary":"","section":true},{"file":"costs.html","page":"Costs and limits","id":"co-records","name":"","signature":"What costs record","summary":"Once paid, a cost may record what was paid in context.costs, typed by the builder (your editor shows the keys). A selection cost records the chosen card (or the list of cards, for a multi-card mode) under its own name and a snapshot under <name>StateWhenChosen: costs.dishonor(…) gives context.costs.dishonor and context.costs.dishonorStateWhenChosen. Read the snapshot when the card changes while paying (a sacrificed card has left play; the snapshot still has its traits and skill).","section":true},{"file":"costs.html","page":"Costs and limits","id":"co-chat","name":"","signature":"Chat text","summary":"The chat line of an ability lists the cost texts between the card and the effect: player1 uses Asahina Artisan, bowing Asahina Artisan to give Doji Whisperer +3 political skill. Each entry below gives its cost text. In it, {0} is what the cost recorded (the paid card or cards; a facedown card reads \"a facedown card\") and {1}, {2} are the cost's own values. A cost without a cost text adds nothing to the line; a few print a line of their own while paying.","section":true},{"file":"costs.html","page":"Costs and limits","id":"co-own","name":"","signature":"A cost of your own","summary":"A cost is an object implementing Cost<Results> (costs/Cost.ts). Results is what it records, which types context.costs in the builder. Write one only when no cost below fits.","section":true},{"file":"costs.html","page":"Costs and limits","id":"li-limits","name":"","signature":"Ability limits","summary":"A limit says how often an ability can be used in a period. The builder has two calls for it, both taking a limit object from AbilityLimit.ts (import { perConflict } from '../../AbilityLimit.js').","section":true},{"file":"costs.html","page":"Costs and limits","id":"li-limit-max","name":"","signature":"limit() and max()","summary":"","section":true},{"file":"costs.html","page":"Costs and limits","id":"li-counting","name":"","signature":"When a use is counted","summary":"","section":true},{"file":"costs.html","page":"Costs and limits","id":"li-gained","name":"","signature":"Copied and gained abilities","summary":"","section":true},{"file":"types.html","page":"Enums, events and context","id":"en-CardType","name":"CardType","signature":"CardType","summary":"The printed card type. Cards use it mostly as cardType on a target or a selection (.target({ cardType: CardType.Character }, …)), which also types the chosen card, and in checks such as event.card.type === CardType.Event."},{"file":"types.html","page":"Enums, events and context","id":"en-CharacterStatus","name":"CharacterStatus","signature":"CharacterStatus","summary":"The three status tokens. Cards pass it as token to gainStatusToken(), compare it with a token's grantedStatus, and use it with treatStatusTokenAs(). Constants.ts also exports the type EntersPlayStatus ('honored' | 'dishonored' | 'ordinary'), the status a character enters play with (putIntoPlay({ status }), default 'ordinary')."},{"file":"types.html","page":"Enums, events and context","id":"en-DeckType","name":"DeckType","signature":"DeckType","summary":"Which deck an action works on. Its values equal the Location values of the two decks."},{"file":"types.html","page":"Enums, events and context","id":"en-Location","name":"Location","signature":"Location","summary":"Where a card is. Taken by .location() (where an ability can be used from), location on targets and selections (where cards can be chosen; default PlayArea), destination of moveCard, and compared with card.location."},{"file":"types.html","page":"Enums, events and context","id":"en-Players","name":"Players","signature":"Players","summary":"A player relative to the ability's player (context.player)."},{"file":"types.html","page":"Enums, events and context","id":"en-RemainingCards","name":"RemainingCards","signature":"RemainingCards","summary":"What deckSearch does with the looked-at cards that were not taken (its remainingCards property, default Shuffle). A remainingCardsHandler replaces it."},{"file":"types.html","page":"Enums, events and context","id":"en-TokenType","name":"TokenType","signature":"TokenType","summary":"Tokens placed on cards other than status tokens and fate."},{"file":"types.html","page":"Enums, events and context","id":"en-Trait","name":"Trait elementTrait","signature":"Trait","summary":"Every card trait, named after the lower-case trait the card data holds (Trait.Shugenja is 'shugenja', Trait.BattleMaiden is 'battle-maiden'). Taken by hasTrait, hasSomeTrait, hasEveryTrait, addTrait, loseTrait, satisfyAffinity, hasAffinity, onAffinity, isTraitInPlay, attachmentConditions({ trait, limitTrait }) and the { trait } restriction scope. The full list is server/game/Constants/Trait.ts."},{"file":"types.html","page":"Enums, events and context","id":"en-AbilityType","name":"AbilityType","signature":"AbilityType","summary":"The kind of an ability, which decides in which window of an event window it is offered. Cards get it from the builder method (this.action(), this.reaction(), …). They name it directly only in gainAbility(AbilityType.X, …), registerTriggerWindow(eventName, AbilityType.X, handler) and checks such as event.context.ability.abilityType === AbilityType.Action."},{"file":"types.html","page":"Enums, events and context","id":"en-Blocker","name":"Blocker","signature":"Blocker","summary":"What meetsRequirements(context, ignoredBlockers) returns: the first thing that stops an ability or play action from being initiated, or None. Cards pass blockers in ignoredBlockers of playCard, resolveAbility and triggerAbility to skip those checks (\"ignoring costs\", \"as if it were in your hand\")."},{"file":"types.html","page":"Enums, events and context","id":"en-Duration","name":"Duration","signature":"Duration","summary":"How long a lasting effect lasts: duration of cardLastingEffect, playerLastingEffect, ringLastingEffect, conflictLastingEffect, duelLastingEffect and takeControl."},{"file":"types.html","page":"Enums, events and context","id":"en-PlayType","name":"PlayType","signature":"PlayType","summary":"How a card is being played. Found as context.playType and event.playType on onCardPlayed; taken by playCard({ playType }), canPlayFromOwn, canPlayFromOutOfPlay, canPlayFromOpponents, cost reducers (playingTypes), and as cannot of a restriction."},{"file":"types.html","page":"Enums, events and context","id":"en-Stage","name":"Stage","signature":"Stage","summary":"How far an ability's resolution has got: context.stage. Cards read it to tell a cost payment from an effect (event.context.stage === Stage.Cost)."},{"file":"types.html","page":"Enums, events and context","id":"en-TargetMode","name":"TargetMode","signature":"TargetMode","summary":"How many cards a choice takes. Cards set it as mode of targetCards(), selectCards(), deckSearch() and object-form targets. The non-card modes are set by the builder itself."},{"file":"types.html","page":"Enums, events and context","id":"en-ConflictType","name":"ConflictType","signature":"ConflictType","summary":"The type of a conflict. Cards use it with this.conflictAction(title, { conflictType }), game.isDuringConflict(type), conflict.conflictType, ring.conflictType, claimRing({ type }), initiateConflict({ forcedDeclaredType }) and conflict effects such as cannotDeclareConflictsOfType."},{"file":"types.html","page":"Enums, events and context","id":"en-DuelType","name":"DuelType","signature":"DuelType","summary":"The statistic a duel compares: type of initiateDuel() / duel()."},{"file":"types.html","page":"Enums, events and context","id":"en-Element","name":"Element","signature":"Element","summary":"The five ring elements. Rings are keyed by element (game.rings[Element.Fire]); compare ring.element, test province.getElement().includes(element); taken by addElement, addElementAsAttacker, canOnlyBeDeclaredAsAttackerWithElement."},{"file":"types.html","page":"Enums, events and context","id":"en-FavorType","name":"FavorType","signature":"FavorType","summary":"A side of the Imperial Favor: side of claimImperialFavor(), and the values of player.imperialFavor and game.getFavorSide() (strings, '' when nobody has it)."},{"file":"types.html","page":"Enums, events and context","id":"en-Phase","name":"Phase","signature":"Phase","summary":"The phases of a round. Taken by .phase() on an action (default 'any'), compared with game.currentPhase and event.phase on the phase events."},{"file":"types.html","page":"Enums, events and context","id":"en-SkillType","name":"SkillType","signature":"SkillType","summary":"Military or political skill. Taken by card.hasDash(type), setDash(type), setBaseDash(type) and the copyBaseSkillEffects helper."},{"file":"types.html","page":"Enums, events and context","id":"en-EffectName","name":"EffectName","signature":"EffectName","summary":"The type key of every effect the engine applies (effect.type). The engine looks effects up by it (card.anyEffect(EffectName.Blank), player.sumEffects(EffectName.AdditionalAction))."},{"file":"types.html","page":"Enums, events and context","id":"en-RestrictionScope","name":"RestrictionScope","signature":"RestrictionScope","summary":"Which attempts a restriction applies to: appliesTo of cardCannot, playerCannot, charactersCannot and immunity. Without appliesTo a restriction applies to every attempt. appliesTo can be a list (every entry must match) and an entry can be { trait: 'x' } (the attempt's source has that trait). \"Applying player\" is applyingPlayer if given, else the player of the effect's context."},{"file":"types.html","page":"Enums, events and context","id":"en-RestrictionType","name":"RestrictionType","signature":"RestrictionType","summary":"What a restriction forbids: cannot of cardCannot, playerCannot, charactersCannot and immunity (also a bare value: cardCannot(RestrictionType.Bow)). A game action checks its own restriction on each target (canAffect); the other values are checked by a rule at one place."},{"file":"types.html","page":"Enums, events and context","id":"en-EventName","name":"EventName","signature":"EventName","summary":"The name of every game event. In a when map the key is the string value (onCardPlayed); in code it is the enum member (EventName.OnCardPlayed), for example in event.is(EventName.OnCardHonored), context.event.name === EventName.OnCardHonored, EventRegistrar.register({ [EventName.OnRoundEnded]: … }) and registerTriggerWindow."},{"file":"types.html","page":"Enums, events and context","id":"ev-onBeginRound","name":"onBeginRound OnBeginRound","signature":"onBeginRound","summary":"Raised by Game.beginRound() at the start of each round, after the round number is increased and the Limited counters are reset, before the dynasty phase."},{"file":"types.html","page":"Enums, events and context","id":"ev-onPhaseCreated","name":"onPhaseCreated OnPhaseCreated","signature":"onPhaseCreated","summary":"Raised by PhaseStep.createPhase() when a phase of the round (dynasty, draw, conflict, fate) is about to run. Its handler queues the phase's steps. Setup does not raise it."},{"file":"types.html","page":"Enums, events and context","id":"ev-onPhaseStarted","name":"onPhaseStarted OnPhaseStarted","signature":"onPhaseStarted","summary":"Raised by PhaseStep.startPhase() as the first step of a round phase. Its handler sets game.currentPhase and posts the \"Round N - phase\" alert. Setup does not raise it (the setup phase sets game.currentPhase itself)."},{"file":"types.html","page":"Enums, events and context","id":"ev-onPhaseEnded","name":"onPhaseEnded OnPhaseEnded","signature":"onPhaseEnded","summary":"Raised by PhaseStep.endPhase() as the last step of a phase, and at the end of setup. game.currentPhase is cleared only after its window, so its interrupts and reactions still happen in the phase."},{"file":"types.html","page":"Enums, events and context","id":"ev-onRoundEnded","name":"onRoundEnded OnRoundEnded","signature":"onRoundEnded","summary":"Raised by Game.roundEnded() after the fate phase and the end-of-round prompt, before the next round begins."},{"file":"types.html","page":"Enums, events and context","id":"ev-onPassActionPhasePriority","name":"onPassActionPhasePriority OnPassActionPhasePriority","signature":"onPassActionPhasePriority","summary":"Raised by ActionWindow.nextPlayer() when priority in an action window goes to the other player: after the current player's action(s), or after a pass while the other player has not passed yet. Its handler switches the current player."},{"file":"types.html","page":"Enums, events and context","id":"ev-onPassDuringDynasty","name":"onPassDuringDynasty OnPassDuringDynasty","signature":"onPassDuringDynasty","summary":"Raised by the dynasty action window when a player passes. For the first player to pass the handler gives that player 1 fate."},{"file":"types.html","page":"Enums, events and context","id":"ev-onPassFirstPlayer","name":"onPassFirstPlayer OnPassFirstPlayer","signature":"onPassFirstPlayer","summary":"Raised by the fate phase as its last step. Its handler makes player the first player."},{"file":"types.html","page":"Enums, events and context","id":"ev-onRevealFacedownDynastyCards","name":"onRevealFacedownDynastyCards OnRevealFacedownDynastyCards","signature":"onRevealFacedownDynastyCards","summary":"Raised by the dynasty phase after it turned every facedown card in the provinces faceup (each flip is its own onCardRevealed from flipDynasty)."},{"file":"types.html","page":"Enums, events and context","id":"ev-onAbilityResolved","name":"onAbilityResolved OnAbilityResolved","signature":"onAbilityResolved","summary":"Never raised: nothing in server/ creates this event, so a when on it never fires."},{"file":"types.html","page":"Enums, events and context","id":"ev-onAbilityResolverInitiated","name":"onAbilityResolverInitiated OnAbilityResolverInitiated","signature":"onAbilityResolverInitiated","summary":"Raised by AbilityResolver when an ability that is not a card ability starts resolving: a play action (playing a character, attachment or dynasty card) or a ring effect. It is the only event of the initiate window; its handler queues the costs, the remaining targets and the effect. Play actions raise their onCardPlayed later, after costs."},{"file":"types.html","page":"Enums, events and context","id":"ev-onCardAbilityInitiated","name":"onCardAbilityInitiated OnCardAbilityInitiated","signature":"onCardAbilityInitiated","summary":"Raised by AbilityResolver when a card ability starts resolving (actions, triggered abilities, events, then-steps), after targets chosen before costs. It shares the initiate window with onCardAbilityTriggered and, for an event card, onCardPlayed. Its handler queues the costs, the remaining targets and the effect. resolveAbility raises it too."},{"file":"types.html","page":"Enums, events and context","id":"ev-onCardAbilityTriggered","name":"onCardAbilityTriggered OnCardAbilityTriggered","signature":"onCardAbilityTriggered","summary":"Raised with onCardAbilityInitiated when a CardAbility (an action, a triggered ability, an event's ability) is triggered; not for then-steps, and not for sub-resolutions of resolveAbility."},{"file":"types.html","page":"Enums, events and context","id":"ev-onEffectApplied","name":"onEffectApplied OnEffectApplied","signature":"onEffectApplied","summary":"The event of the lasting-effect actions: cardLastingEffect, playerLastingEffect, ringLastingEffect, conflictLastingEffect, duelLastingEffect and takeControl. Its handler applies the effect."},{"file":"types.html","page":"Enums, events and context","id":"ev-onInitiateAbilityEffects","name":"onInitiateAbilityEffects OnInitiateAbilityEffects","signature":"onInitiateAbilityEffects","summary":"Raised by AbilityResolver (as an InitiateCardAbilityEvent) when a card ability's effects are about to resolve: after its costs are paid and its targets chosen, after its chat message. Raised for actions, triggered abilities and events, not for then-steps; also by resolveAbility and for covert."},{"file":"types.html","page":"Enums, events and context","id":"ev-onResolveFateCost","name":"onResolveFateCost OnResolveFateCost","signature":"onResolveFateCost","summary":"Never raised: nothing in server/ creates this event, so a when on it never fires."},{"file":"types.html","page":"Enums, events and context","id":"ev-onSpendFate","name":"onSpendFate OnSpendFate","signature":"onSpendFate","summary":"The event of paying a fate cost: the cost to play a card (ReduceableFateCost) and target-dependent fate costs. Its handler marks the used cost reducers and takes the fate."},{"file":"types.html","page":"Enums, events and context","id":"ev-payCost","name":"payCost PayCost","signature":"payCost","summary":"The event of paying a cost that has no event of its own (a cost with only a pay function)."},{"file":"types.html","page":"Enums, events and context","id":"ev-unnamedEvent","name":"unnamedEvent Unnamed","signature":"unnamedEvent","summary":"The event of game actions that have no event name of their own (moveCard, handler, playCard, shuffleDeck, cancel, resolveAbility, …), and of a few framework steps (revealing honor dials without an event, resolving several ring effects)."},{"file":"types.html","page":"Enums, events and context","id":"ev-onCardAttached","name":"onCardAttached OnCardAttached","signature":"onCardAttached","summary":"The event of attach and attachToRing (and so of playing an attachment). Its handler moves the attachment onto the parent."},{"file":"types.html","page":"Enums, events and context","id":"ev-onCardDetached","name":"onCardDetached OnCardDetached","signature":"onCardDetached","summary":"The event of detach: an attachment in play leaves its parent and becomes a card in play of its own."},{"file":"types.html","page":"Enums, events and context","id":"ev-onCardPlayed","name":"onCardPlayed OnCardPlayed","signature":"onCardPlayed","summary":"Raised when a card is played. For an event card it is in the ability's initiate window (with onCardAbilityInitiated), before costs; for a character, attachment or dynasty card the play action raises it after costs, in the same window as the card's onCharacterEntersPlay or onCardAttached."},{"file":"types.html","page":"Enums, events and context","id":"ev-onCharacterEntersPlay","name":"onCharacterEntersPlay OnCharacterEntersPlay","signature":"onCharacterEntersPlay","summary":"The event of putIntoPlay, putIntoConflict and opponentPutIntoPlay, which playing a character also uses. Its handler sets fate and status, moves the card into play, and adds it to the conflict when intoConflict."},{"file":"types.html","page":"Enums, events and context","id":"ev-onCreateTokenCharacter","name":"onCreateTokenCharacter OnCreateTokenCharacter","signature":"onCreateTokenCharacter","summary":"The event of createToken: a facedown card in a province is removed from the game and a token character enters play instead (into the conflict, on the player's side, if one is running)."},{"file":"types.html","page":"Enums, events and context","id":"ev-onCardLeavesPlay","name":"onCardLeavesPlay OnCardLeavesPlay","signature":"onCardLeavesPlay","summary":"The event of every way of leaving play: discardFromPlay, sacrifice, returnToHand, returnToDeck, removeFromGame, putIntoProvince, and discarding characters with no fate in the fate phase. Its handler moves the card to destination."},{"file":"types.html","page":"Enums, events and context","id":"ev-onCardMoved","name":"onCardMoved OnCardMoved","signature":"onCardMoved","summary":"Two uses. BaseCard.moveTo() emits it every time a card changes location; this opens no event window, so no triggered ability can respond, only until maps and EventRegistrar listeners. chosenReturnToDeck uses it as its windowed event (a player returns cards from hand to their deck)."},{"file":"types.html","page":"Enums, events and context","id":"ev-onCardsDiscarded","name":"onCardsDiscarded OnCardsDiscarded","signature":"onCardsDiscarded","summary":"The event of discardCard: cards that are not in play (in hand, deck or provinces) go to their discard piles. One event for all the cards; the fate phase discards from provinces with it."},{"file":"types.html","page":"Enums, events and context","id":"ev-onCardsDiscardedFromHand","name":"onCardsDiscardedFromHand OnCardsDiscardedFromHand","signature":"onCardsDiscardedFromHand","summary":"The event of chosenDiscard, discardAtRandom and discardMatching: a player discards cards from hand."},{"file":"types.html","page":"Enums, events and context","id":"ev-onCardsDrawn","name":"onCardsDrawn OnCardsDrawn","signature":"onCardsDrawn","summary":"The event of draw, which the draw phase also uses. Its handler draws amount cards."},{"file":"types.html","page":"Enums, events and context","id":"ev-onDeckSearch","name":"onDeckSearch OnDeckSearch","signature":"onDeckSearch","summary":"The event of deckSearch. The cards are looked at and chosen while the action collects its events, before the window opens; the event has no handler."},{"file":"types.html","page":"Enums, events and context","id":"ev-onDeckShuffled","name":"onDeckShuffled OnDeckShuffled","signature":"onDeckShuffled","summary":"Emitted by Player.shuffleConflictDeck() and shuffleDynastyDeck(). It opens no event window, so no triggered ability can respond; until maps and EventRegistrar listeners see it."},{"file":"types.html","page":"Enums, events and context","id":"ev-onLookAtCards","name":"onLookAtCards OnLookAtCards","signature":"onLookAtCards","summary":"The event of lookAt: a player looks at cards (in hand, a deck, or facedown). One event for all the cards; its handler posts the chat message."},{"file":"types.html","page":"Enums, events and context","id":"ev-onAddTokenToCard","name":"onAddTokenToCard OnAddTokenToCard","signature":"onAddTokenToCard","summary":"The event of addToken: a token is placed on a faceup card (in play, or a holding or province in a province)."},{"file":"types.html","page":"Enums, events and context","id":"ev-onCardBowed","name":"onCardBowed OnCardBowed","signature":"onCardBowed","summary":"The event of bow, which the end of a conflict also uses for each participant."},{"file":"types.html","page":"Enums, events and context","id":"ev-onCardDishonored","name":"onCardDishonored OnCardDishonored","signature":"onCardDishonored","summary":"The event of dishonor (a character) and dishonorProvince (a province). After an ordinary character becomes dishonored, dishonor raises onStatusTokenGained."},{"file":"types.html","page":"Enums, events and context","id":"ev-onCardHonored","name":"onCardHonored OnCardHonored","signature":"onCardHonored","summary":"The event of honor. After an ordinary character becomes honored, it raises onStatusTokenGained."},{"file":"types.html","page":"Enums, events and context","id":"ev-onCardReadied","name":"onCardReadied OnCardReadied","signature":"onCardReadied","summary":"The event of ready, which the fate phase also uses."},{"file":"types.html","page":"Enums, events and context","id":"ev-onCardRevealed","name":"onCardRevealed OnCardRevealed","signature":"onCardRevealed","summary":"The event of reveal and flipDynasty; also raised for the attacked province revealed at declaration or after moveConflict, and for a province turned facedown during its own conflict."},{"file":"types.html","page":"Enums, events and context","id":"ev-onCardTainted","name":"onCardTainted OnCardTainted","signature":"onCardTainted","summary":"The event of taint. After it, taint raises onStatusTokenGained."},{"file":"types.html","page":"Enums, events and context","id":"ev-onCardTurnedFacedown","name":"onCardTurnedFacedown OnCardTurnedFacedown","signature":"onCardTurnedFacedown","summary":"The event of turnFacedown: a faceup card in a province is turned facedown."},{"file":"types.html","page":"Enums, events and context","id":"ev-onDynastyCardTurnedFaceup","name":"onDynastyCardTurnedFaceup OnDynastyCardTurnedFaceup","signature":"onDynastyCardTurnedFaceup","summary":"Never raised: nothing in server/ creates this event, so a when on it never fires. Turning dynasty cards faceup raises onCardRevealed."},{"file":"types.html","page":"Enums, events and context","id":"ev-onStatusTokenDiscarded","name":"onStatusTokenDiscarded OnStatusTokenDiscarded","signature":"onStatusTokenDiscarded","summary":"The event of discardStatusToken."},{"file":"types.html","page":"Enums, events and context","id":"ev-onStatusTokenGained","name":"onStatusTokenGained OnStatusTokenGained","signature":"onStatusTokenGained","summary":"The event of gainStatusToken; also raised after honor, dishonor and taint change a character's status, and after moveStatusToken."},{"file":"types.html","page":"Enums, events and context","id":"ev-onStatusTokenMoved","name":"onStatusTokenMoved OnStatusTokenMoved","signature":"onStatusTokenMoved","summary":"The event of moveStatusToken. Its handler moves the token and then raises onStatusTokenGained for the recipient."},{"file":"types.html","page":"Enums, events and context","id":"ev-afterConflict","name":"afterConflict AfterConflict","signature":"afterConflict","summary":"Raised by ConflictFlow after the conflict action window, once the winner is determined; its handler posts the result, records the winner and marks the conflict unopposed. Then come unopposed honor loss, breaking the province, the ring effect, claiming the ring and returning home."},{"file":"types.html","page":"Enums, events and context","id":"ev-onBreakProvince","name":"onBreakProvince OnBreakProvince","signature":"onBreakProvince","summary":"The event of breakProvince, which conflict resolution uses when the attacker wins by enough."},{"file":"types.html","page":"Enums, events and context","id":"ev-onConflictDeclared","name":"onConflictDeclared OnConflictDeclared","signature":"onConflictDeclared","summary":"Raised by ConflictFlow at the start of a conflict opportunity. Its handler runs the whole declaration: onConflictOpportunityAvailable, choosing ring, type, attackers and province, paying costs, onConflictDeclaredBeforeProvinceReveal, and revealing the province. Then it fills in type, ring, attackers and ringFate."},{"file":"types.html","page":"Enums, events and context","id":"ev-onConflictDeclaredBeforeProvinceReveal","name":"onConflictDeclaredBeforeProvinceReveal OnConflictDeclaredBeforeProvinceReveal","signature":"onConflictDeclaredBeforeProvinceReveal","summary":"Raised while declaring, after attackers, ring, type and province are chosen and their costs paid, before the province is revealed. Its handler starts the conflict (current conflict, participants, the conflict record), takes the ring's fate, resolves covert and raises onTheCrashingWave."},{"file":"types.html","page":"Enums, events and context","id":"ev-onConflictFinished","name":"onConflictFinished OnConflictFinished","signature":"onConflictFinished","summary":"Raised by ConflictFlow as the last step of a conflict, after participants returned home, once the current conflict is cleared."},{"file":"types.html","page":"Enums, events and context","id":"ev-onConflictInitiated","name":"onConflictInitiated OnConflictInitiated","signature":"onConflictInitiated","summary":"The event of initiateConflict: the conflict phase gives a player a conflict opportunity, or a card grants an extra conflict. Its handler starts the conflict flow."},{"file":"types.html","page":"Enums, events and context","id":"ev-onConflictMoved","name":"onConflictMoved OnConflictMoved","signature":"onConflictMoved","summary":"The event of moveConflict: the conflict moves to another province of the same defender, which is revealed if facedown."},{"file":"types.html","page":"Enums, events and context","id":"ev-onConflictOpportunityAvailable","name":"onConflictOpportunityAvailable OnConflictOpportunityAvailable","signature":"onConflictOpportunityAvailable","summary":"Raised inside onConflictDeclared's handler, before the attacking player chooses a conflict. Its handler asks the player to declare or pass (and handles \"defenders chosen first\")."},{"file":"types.html","page":"Enums, events and context","id":"ev-onConflictPass","name":"onConflictPass OnConflictPass","signature":"onConflictPass","summary":"Raised by Conflict.passConflict() when a player passes a conflict opportunity (by choice, or because no character can attack), after it is recorded."},{"file":"types.html","page":"Enums, events and context","id":"ev-onConflictStarted","name":"onConflictStarted OnConflictStarted","signature":"onConflictStarted","summary":"Raised by ConflictFlow after defenders are declared and their costs paid, just before the conflict action window."},{"file":"types.html","page":"Enums, events and context","id":"ev-onCovertResolved","name":"onCovertResolved OnCovertResolved","signature":"onCovertResolved","summary":"Raised after covert targets are chosen, next to the covert ability's onInitiateAbilityEffects. One per covert character, or one for all of them under the covertUnified rule."},{"file":"types.html","page":"Enums, events and context","id":"ev-onDefendersDeclared","name":"onDefendersDeclared OnDefendersDeclared","signature":"onDefendersDeclared","summary":"Raised by the defender prompt when the defending player confirms defenders (also when there are none)."},{"file":"types.html","page":"Enums, events and context","id":"ev-onMoveToConflict","name":"onMoveToConflict OnMoveToConflict","signature":"onMoveToConflict","summary":"The event of moveToConflict: a character at home joins the conflict on side."},{"file":"types.html","page":"Enums, events and context","id":"ev-onParticipantsReturnHome","name":"onParticipantsReturnHome OnParticipantsReturnHome","signature":"onParticipantsReturnHome","summary":"Raised at the end of a conflict, in one window with every participant's bow and onReturnHome events."},{"file":"types.html","page":"Enums, events and context","id":"ev-onReturnHome","name":"onReturnHome OnReturnHome","signature":"onReturnHome","summary":"Raised at the end of a conflict once per participant; its handler removes the character from the conflict. Each comes with a bow event, cancelled up front for a character that does not bow on return home."},{"file":"types.html","page":"Enums, events and context","id":"ev-onRestoreProvince","name":"onRestoreProvince OnRestoreProvince","signature":"onRestoreProvince","summary":"The event of restoreProvince: a broken province is restored."},{"file":"types.html","page":"Enums, events and context","id":"ev-onSendHome","name":"onSendHome OnSendHome","signature":"onSendHome","summary":"The event of sendHome: a participating character leaves the conflict."},{"file":"types.html","page":"Enums, events and context","id":"ev-onSwitchConflictElement","name":"onSwitchConflictElement OnSwitchConflictElement","signature":"onSwitchConflictElement","summary":"The event of switchConflictElement: the contested ring is switched with ring."},{"file":"types.html","page":"Enums, events and context","id":"ev-onSwitchConflictType","name":"onSwitchConflictType OnSwitchConflictType","signature":"onSwitchConflictType","summary":"The event of switchConflictType: the conflict switches between military and political."},{"file":"types.html","page":"Enums, events and context","id":"ev-onTheCrashingWave","name":"onTheCrashingWave OnTheCrashingWave","signature":"onTheCrashingWave","summary":"Raised in every conflict by onConflictDeclaredBeforeProvinceReveal's handler: after the attack is declared, before the province is revealed. Only The Crashing Wave uses it."},{"file":"types.html","page":"Enums, events and context","id":"ev-onClaimRing","name":"onClaimRing OnClaimRing","signature":"onClaimRing","summary":"Raised when a player claims a ring: by the conflict's winner after the ring effect (if no ClaimRings restriction), and by claimRing."},{"file":"types.html","page":"Enums, events and context","id":"ev-onRemoveRingFromPlay","name":"onRemoveRingFromPlay OnRemoveRingFromPlay","signature":"onRemoveRingFromPlay","summary":"The event of removeRingFromPlay. Its handler raises a second onRemoveRingFromPlay event, whose handler removes the ring."},{"file":"types.html","page":"Enums, events and context","id":"ev-onResolveConflictRing","name":"onResolveConflictRing OnResolveConflictRing","signature":"onResolveConflictRing","summary":"The event of resolveConflictRing, which conflict resolution uses when the attacker wins. Its handler lets the player choose which elements to resolve and raises an onResolveRingElement for each."},{"file":"types.html","page":"Enums, events and context","id":"ev-onResolveRingElement","name":"onResolveRingElement OnResolveRingElement","signature":"onResolveRingElement","summary":"The event of resolveRingEffect: one element's effect resolves. With several rings, they are offered as simultaneous effects and each opens its own window."},{"file":"types.html","page":"Enums, events and context","id":"ev-onReturnRing","name":"onReturnRing OnReturnRing","signature":"onReturnRing","summary":"The event of returnRing, which the fate phase uses to return every claimed ring to the unclaimed pool."},{"file":"types.html","page":"Enums, events and context","id":"ev-onReturnRingToPlay","name":"onReturnRingToPlay OnReturnRingToPlay","signature":"onReturnRingToPlay","summary":"The event of returnRingToPlay. Like onRemoveRingFromPlay, its handler raises a second event of the same name, whose handler returns the ring."},{"file":"types.html","page":"Enums, events and context","id":"ev-onTakeRing","name":"onTakeRing OnTakeRing","signature":"onTakeRing","summary":"The event of takeRing: the player claims a ring they have not claimed, with its fate unless takeFate: false."},{"file":"types.html","page":"Enums, events and context","id":"ev-afterDuel","name":"afterDuel AfterDuel","signature":"afterDuel","summary":"Raised by DuelFlow once the duel's result is determined and announced, before the strike step and the duel's effects."},{"file":"types.html","page":"Enums, events and context","id":"ev-onAddDuelParticipant","name":"onAddDuelParticipant OnAddDuelParticipant","signature":"onAddDuelParticipant","summary":"The event of duelAddParticipant: a character is added to a running duel."},{"file":"types.html","page":"Enums, events and context","id":"ev-onDuelChallenge","name":"onDuelChallenge OnDuelChallenge","signature":"onDuelChallenge","summary":"Raised by DuelFlow after onDuelStarted: the challenge step. Cards use it through this.duelChallenge(title, duelCondition?), a DuelReaction trigger."},{"file":"types.html","page":"Enums, events and context","id":"ev-onDuelFinished","name":"onDuelFinished OnDuelFinished","signature":"onDuelFinished","summary":"Raised by DuelFlow as its last step, after the duel's effects, once the current duel is restored to the previous one."},{"file":"types.html","page":"Enums, events and context","id":"ev-onDuelFocus","name":"onDuelFocus OnDuelFocus","signature":"onDuelFocus","summary":"Raised by the honor bid prompt of a duel, right after onHonorDialsRevealed: the focus step. Cards use it through this.duelFocus(title, duelCondition?)."},{"file":"types.html","page":"Enums, events and context","id":"ev-onDuelInitiated","name":"onDuelInitiated OnDuelInitiated","signature":"onDuelInitiated","summary":"The event of duel (and initiateDuel()). Its handler applies challenger and target effects and starts the duel flow."},{"file":"types.html","page":"Enums, events and context","id":"ev-onDuelResolution","name":"onDuelResolution OnDuelResolution","signature":"onDuelResolution","summary":"Raised by DuelFlow after the strike step. Its handler resolves the duel's effect (gameAction / onTie)."},{"file":"types.html","page":"Enums, events and context","id":"ev-onDuelStarted","name":"onDuelStarted OnDuelStarted","signature":"onDuelStarted","summary":"Raised by DuelFlow first, once the duel is the current duel."},{"file":"types.html","page":"Enums, events and context","id":"ev-onDuelStrike","name":"onDuelStrike OnDuelStrike","signature":"onDuelStrike","summary":"Raised by DuelFlow after afterDuel: the strike step. Cards use it through this.duelStrike(title, duelCondition?)."},{"file":"types.html","page":"Enums, events and context","id":"ev-onReplaceDuelParticipant","name":"onReplaceDuelParticipant OnReplaceDuelParticipant","signature":"onReplaceDuelParticipant","summary":"Never raised: nothing in server/ creates this event, so a when on it never fires."},{"file":"types.html","page":"Enums, events and context","id":"ev-onFateCollected","name":"onFateCollected OnFateCollected","signature":"onFateCollected","summary":"Raised by Player.collectFate() in the dynasty phase, after the player's income was added."},{"file":"types.html","page":"Enums, events and context","id":"ev-onHonorBid","name":"onHonorBid OnHonorBid","signature":"onHonorBid","summary":"The event of honorBid: an honor bid outside the draw phase. Its handler prompts the bidding players and queues postBidAction."},{"file":"types.html","page":"Enums, events and context","id":"ev-onHonorDialsRevealed","name":"onHonorDialsRevealed OnHonorDialsRevealed","signature":"onHonorDialsRevealed","summary":"Raised by the honor bid prompt when every bid is chosen (draw phase, duels, honorBid). Its handler sets each dial (an onSetHonorDial per player). A reveal that is not a bid raises an unnamed event instead."},{"file":"types.html","page":"Enums, events and context","id":"ev-onModifyBid","name":"onModifyBid OnModifyBid","signature":"onModifyBid","summary":"The event of modifyBid: a player's honor bid goes up or down."},{"file":"types.html","page":"Enums, events and context","id":"ev-onModifyFate","name":"onModifyFate OnModifyFate","signature":"onModifyFate","summary":"The event of gainFate and loseFate."},{"file":"types.html","page":"Enums, events and context","id":"ev-onModifyHonor","name":"onModifyHonor OnModifyHonor","signature":"onModifyHonor","summary":"The event of gainHonor and loseHonor, which the unopposed honor loss and status tokens also use."},{"file":"types.html","page":"Enums, events and context","id":"ev-onMoveFate","name":"onMoveFate OnMoveFate","signature":"onMoveFate","summary":"The event of moving fate: placeFate, removeFate, takeFate, placeFateOnRing, takeFateFromRing; also fate taken from a ring when a conflict is declared or a ring claimed, the contested ring being switched, the fate phase's fate removal, the fate removed with a card leaving play, and paying a fate cost to the opponent."},{"file":"types.html","page":"Enums, events and context","id":"ev-onPlaceFateOnUnclaimedRings","name":"onPlaceFateOnUnclaimedRings OnPlaceFateOnUnclaimedRings","signature":"onPlaceFateOnUnclaimedRings","summary":"Raised by the fate phase when the game's rules place fate on rings: 1 fate on each unclaimed ring, by its handler."},{"file":"types.html","page":"Enums, events and context","id":"ev-onSetHonorDial","name":"onSetHonorDial OnSetHonorDial","signature":"onSetHonorDial","summary":"The event of setHonorDial, which revealing honor dials uses for each player."},{"file":"types.html","page":"Enums, events and context","id":"ev-onTransferHonor","name":"onTransferHonor OnTransferHonor","signature":"onTransferHonor","summary":"The event of takeHonor: honor goes from player to that player's opponent; after a draw-phase or duel bid with afterBid: true."},{"file":"types.html","page":"Enums, events and context","id":"ev-onClaimFavor","name":"onClaimFavor OnClaimFavor","signature":"onClaimFavor","summary":"The event of claimImperialFavor, which the glory count uses for its winner. Its handler takes the favor from the opponent and gives it to the player (prompting for the side when needed)."},{"file":"types.html","page":"Enums, events and context","id":"ev-onDiscardFavor","name":"onDiscardFavor OnDiscardFavor","signature":"onDiscardFavor","summary":"The event of loseImperialFavor (default target: the opponent)."},{"file":"types.html","page":"Enums, events and context","id":"ev-onFavorGloryTied","name":"onFavorGloryTied OnFavorGloryTied","signature":"onFavorGloryTied","summary":"Raised by the glory count's handler when both players have the same glory total."},{"file":"types.html","page":"Enums, events and context","id":"ev-onFlipFavor","name":"onFlipFavor OnFlipFavor","signature":"onFlipFavor","summary":"The event of flipImperialFavor: the favor switches between military and political."},{"file":"types.html","page":"Enums, events and context","id":"ev-onGloryCount","name":"onGloryCount OnGloryCount","signature":"onGloryCount","summary":"The event of performGloryCount, which the end of the conflict phase uses. Its handler counts glory, raises onFavorGloryTied on a tie, and resolves the action's gameAction for the winner (claiming the favor)."},{"file":"types.html","page":"Enums, events and context","id":"ctx-AbilityContext","name":"AbilityContext","signature":"AbilityContext<S, T>","summary":"The object every callback of an ability receives as context: conditions, cardCondition, property factories ((context) => ({ … })), chatText, handler, then factories. One is created each time an ability is used (for a trigger, one per player while checking). S is the source's type, T the type of context.target. Defined in server/game/AbilityContext.ts."},{"file":"types.html","page":"Enums, events and context","id":"ctx-TriggeredAbilityContext","name":"TriggeredAbilityContext","signature":"TriggeredAbilityContext<S, T, E>","summary":"The context of a triggered ability (reaction, interrupt, forced, duel reaction, would-interrupt). It adds event and cancel() to AbilityContext. Defined in server/game/TriggeredAbilityContext.ts."},{"file":"types.html","page":"Enums, events and context","id":"ctx-ability","name":"ability","signature":"context.ability","summary":"The ability being resolved. Useful members: title, abilityType (AbilityType), isCardPlayed() (an event card, or a play action), isCardAbility(), isTriggeredAbility(), isKeywordAbility(), cannotBeMirrored, getReducedCost(context) on play abilities."},{"file":"types.html","page":"Enums, events and context","id":"ctx-game","name":"game","signature":"context.game","summary":"The Game: currentConflict, currentDuel, currentPhase, rings, isDuringConflict(type?), getConflicts(player), getDeclaredConflictCount(player), getPlayers(), addMessage(), queueSimpleStep(), …"},{"file":"types.html","page":"Enums, events and context","id":"ctx-player","name":"player","signature":"context.player","summary":"The player using the ability: who triggers or plays it, pays its costs and is \"you\" in its text. Player actions (gainHonor, draw, …) default to this player; context.player.opponent is the opponent (undefined in a solo game)."},{"file":"types.html","page":"Enums, events and context","id":"ctx-source","name":"source","signature":"context.source","summary":"The card whose ability this is. Card game actions (bow(), honor(), …) default to it."},{"file":"types.html","page":"Enums, events and context","id":"ctx-costs","name":"costs","signature":"context.costs","summary":"What the paid costs recorded, by key: a selection cost records the chosen card(s) under its name and a snapshot under <name>StateWhenChosen (costs.dishonor() gives context.costs.dishonor); a fate cost records context.costs.fate (the amount after reductions)."},{"file":"types.html","page":"Enums, events and context","id":"ctx-deckSearchSelected","name":"deckSearchSelected","signature":"context.deckSearchSelected","summary":"The cards a deckSearch resolved with this context took. A gameAction of the search, or a later step, reads it."},{"file":"types.html","page":"Enums, events and context","id":"ctx-element","name":"element elements elementCard","signature":"context.element","summary":"The element symbol chosen with elementTarget() (an ElementSymbol: element, key, prettyName): context.elements[name], and context.element for a target named target. context.elementCard is the card it is printed on."},{"file":"types.html","page":"Enums, events and context","id":"ctx-ring","name":"ring rings","signature":"context.ring","summary":"The ring chosen with ringTarget(): context.rings[name] for every ring target, and context.ring when the target is named target."},{"file":"types.html","page":"Enums, events and context","id":"ctx-select","name":"select selects","signature":"context.select","summary":"The label chosen in a select(): context.selects[name] is a SelectChoice (.choice is the label), and context.select is the label itself when the select is named target (the default)."},{"file":"types.html","page":"Enums, events and context","id":"ctx-target","name":"target targets","signature":"context.target","summary":"The card chosen for a target: context.targets[name] for every card target, and context.target when the target is named target (the default for an unnamed target) and holds one card. {0} in the chat text is this target."},{"file":"types.html","page":"Enums, events and context","id":"ctx-targetAbility","name":"targetAbility","signature":"context.targetAbility","summary":"The printed ability chosen with abilityTarget() (a CardAbility: card, title, abilityType, …). There is one per ability, so the target takes no name."},{"file":"types.html","page":"Enums, events and context","id":"ctx-token","name":"token tokens","signature":"context.token","summary":"The status tokens chosen with tokenTarget(): context.tokens[name], and context.token for a target named target. Always an array of StatusToken (grantedStatus, card)."},{"file":"types.html","page":"Enums, events and context","id":"ctx-cardStateWhenInitiated","name":"cardStateWhenInitiated","signature":"context.cardStateWhenInitiated","summary":"A snapshot of the source taken in the first step of resolution, before targets and costs, when the source is a character, holding or attachment. null for other sources and before resolution starts."},{"file":"types.html","page":"Enums, events and context","id":"ctx-choosingPlayerOverride","name":"choosingPlayerOverride","signature":"context.choosingPlayerOverride","summary":"A player who chooses this ability's targets instead of their usual chooser. An interrupt to the ability's onCardAbilityInitiated sets it on event.context."},{"file":"types.html","page":"Enums, events and context","id":"ctx-chosenCardTargets","name":"chosenCardTargets triggeringContext originatingContext subResolution","signature":"context.chosenCardTargets","summary":"chosenCardTargets: every card chosen as a target during this triggering, then-steps and sub-resolutions included. It is filled on triggeringContext when the effects initiate."},{"file":"types.html","page":"Enums, events and context","id":"ctx-events","name":"events previousEvents","signature":"context.events","summary":"context.events holds the events created by the current step's game actions (it is reset when the step resolves them). In a then-step, context.previousEvents holds the events of the step before."},{"file":"types.html","page":"Enums, events and context","id":"ctx-playType","name":"playType chooseFate","signature":"context.playType","summary":"playType: how the source is being played (PlayType), found on creation from where the player can play the source; \"play as if from hand\" actions set it to PlayFromHand. chooseFate: the extra fate chosen for a character being played."},{"file":"types.html","page":"Enums, events and context","id":"ctx-stage","name":"stage","signature":"context.stage","summary":"How far the resolution has got (Stage): PreTarget while choosing targets before costs, Cost while paying costs, Target while choosing targets after costs, Effect while the effects resolve."},{"file":"types.html","page":"Enums, events and context","id":"ctx-event","name":"event cancel","signature":"context.event","summary":"On a triggered ability's context, the event that triggered it, with its full payload. In the when predicate the same event is the first argument."},{"file":"types.html","page":"Enums, events and context","id":"ctx-chatTarget","name":"chatTarget messageTarget","signature":"context.chatTarget()","summary":"chatTarget() returns what a chat text's {0} names: the target (the cards in targets.target if several, else context.target), else context.ring, else context.source. messageTarget() returns only the target part."},{"file":"types.html","page":"Enums, events and context","id":"ctx-refillProvince","name":"refillProvince","signature":"context.refillProvince(player, location)","summary":"Queues a refill of player's province at location; the provinces are refilled (first player first) when the ability's resolution finishes, then the game state is checked."},{"file":"types.html","page":"Enums, events and context","id":"ctx-typing","name":"ActionContext TriggerContext ResolvedAbilityContext","signature":"ActionContext<S> / TriggerContext<S, W>","summary":"The builder types the context of each callback from what the ability declared, so callbacks need no casts:"},{"file":"types.html","page":"Enums, events and context","id":"en-section-enums","name":"","signature":"Enums","summary":"The enums card files import from server/game/Constants.ts (each lives in server/game/Constants/). All are string enums: the value is what the engine stores and compares, so card.type === CardType.Character and card.type === 'character' are the same test. Prefer the member.","section":true},{"file":"types.html","page":"Enums, events and context","id":"ev-section-events","name":"","signature":"Events","summary":"Everything that happens in a game is an event (Event). A triggered ability names the events it responds to in .when({ onX: (event, context) => … }): the key is the event's string value, event is typed by the key, and the predicate returns whether the ability may trigger. In code the names are the EventName members (EventName.OnCardPlayed).","section":true},{"file":"types.html","page":"Enums, events and context","id":"ctx-section-context","name":"","signature":"Context","summary":"Every callback of an ability gets context, an AbilityContext (a TriggeredAbilityContext for triggered abilities). It says whose ability it is, what was chosen and paid, and how far the resolution has got. Fields are filled in as the ability resolves, so what a callback can read depends on when it runs: a cardCondition runs while targets are chosen, a property factory of a game action when the effect resolves.","section":true},{"file":"engine.html","page":"Engine internals","id":"eng-checks","name":"","signature":"How an ability is checked","summary":"Before an ability is offered, meetsRequirements(context, ignoredBlockers) runs its checks in order and returns the first Blocker that stops it, or Blocker.None. The checks come from three classes; each calls the next one's checks last.","section":true},{"file":"engine.html","page":"Engine internals","id":"eng-ignored-blockers","name":"","signature":"Ignoring blockers","summary":"resolveAbility and the play actions pass ignoredBlockers to skip checks. Only these blockers can be skipped:","section":true},{"file":"engine.html","page":"Engine internals","id":"eng-resolver","name":"","signature":"How an ability resolves","summary":"AbilityResolver runs these steps:","section":true},{"file":"engine.html","page":"Engine internals","id":"eng-game-actions","name":"","signature":"Running game actions from engine code","summary":"An action first collects its events (action.addEventsToArray(events, context): one per legal target), and something else opens them in an event window. Open them one step later, as the entry points below do: some actions add their events only after a prompt.","section":true},{"file":"engine.html","page":"Engine internals","id":"eng-imports","name":"","signature":"Imports and cycles","summary":"","section":true},{"file":"engine.html","page":"Engine internals","id":"eng-registrar","name":"","signature":"Listening to events: EventRegistrar","summary":"A card that has to remember something across events (which provinces were attacked, the first action of a conflict) listens with an EventRegistrar. Its listeners stay for the whole game.","section":true},{"file":"helpers.html","page":"Card helpers and queries","id":"he-BattlefieldAttachment","name":"BattlefieldAttachment","signature":"class X extends BattlefieldAttachment","summary":"A ProvinceAttachment with \"Limit 1 Battlefield attachment per province.\" Its setupCardAbilities() adds attachmentConditions({ limitTrait: { battlefield: 1 } })."},{"file":"helpers.html","page":"Card helpers and queries","id":"he-ProvinceAttachment","name":"ProvinceAttachment","signature":"class X extends ProvinceAttachment","summary":"An attachment that is played on and attached to a province instead of a character. canPlayOn and canAttach accept only a card of type province, and only while the card itself is an attachment."},{"file":"helpers.html","page":"Card helpers and queries","id":"he-RingAttachment","name":"RingAttachment","signature":"class X extends RingAttachment","summary":"An attachment played on and attached to a ring: \"Attach to a ring.\" canPlayOn and canAttach accept only a ring, and mustAttachToRing() returns true, all while the card is an attachment."},{"file":"helpers.html","page":"Card helpers and queries","id":"he-TokenCard","name":"TokenCard","signature":"abstract class TokenCard extends DrawCard","summary":"A facedown card that is in play as a token (\"put the top card of your dynasty deck into play facedown as a 1 military … character\"). The token class holds the token's printed data; the real card is kept in facedownCard. You don't create tokens yourself: the game actions tokenFromTopCard and createToken take the token class and make one."},{"file":"helpers.html","page":"Card helpers and queries","id":"he-AshigaruRecruit","name":"AshigaruRecruit Soldier SpiritOfTheRiver UnleashedHound","signature":"AshigaruRecruit","summary":"The existing TokenCard subclasses. Pass the class (not an instance) as token to tokenFromTopCard or createToken."},{"file":"helpers.html","page":"Card helpers and queries","id":"he-CharactersEnteredThisConflict","name":"CharactersEnteredThisConflict","signature":"new CharactersEnteredThisConflict(game)","summary":"Remembers each character that entered play (onCharacterEntersPlay) since the current conflict started. has(card) answers \"did this character enter play during this conflict?\"."},{"file":"helpers.html","page":"Card helpers and queries","id":"he-ConflictsDeclaredThisRound","name":"ConflictsDeclaredThisRound","signature":"new ConflictsDeclaredThisRound(game)","summary":"Records the province each conflict was declared against this round, for \"the attacked province has had a previous conflict declared against it this round\" and \"for each conflict declared against this province this round\"."},{"file":"helpers.html","page":"Card helpers and queries","id":"he-DuelsThisConflict","name":"DuelsThisConflict","signature":"DuelsThisConflict.winners(game, options?)","summary":"Remembers characters from each duel resolved during the current conflict. The static factories pick which ones; has(card) answers the question."},{"file":"helpers.html","page":"Card helpers and queries","id":"he-LimitedPlaysFromOutOfPlay","name":"LimitedPlaysFromOutOfPlay","signature":"new LimitedPlaysFromOutOfPlay<this>(card, options)","summary":"Counts the plays a card allows \"as if it were in your hand\", for \"You cannot play more than 3 cards per round this way.\" It adds a persistent effect to card that counts each matching play, writes the chat line and runs afterPlay. It does not make anything playable: the card's own persistent effect does that and must check available."},{"file":"helpers.html","page":"Card helpers and queries","id":"he-attachmentSearch","name":"attachmentSearch","signature":"attachmentSearch({ controller, maxCost? })","summary":"\"Search the top 5 cards of your conflict deck for an attachment and put it into play attached to a character. Shuffle.\" Returns a sequential action: a card menu of the top 5 cards, then a character choice for the chosen attachment, then a shuffle of the player's conflict deck."},{"file":"helpers.html","page":"Card helpers and queries","id":"he-cheapCharacterSearch","name":"cheapCharacterSearch","signature":"cheapCharacterSearch()","summary":"\"Look at the top 5 cards of your dynasty deck. You may put a character with cost 2 or lower from among those cards into play. Discard the rest.\" Returns the properties for .deckSearch(…)."},{"file":"helpers.html","page":"Card helpers and queries","id":"he-copyBaseSkillEffects","name":"copyBaseSkillEffects","signature":"copyBaseSkillEffects(card, { base?, skills? }?)","summary":"Effects that set a character's base skills to another character's skills: \"set this character's base skill to the chosen character's current skill values\". Returns an array of effects for a lasting effect."},{"file":"helpers.html","page":"Card helpers and queries","id":"he-discardBottomTop","name":"discardBottomTop","signature":"discardBottomTop(player, deck)","summary":"\"Discard 1 of those cards, place another on top of that deck, and the other on the bottom of that deck.\" An assignRoles action on the top 3 cards of the deck: the player picks the card to discard, then the card for the bottom; the last stays on top."},{"file":"helpers.html","page":"Card helpers and queries","id":"he-makeMantra","name":"makeMantra","signature":"makeMantra(id, element, title, effect, chatText)","summary":"Builds the whole card class of a Mantra: \"Reaction: After an opponent declares a [element] conflict, choose a Monk character or a character with a Monk attachment – {effect} and draw 1 card.\" The card file only exports the result."},{"file":"helpers.html","page":"Card helpers and queries","id":"he-moveCardInProvinceAction","name":"moveCardInProvinceAction","signature":"moveCardInProvinceAction(source)","summary":"Declares the action \"choose a card in or attached to a province - move that card to another unbroken non-stronghold province controlled by the same player\" on source and returns the builder, so you can add costs and steps."},{"file":"helpers.html","page":"Card helpers and queries","id":"he-moveHoldingAction","name":"moveHoldingAction","signature":"moveHoldingAction(holding)","summary":"Declares the holding's action \"Choose a non-stronghold province you control - move this card to that province.\" on holding and returns the builder for further steps."},{"file":"helpers.html","page":"Card helpers and queries","id":"he-nameCardType","name":"nameCardType revealCount takeUpToTwoOfNamedType","signature":"nameCardType()","summary":"The parts of \"Name a card type. Reveal the top 3 cards of your conflict deck (top 4 cards instead if you control a [Trait] character) – add up to 2 revealed cards of that type to your hand and discard the rest.\""},{"file":"helpers.html","page":"Card helpers and queries","id":"he-playableFromUnderneath","name":"playableFromUnderneath","signature":"playableFromUnderneath(card, match?)","summary":"\"You may play each card underneath it as if it were in your hand.\" Returns the properties for this.persistentEffect(…): while card is in play, its controller can play the cards underneath it that pass match."},{"file":"helpers.html","page":"Card helpers and queries","id":"he-randomHandCards","name":"randomHandCards chooseCardToDiscard","signature":"randomHandCards(player, amount)","summary":"\"Reveal X random cards from their hand … Choose and discard one of those cards.\" randomHandCards picks the cards; chooseCardToDiscard is a card menu in which the ability's player picks one of them to discard."},{"file":"helpers.html","page":"Card helpers and queries","id":"he-revealedTopCardPlayable","name":"revealedTopCardPlayable","signature":"revealedTopCardPlayable(player, source, endsWith)","summary":"\"Reveal the top card of your conflict deck. Until the end of the phase, you may play that card as if it were in your hand.\" Returns the properties for .playerLastingEffect(…): the top card is shown and can be played from the deck."},{"file":"helpers.html","page":"Card helpers and queries","id":"he-attachSearchedCard","name":"attachSearchedCard","signature":"attachSearchedCard(context, parent, card, message)","summary":"For \"search your deck for an attachment and attach it to that character\": call it in a deck search's selectedCardsHandler. It writes message(card) to the chat and attaches card to parent once the search has finished."},{"file":"helpers.html","page":"Card helpers and queries","id":"he-DeckChoice","name":"DeckChoice","signature":"new DeckChoice({ players, pile })","summary":"\"Choose a deck\": builds selectFrom choices with one entry per dynasty and conflict deck (or discard pile), labelled like \"player2's Conflict Deck\", and the chosen pile's name for the chat."},{"file":"helpers.html","page":"Card helpers and queries","id":"he-placeInProvinces","name":"placeInProvinces","signature":"placeInProvinces(context, cards)","summary":"\"Put 1 of those cards into each of your non-stronghold provinces faceup. Shuffle.\" Prompts the player to pick a card, then a province for it, until every non-stronghold province has received one or no card is left; then shuffles the player's dynasty deck. Call it from .handler(…)."},{"file":"helpers.html","page":"Card helpers and queries","id":"he-playerChoices","name":"playerChoices","signature":"playerChoices(player, choice, both?)","summary":"\"Choose a player\": selectFrom choices labelled with the players' names, the ability's player first."},{"file":"helpers.html","page":"Card helpers and queries","id":"he-attacksAloneWithTrait","name":"attacksAloneWithTrait","signature":"attacksAloneWithTrait(conflict, player, trait)","summary":"\"After a [Trait] character you control attacks alone\": whether player is the attacking player, has exactly one participating character, and that character has trait."},{"file":"helpers.html","page":"Card helpers and queries","id":"he-controlsShugenja","name":"controlsShugenja","signature":"controlsShugenja(player)","summary":"\"Play only if you control a Shugenja character.\" True if the player has a character with the Shugenja trait in play."},{"file":"helpers.html","page":"Card helpers and queries","id":"he-controlsParticipating","name":"controlsParticipating","signature":"controlsParticipating(player, ...traits)","summary":"\"If you control a participating [trait] character.\" True if the player has a participating character with any of the traits."},{"file":"helpers.html","page":"Card helpers and queries","id":"he-countCardsUnderneath","name":"countCardsUnderneath","signature":"countCardsUnderneath(card)","summary":"\"for each card under it\": the number of cards underneath card (in the location card.uuid) controlled by card's controller."},{"file":"helpers.html","page":"Card helpers and queries","id":"he-countTargetable","name":"countTargetable","signature":"countTargetable(cards, context)","summary":"How many of cards can be chosen as targets together, for a variable X (\"Lose X honor. Choose X characters\"). It goes through the cards in order and keeps each one that can be targeted alongside those kept before."},{"file":"helpers.html","page":"Card helpers and queries","id":"he-defendingAtKaiuWall","name":"defendingAtKaiuWall","signature":"defendingAtKaiuWall(player, conflict)","summary":"\"if the attacked province has a Kaiu Wall holding\": whether player is the defending player and one of the conflict's provinces holds a faceup holding with the Kaiu Wall trait."},{"file":"helpers.html","page":"Card helpers and queries","id":"he-isOpponentsRingOrCardEffect","name":"isOpponentsRingOrCardEffect isOwnRingEffect","signature":"isOpponentsRingOrCardEffect(player, context)","summary":"Who caused an event: pass the event's context. isOpponentsRingOrCardEffect is true for \"an opponent's card ability or ring effect\"; isOwnRingEffect for \"the effect of the ring\" resolved by player."},{"file":"helpers.html","page":"Card helpers and queries","id":"he-otherHoldingsInSameProvince","name":"otherHoldingsInSameProvince","signature":"otherHoldingsInSameProvince(context)","summary":"\"each other holding in that province\": the faceup holdings in the source's location, controlled by the source's controller, other than the source."},{"file":"helpers.html","page":"Card helpers and queries","id":"he-participatingGlory","name":"participatingGlory hasMoreParticipatingGlory","signature":"participatingGlory(player)","summary":"\"if you count more current glory than your opponent among ready participating characters\". participatingGlory sums the current glory of the player's ready participating characters; hasMoreParticipatingGlory compares it with the opponent's."},{"file":"helpers.html","page":"Card helpers and queries","id":"he-soldierAttachCheck","name":"soldierAttachCheck","signature":"soldierAttachCheck(owner)","summary":"Returns a check (character, context) => boolean: could a Soldier token be attached to this character? It asks the attach action with a dummy Soldier that never enters the game, so attachment restrictions (\"No attachments\", \"cannot have Follower attachments\") apply before the top card is turned into a token."},{"file":"helpers.html","page":"Card helpers and queries","id":"he-stateWhenLeftPlay","name":"stateWhenLeftPlay","signature":"stateWhenLeftPlay(context)","summary":"The card that left play in the previous step of the ability, as it was then (with its tokens and fate). Use it after .then() when the step before sacrificed or discarded the card."},{"file":"helpers.html","page":"Card helpers and queries","id":"he-claimedRingSymbols","name":"claimedRingSymbols","signature":"claimedRingSymbols(symbols)","summary":"Turns { key, element } pairs into the card's printed element symbols, named \"Claimed Ring\". Return them from getPrintedElementSymbols() together with super's."},{"file":"helpers.html","page":"Card helpers and queries","id":"he-claimsRingOf","name":"claimsRingOf","signature":"claimsRingOf(card, key, event)","summary":"For onClaimRing: \"After the [element] ring is claimed\". True if the claimed ring, or the conflict's ring, has the element of card's symbol key."},{"file":"helpers.html","page":"Card helpers and queries","id":"he-claimsRoleElement","name":"claimsRoleElement","signature":"claimsRoleElement(player, event)","summary":"For onClaimRing: \"After you claim a ring that matches the element of your role\". True if the player's role card has a trait equal to an element of the conflict's ring or of the claimed ring."},{"file":"helpers.html","page":"Card helpers and queries","id":"he-countClaimedRings","name":"countClaimedRings","signature":"countClaimedRings(game, predicate?)","summary":"\"for each claimed ring\": the number of rings claimed by any player that pass predicate."},{"file":"helpers.html","page":"Card helpers and queries","id":"he-hasClaimedAnyRing","name":"hasClaimedAnyRing","signature":"hasClaimedAnyRing(card, symbols, player)","summary":"\"while you have claimed the [element] or [element] ring\": hasClaimedRing for each symbol, true if any is claimed by player."},{"file":"helpers.html","page":"Card helpers and queries","id":"he-hasClaimedRing","name":"hasClaimedRing","signature":"hasClaimedRing(card, key, player)","summary":"\"If you have claimed the [element] ring\": whether player has claimed the ring of card's current element for symbol key."},{"file":"helpers.html","page":"Card helpers and queries","id":"he-isRingClaimed","name":"isRingClaimed","signature":"isRingClaimed(card, key)","summary":"\"While the [element] ring is claimed\": whether any player has claimed the ring of card's symbol key."},{"file":"helpers.html","page":"Card helpers and queries","id":"he-captureCost","name":"captureCost","signature":"captureCost(name, capture)","summary":"A free cost that records a value as context.costs[name] while costs are paid. Put it before a cost that changes what you need to remember, such as \"sacrifice this holding\" (which moves the holding out of its province)."},{"file":"helpers.html","page":"Card helpers and queries","id":"he-captureParentCost","name":"captureParentCost capturedParent","signature":"captureParentCost()","summary":"For an attachment that pays \"sacrifice this attachment\" or \"return this attachment to your hand\" and then refers to \"attached character\". captureParentCost() is captureCost('captureParentCost', …) recording context.source.parentCharacter; capturedParent(context) returns the recorded character, or the current parent before the costs are paid."},{"file":"helpers.html","page":"Card helpers and queries","id":"he-giveHonorToTriggerCost","name":"giveHonorToTriggerCost","signature":"giveHonorToTriggerCost(recipient)","summary":"\"As an additional cost to trigger an ability on attached character, its controller must give you 1 honor.\" Pass it to the additionalTriggerCostForCard effect."},{"file":"helpers.html","page":"Card helpers and queries","id":"he-article","name":"article","signature":"article(name)","summary":"'an' if name starts with a vowel (a, e, i, o, u, either case), else 'a'."},{"file":"helpers.html","page":"Card helpers and queries","id":"he-honorTransferMessage","name":"honorTransferMessage","signature":"honorTransferMessage(context, chosen, what)","summary":"The tail of the chat text for \"Each opponent may give you 1 honor and choose a character\": '. {opponent} gives {player} 1 honor to {what(chosen.name)}', or an empty string if the opponent chose nothing."},{"file":"helpers.html","page":"Card helpers and queries","id":"he-createSummonedCopy","name":"createSummonedCopy summonEffectMessage summonEffectArgs BaseOni","signature":"createSummonedCopy","summary":"createSummonedCopy(context, creature) makes a new copy of a creature from outside the game and adds it to game.allCards. summonEffectMessage ('summon {2} {1} from the depths of the Shadowlands!') and summonEffectArgs(creature) are the chat text. BaseOni (in 16-UFLS-Oni/_BaseOni.ts) removes the card from the game whenever it leaves play."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-isParticipating","name":"isParticipating","signature":"card.isParticipating(conflictType?)","summary":"True for a character that is attacking or defending in the current conflict."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-isAttacking","name":"isAttacking isDefending","signature":"card.isAttacking(conflictType?)","summary":"True for a character that is attacking (defending) in the current conflict."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-isParticipatingFor","name":"isParticipatingFor","signature":"card.isParticipatingFor(player)","summary":"True for a character participating on player's side: attacking while player is the attacking player, or defending while player is the defending player. \"A character on the enemy side\" is card.isParticipatingFor(context.player.opponent)."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-isAtHome","name":"isAtHome isInConflict","signature":"card.isAtHome()","summary":"Where the character is: in the conflict, or at home. isAtHome() is !isInConflict()."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-anotherUniqueInPlay","name":"anotherUniqueInPlay","signature":"card.anotherUniqueInPlay(player)","summary":"True if the card is unique and another card with the same printed name is in play, owned or controlled by player, or owned by this card's owner. Use it before taking or giving control of a character."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-hasEveryTrait","name":"hasEveryTrait","signature":"card.hasEveryTrait(...traits)","summary":"True if the card has all of the traits (\"a Fire Spell card\"). Takes trait strings or one Set<string>."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-hasKeyword","name":"hasKeyword","signature":"card.hasKeyword(keyword)","summary":"True if the card currently has the keyword (covert, pride, sincerity, …): printed or gained, and not lost."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-hasSomeTrait","name":"hasSomeTrait","signature":"card.hasSomeTrait(...traits)","summary":"True if the card has at least one of the traits (\"a Scholar or Monk character\"). Takes trait strings or one Set<string>."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-hasTrait","name":"hasTrait","signature":"card.hasTrait(trait)","summary":"True if the card currently has the trait: printed or gained, and not lost."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-getTraits","name":"getTraits","signature":"card.getTraits()","summary":"The card's current traits as a Set<string>: printed, plus gained, minus lost. A new set on each call. They are plain strings, not Trait values; to compare two cards use sharesTrait."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-sharesTrait","name":"sharesTrait","signature":"card.sharesTrait(other)","summary":"Whether this card and other have at least one trait in common now (printed, gained, minus lost)."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-isBlank","name":"isBlank","signature":"card.isBlank()","summary":"True if the card's text box is treated as blank: a blank effect, or a copy effect (copy character, copy province). A province is also blank while it is broken or dishonored."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-isCharacter","name":"isCharacter isDrawCard isProvinceCard","signature":"card.isCharacter()","summary":"Narrow a BaseCard before calling methods that only some cards have. isCharacter() checks the current type (type === CardType.Character) and narrows to DrawCard; isDrawCard() is true for every dynasty and conflict card; isProvinceCard() for province cards."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-isFaction","name":"isFaction","signature":"card.isFaction(faction)","summary":"True if the card belongs to the clan: printed, or gained through an effect, and not lost. A copied character uses the copied card's clan."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-isUnique","name":"isUnique","signature":"card.isUnique()","summary":"True if the card is printed unique."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-costLessThan","name":"costLessThan","signature":"card.costLessThan(num)","summary":"True if the card's printed cost is lower than num. \"printed cost 2 or lower\" is costLessThan(3)."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-getCost","name":"getCost","signature":"card.getCost()","summary":"The card's printed cost, or the printed cost of the character it copies. number | null; null for cards without a cost."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-getFate","name":"getFate","signature":"card.getFate()","summary":"The fate on the card. On a draw card, an effect that sets its apparent fate wins over the real count; other cards always return 0."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-isDire","name":"isDire","signature":"card.isDire()","summary":"True for a draw card with no fate (getFate() === 0); always false for other cards. Dire abilities use the builder's dire(…), which checks this for you."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-militarySkill","name":"militarySkill politicalSkill glory getMilitarySkill getPoliticalSkill","signature":"card.militarySkill","summary":"The current skill and glory, with all modifiers. getMilitarySkill(floor = true) and getPoliticalSkill(floor = true) are the same with the floor as a parameter: with false, a negative total stays negative."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-getBaseMilitarySkill","name":"getBaseMilitarySkill getBasePoliticalSkill","signature":"card.getBaseMilitarySkill()","summary":"The base skill: the printed skill as changed by effects that set or modify base skill (\"double that character's base skill\"), without the other modifiers. Also available as the getters baseMilitarySkill and basePoliticalSkill."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-getMilitarySkillExcludingModifiers","name":"getMilitarySkillExcludingModifiers getPoliticalSkillExcludingModifiers","signature":"card.getMilitarySkillExcludingModifiers(exclusions, floor?)","summary":"The current military (or, with getPoliticalSkillExcludingModifiers, political) skill without some modifiers: \"ignoring the skill modifiers of attachments\"."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-hasDash","name":"hasDash","signature":"card.hasDash(type?)","summary":"True if the character's base skill of type is a dash. Without type, true if either skill is a dash."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-isHonored","name":"isHonored isDishonored isTainted","signature":"card.isHonored","summary":"True if the card has the status token. A token that is treated as another status (Disciple of Deception) counts as the status it grants."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-isOrdinary","name":"isOrdinary","signature":"card.isOrdinary()","summary":"True if the card is neither honored nor dishonored. A tainted character can be ordinary."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-getStatusToken","name":"getStatusToken hasStatusToken","signature":"card.getStatusToken(type)","summary":"The card's status token granting type (CharacterStatus.Honored, Dishonored, Tainted), or undefined; hasStatusToken is the boolean form. Status token game actions (discard, move) take the token as their target."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-getTokenCount","name":"getTokenCount hasToken","signature":"card.getTokenCount(type)","summary":"How many tokens of type (TokenType.Honor, the only type) are on the card; hasToken is true for one or more. These are the honor tokens of holdings and provinces, not status tokens."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-canAttach","name":"canAttach","signature":"card.canAttach(parent, properties?)","summary":"Whether this attachment's own restrictions allow parent: a character, the card is an attachment, and the attachmentConditions (control, unique, faction, trait, card condition) are met. Override it for printed restrictions that attachmentConditions can't express, and call super.canAttach(parent)."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-canBeAttacked","name":"canBeAttacked","signature":"province.canBeAttacked()","summary":"ProvinceCard. True if a conflict could be declared against the province: unbroken, not protected by a \"cannot be attacked\" effect, the opponent can pay its fate cost to attack, and the stronghold province only after 3 other provinces are broken (or an effect allows it)."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-conflictProvinceWithText","name":"conflictProvinceWithText","signature":"province.conflictProvinceWithText()","summary":"ProvinceCard. For \"During conflicts at this province\": the conflict province whose text is this province's (itself, or a province copying it), unless that province's text box is blank. undefined if there is none."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-getCurrentElementSymbol","name":"getCurrentElementSymbol","signature":"card.getCurrentElementSymbol(key)","summary":"The current element of one of the card's printed element symbols. Effects can replace a printed element, so never compare with the printed element directly."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-getElement","name":"getElement isElement","signature":"province.getElement()","summary":"ProvinceCard. The province's current elements (Element[], from its \"province-element\" symbols, or the copied province's), and whether element is one of them."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-getStrength","name":"getStrength","signature":"province.getStrength()","summary":"ProvinceCard. The current strength: base strength, modifiers, and the stronghold or holding bonus, multiplied by multiplier effects, at least 0. A \"set strength\" effect replaces all of it."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-isConflictProvince","name":"isConflictProvince","signature":"province.isConflictProvince()","summary":"True if this province is attacked in the current conflict (the declared one or one added by an effect)."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-isFaceup","name":"isFaceup isFacedown","signature":"card.isFaceup()","summary":"Whether the card is face up or face down."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-isInConflictProvince","name":"isInConflictProvince","signature":"card.isInConflictProvince()","summary":"DrawCard. True if the card is in an attacked province: same location and controller as a province of the current conflict. For \"a dynasty card in the attacked province\" and \"During a conflict at this province\" on holdings."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-isInPlay","name":"isInPlay","signature":"card.isInPlay()","summary":"True if the card is in play: face up, and in the play area, or (for holdings, provinces and strongholds) in a province."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-isInProvince","name":"isInProvince","signature":"card.isInProvince()","summary":"True if the card's location is one of the province locations of the game mode, the stronghold province included. Province cards themselves are in a province too."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-opponent","name":"opponent","signature":"player.opponent","summary":"The other player, Player | undefined."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-player-properties","name":"cardsInPlay hand conflictDeck dynastyDeck conflictDiscardPile dynastyDiscardPile honor fate","signature":"player.cardsInPlay","summary":"The player's piles and counters."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-anyCardsInPlay","name":"anyCardsInPlay filterCardsInPlay getNumberOfCardsInPlay","signature":"player.anyCardsInPlay(predicate)","summary":"\"if you control …\", \"each … you control\", \"for each … you control\": whether any, which, and how many draw cards the player controls in the play area match predicate."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-areLocationsAdjacent","name":"areLocationsAdjacent","signature":"player.areLocationsAdjacent(locationA, locationB)","summary":"True if two province locations are next to each other: province 1 and 2, 2 and 3, 3 and 4."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-getClaimedRings","name":"getClaimedRings","signature":"player.getClaimedRings()","summary":"The rings in the player's claimed ring pool (Ring[]), including rings an effect makes count as claimed by the player."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-getDynastyCardsInProvince","name":"getDynastyCardsInProvince","signature":"player.getDynastyCardsInProvince(location)","summary":"The dynasty cards (not the province card) in one of the player's province locations, face up or face down."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-getProvinceCardInProvince","name":"getProvinceCardInProvince","signature":"player.getProvinceCardInProvince(location)","summary":"The province card in one of the player's province locations, or undefined. A holding finds \"this holding's province\" with getProvinceCardInProvince(context.source.location)."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-getProvinces","name":"getProvinces getProvinceCards","signature":"player.getProvinces(predicate?)","summary":"The player's province cards in all province locations, the stronghold province included; getProvinces keeps those passing predicate."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-getNumberOfFaceupProvinces","name":"getNumberOfFaceupProvinces getNumberOfFacedownProvinces getNumberOfOpponentsFaceupProvinces getNumberOfOpponentsFacedownProvinces","signature":"player.getNumberOfFaceupProvinces(predicate?)","summary":"How many of the player's (or the opponent's) province cards are face up (face down) and pass predicate."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-getNumberOfHoldingsInPlay","name":"getNumberOfHoldingsInPlay getHoldingsInPlay","signature":"player.getNumberOfHoldingsInPlay()","summary":"The face-up holdings in the player's provinces, and how many."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-hasAffinity","name":"hasAffinity","signature":"player.hasAffinity(trait, context?)","summary":"\"With [Trait] affinity\": true if the player controls a character with the trait, or an effect satisfies that affinity, and nothing forbids the player to have affinity."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-hasComposure","name":"hasComposure","signature":"player.hasComposure()","summary":"True if the player's honor bid is lower than the opponent's. Composure abilities use the builder's composure(…), which checks this for you."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-hasDeclaredConflictOfType","name":"hasDeclaredConflictOfType","signature":"player.hasDeclaredConflictOfType(context, conflictType)","summary":"True if the player declared a conflict of that type this round (the record is cleared when the dynasty phase starts)."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-honorGained","name":"honorGained","signature":"player.honorGained(round?, phase?, onlyPositive?)","summary":"The net honor the player gained, from the recorded honor changes."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-isAttackingPlayer","name":"isAttackingPlayer isDefendingPlayer","signature":"player.isAttackingPlayer()","summary":"True if there is a current conflict and the player is its attacking (defending) player. \"While defending\" on a non-character card is context.player.isDefendingPlayer()."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-isCharacterTraitInPlay","name":"isCharacterTraitInPlay","signature":"player.isCharacterTraitInPlay(trait)","summary":"\"if you control a [Trait] character\": true if the player controls a face-up character with the trait in play."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-player-isTraitInPlay","name":"isTraitInPlay","signature":"player.isTraitInPlay(trait)","summary":"True if the player controls a face-up card in play with the trait: a card in the play area (characters and attachments), an unbroken province, or a holding in a province."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-isKihoPlayedThisConflict","name":"isKihoPlayedThisConflict","signature":"player.isKihoPlayedThisConflict(context, cardBeingPlayed)","summary":"\"If you have played another Kihō in this conflict\": true if the player played a Kihō card other than cardBeingPlayed during the current conflict."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-isMoreHonorable","name":"isMoreHonorable isLessHonorable","signature":"player.isMoreHonorable()","summary":"\"While you are more (less) honorable than an opponent\": compares the honor totals; an effect that makes a player \"considered less honorable\" wins over the totals."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-moveCard","name":"moveCard shuffleConflictDeck shuffleDynastyDeck","signature":"player.moveCard(card, location)","summary":"Move a card between piles directly, and shuffle a deck. Not queries, but they appear in many handlers."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-addMessage","name":"addMessage","signature":"game.addMessage(message)","summary":"Writes a line to the game chat. Pass a msg tagged template (cards, players and rings in it become links), or a format string with {0}, {1} and the arguments after it."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-currentConflict","name":"currentConflict requireConflict","signature":"game.currentConflict","summary":"The conflict being resolved: Conflict | null. requireConflict() returns it, or throws if there is none."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-findAnyCardsInPlay","name":"findAnyCardsInPlay","signature":"game.findAnyCardsInPlay(predicate)","summary":"\"each character …\": the cards in every player's cardsInPlay, and the attachments on them, that match predicate."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-getConflicts","name":"getConflicts","signature":"game.getConflicts(player)","summary":"The conflicts declared this round by player (or by anyone with Players.All), as records: attackingPlayer, declaredType, passed, uuid, completed, winner, typeSwitched, brokenProvinces."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-getDeclaredConflictCount","name":"getDeclaredConflictCount","signature":"game.getDeclaredConflictCount(player)","summary":"How many conflicts player declared this round. Passed conflict opportunities don't count."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-getFavorSide","name":"getFavorSide","signature":"game.getFavorSide()","summary":"The side of the Imperial Favor ('military', 'political' or 'both', see FavorType), or undefined if no player has it."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-getFirstPlayer","name":"getFirstPlayer","signature":"game.getFirstPlayer()","summary":"The first player, or undefined before one is chosen."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-getPlayers","name":"getPlayers","signature":"game.getPlayers()","summary":"The players (spectators excluded), for \"each player\"."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-getProvinceArray","name":"getProvinceArray","signature":"game.getProvinceArray(includeStronghold?)","summary":"The province locations of the game mode (Location[]): provinces one to four, and the stronghold province if the mode has strongholds and includeStronghold is true (the default)."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-isDuringConflict","name":"isDuringConflict","signature":"game.isDuringConflict(types?)","summary":"\"During a conflict\", \"During [conflict-military] conflicts\", \"During an [element-air] conflict\": true if a conflict is in progress and it matches every type and element given."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-game-isTraitInPlay","name":"isTraitInPlay","signature":"game.isTraitInPlay(trait)","summary":"\"if there is a [Trait] in play\": player.isTraitInPlay(trait) for any player."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-promptWithHandlerMenu","name":"promptWithHandlerMenu promptForSelect promptForRingSelect","signature":"game.promptWithHandlerMenu(player, properties)","summary":"Ask a player inside a .handler(…): a menu of buttons and cards, a card selection on the board, or a ring selection. Prefer the builder's targets, selectFrom and the cardMenu and selectCard game actions, which handle legality and chat; use these prompts for multi-step choices that don't fit."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-queueSimpleStep","name":"queueSimpleStep","signature":"game.queueSimpleStep(handler)","summary":"Runs handler as a later step of the game pipeline, after the steps already queued (open prompts, event windows)."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-ringFor","name":"ringFor rings","signature":"game.rings","summary":"game.rings maps each Element to its Ring. ringFor(element) takes any string and returns the ring, or undefined if the string is not an element (for example a role trait)."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-calculateSkillFor","name":"calculateSkillFor","signature":"conflict.calculateSkillFor(cards)","summary":"The skill cards contribute to the conflict: each card's contribution for the conflict type, without bowed characters (unless they may contribute while bowed) and characters that cannot contribute."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-getAttackers","name":"getAttackers getDefenders","signature":"conflict.getAttackers(predicate?)","summary":"\"each attacking character\", \"each defending character\": the attacking (defending) characters that match predicate, including characters that participate from home on that side."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-getCharacters","name":"getCharacters","signature":"conflict.getCharacters(player)","summary":"\"each character on your side\": the attackers if player is the attacking player, else the defenders."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-getConflictProvinces","name":"getConflictProvinces","signature":"conflict.getConflictProvinces()","summary":"The attacked provinces: the conflict province first, then provinces an effect added (\"The conflict is also at that province\"). [] if the conflict has no province."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-brokenProvinces","name":"brokenProvinces attackersAtResolution defendersAtResolution","signature":"conflict.brokenProvinces","summary":"What happened in a conflict, kept on the Conflict so a card needs no state of its own: the provinces broken while it was the current conflict, and the characters attacking and defending when the winner was determined."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-getWinningPlayer","name":"getWinningPlayer","signature":"conflict.getWinningPlayer()","summary":"The player who wins the conflict at the current skills, or undefined if nobody does. conflict.winner is set from it when the conflict resolves."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-getNumberOfCardsPlayed","name":"getNumberOfCardsPlayed getCardsPlayed","signature":"conflict.getNumberOfCardsPlayed(player, predicate?)","summary":"The cards player played during this conflict (as snapshots), and how many."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-getNumberOfParticipantsFor","name":"getNumberOfParticipantsFor","signature":"conflict.getNumberOfParticipantsFor(player, predicate?)","summary":"How many characters participate on one side. \"attacking alone\" is getNumberOfParticipantsFor('attacker') === 1."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-getParticipants","name":"getParticipants getNumberOfParticipants","signature":"conflict.getParticipants(predicate?)","summary":"All participating characters, attackers then defenders, filtered by predicate; and how many match."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-hasMoreParticipants","name":"hasMoreParticipants","signature":"conflict.hasMoreParticipants(player, predicate?)","summary":"\"more participating characters than your opponent\": true if player's side has more participants than the opponent's."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-conflict-hasElement","name":"hasElement","signature":"conflict.hasElement(element)","summary":"True if the conflict's ring has the element (conflict.elements, gained elements included). false without a ring."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-isAtStrongholdProvince","name":"isAtStrongholdProvince","signature":"conflict.isAtStrongholdProvince()","summary":"True if one of the conflict's provinces is in the stronghold province location."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-canDeclare","name":"canDeclare","signature":"ring.canDeclare(player)","summary":"True if player could declare a conflict with this ring: not claimed, not removed from the game, and no effect forbids it."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-getElements","name":"getElements","signature":"ring.getElements()","summary":"The ring's current elements: its own, those added by effects, and while it is contested, those the attackers add."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-ring-getFate","name":"getFate fate","signature":"ring.getFate()","summary":"The fate on the ring. Both forms read the same value."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-ring-hasElement","name":"hasElement","signature":"ring.hasElement(element)","summary":"True if element is one of getElements(). Compare with ring.element only for the ring's own element."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-isConflictType","name":"isConflictType","signature":"ring.isConflictType(type)","summary":"True if the ring's current conflict type is type (\"a [conflict-military] ring in your claimed ring pool\")."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-isConsideredClaimed","name":"isConsideredClaimed","signature":"ring.isConsideredClaimed(player?)","summary":"True if player claimed the ring or an effect makes it count as claimed by player. Without player, true if that holds for any player. Use it for \"in your claimed ring pool\"."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-isUnclaimed","name":"isUnclaimed","signature":"ring.isUnclaimed()","summary":"True if the ring is in the unclaimed pool: not contested, not claimed, not removed from the game."},{"file":"helpers.html","page":"Card helpers and queries","id":"q-isClaimed","name":"isClaimed isContested isRemovedFromGame","signature":"ring.isClaimed()","summary":"The ring's state flags: in a claimed ring pool (by anyone), contested in the current conflict, removed from the game."},{"file":"helpers.html","page":"Card helpers and queries","id":"he-helpers","name":"","signature":"Shared card helpers","summary":"Some cards share most of their implementation: the province attachments, the mantras, the cards that search for an attachment, the cards with a \"claimed ring\" symbol. The shared parts live in the modules directly in server/game/cards/ (not in a set folder). Import them with '../name.js' from a set folder such as 01-Core/, and with '../../name.js' from a clan folder such as 20-Core2/Crab/.","section":true},{"file":"helpers.html","page":"Card helpers and queries","id":"q-queries","name":"","signature":"Queries","summary":"Conditions and callbacks ask the game about its state: is this character participating, is the player more honorable, is the ring claimed. These are the methods card abilities call most often, counted over all card files and grouped by the object they are called on. You reach the objects from the context: context.source (the card), context.player and context.player.opponent, context.game, context.game.currentConflict, and in triggers event.card, event.conflict, event.ring.","section":true}];
